INSERT INTO exam.questions (question_id, question_type, title, body, created_at, difficulty, created_by, allow_multiple, weight_bb, weight_wb, structural_rules, grace_mode, grace_threshold, grace_cap) VALUES (1, 'programming', 'Temperature Scale Converter', 'Write a function `double convertTemperature(double temp, char scale)` that converts temperature between Celsius and Fahrenheit. If scale is ''C'', convert temp from Fahrenheit to Celsius. If scale is ''F'', convert temp from Celsius to Fahrenheit. Return the converted temperature.', '2026-07-20 10:36:40.075617+00', 'easy', 7, false, 0.80, 0.20, '[]', 'STANDARD', 0.90, 0.15);
INSERT INTO exam.questions (question_id, question_type, title, body, created_at, difficulty, created_by, allow_multiple, weight_bb, weight_wb, structural_rules, grace_mode, grace_threshold, grace_cap) VALUES (2, 'programming', 'Basic Sign Classifier Vector', 'Write a function `std::vector<int> classifySigns(const std::vector<int>& numbers)` that returns a new vector where positive numbers are replaced by 1, negative numbers by -1, and zeros remain 0.', '2026-07-20 10:36:40.075617+00', 'easy', 7, false, 0.80, 0.20, '[]', 'STANDARD', 0.90, 0.15);
INSERT INTO exam.questions (question_id, question_type, title, body, created_at, difficulty, created_by, allow_multiple, weight_bb, weight_wb, structural_rules, grace_mode, grace_threshold, grace_cap) VALUES (4, 'programming', 'First Node Sign Checker', 'Given the head of a linked list, return 1 if the head node data is positive, -1 if negative, and 0 if it is 0 or if the list is nullptr.', '2026-07-20 10:36:40.075617+00', 'easy', 7, false, 0.80, 0.20, '[]', 'STANDARD', 0.90, 0.15);
INSERT INTO exam.questions (question_id, question_type, title, body, created_at, difficulty, created_by, allow_multiple, weight_bb, weight_wb, structural_rules, grace_mode, grace_threshold, grace_cap) VALUES (5, 'programming', 'Leap Year Evaluator', 'Write a complete C++ program that reads an integer year from standard input and prints "LEAP" if the year is a leap year, or "COMMON" otherwise. A year is leap if it is divisible by 4, except for end-of-century years which must be divisible by 400.', '2026-07-20 10:36:40.075617+00', 'easy', 7, false, 0.80, 0.20, '[]', 'STANDARD', 0.90, 0.15);
INSERT INTO exam.questions (question_id, question_type, title, body, created_at, difficulty, created_by, allow_multiple, weight_bb, weight_wb, structural_rules, grace_mode, grace_threshold, grace_cap) VALUES (6, 'programming', 'Tax Bracket Calculator', 'Write a function `double calculateTax(double income)` that computes income tax using progressive brackets: 0% up to 10000, 10% for 10001-40000, 20% for 40001-80000, and 30% for amounts above 80000. Return total tax formatted rounded to 2 decimal places.', '2026-07-20 10:36:40.075617+00', 'medium', 7, false, 0.80, 0.20, '[]', 'STANDARD', 0.90, 0.15);
INSERT INTO exam.questions (question_id, question_type, title, body, created_at, difficulty, created_by, allow_multiple, weight_bb, weight_wb, structural_rules, grace_mode, grace_threshold, grace_cap) VALUES (7, 'programming', 'Conditional Multi-State Flag Classifier', 'Write a function `std::vector<int> processFlags(const std::vector<int>& values)` that maps each integer: if divisible by 3 and 5 return 35, else if divisible by 3 return 3, else if divisible by 5 return 5, else return the value itself.', '2026-07-20 10:36:40.075617+00', 'medium', 7, false, 0.80, 0.20, '[]', 'STANDARD', 0.90, 0.15);
INSERT INTO exam.questions (question_id, question_type, title, body, created_at, difficulty, created_by, allow_multiple, weight_bb, weight_wb, structural_rules, grace_mode, grace_threshold, grace_cap) VALUES (8, 'programming', 'Grid Boundary Validity Check', 'Write a function `std::vector<std::vector<int>> checkBoundaryStatus(const std::vector<std::vector<int>>& grid)` that marks elements in a grid: return a grid of same shape where boundary cells keep their original values and interior cells are replaced with -1 if positive, -2 if negative, or 0.', '2026-07-20 10:36:40.075617+00', 'medium', 7, false, 0.80, 0.20, '[]', 'STANDARD', 0.90, 0.15);
INSERT INTO exam.questions (question_id, question_type, title, body, created_at, difficulty, created_by, allow_multiple, weight_bb, weight_wb, structural_rules, grace_mode, grace_threshold, grace_cap) VALUES (9, 'programming', 'Two-Node Order Check', 'Write a function `int evaluateFirstTwoNodes(Node* head)` that inspects the first two nodes of a list. Return 1 if first > second, -1 if first < second, 0 if equal, and -99 if fewer than two nodes exist.', '2026-07-20 10:36:40.075617+00', 'medium', 7, false, 0.80, 0.20, '[]', 'STANDARD', 0.90, 0.15);
INSERT INTO exam.questions (question_id, question_type, title, body, created_at, difficulty, created_by, allow_multiple, weight_bb, weight_wb, structural_rules, grace_mode, grace_threshold, grace_cap) VALUES (10, 'programming', 'Valid Date Identifier', 'Write a full program that reads three integers (day, month, year) from stdin and prints "VALID" if they represent a valid calendar date (accounting for leap years in February) or "INVALID" otherwise.', '2026-07-20 10:36:40.075617+00', 'medium', 7, false, 0.80, 0.20, '[]', 'STANDARD', 0.90, 0.15);
INSERT INTO exam.questions (question_id, question_type, title, body, created_at, difficulty, created_by, allow_multiple, weight_bb, weight_wb, structural_rules, grace_mode, grace_threshold, grace_cap) VALUES (11, 'programming', 'Complex Bitwise State Resolver', 'Write a function `int resolveState(int flags, int mask, int trigger)` that evaluates bitwise logic: if (flags & mask) equals mask and trigger bit (1 << trigger) is set, return (flags ^ mask); if only mask condition holds, return (flags | mask); otherwise return ~flags.', '2026-07-20 10:36:40.075617+00', 'hard', 7, false, 0.80, 0.20, '[]', 'STANDARD', 0.90, 0.15);
INSERT INTO exam.questions (question_id, question_type, title, body, created_at, difficulty, created_by, allow_multiple, weight_bb, weight_wb, structural_rules, grace_mode, grace_threshold, grace_cap) VALUES (12, 'programming', 'Nested Logical Conditional Pipeline', 'Write a function `std::vector<int> pipelineTransform(const std::vector<int>& vec, int threshold)` that transforms each element x: if x > threshold and x is even, x = x / 2; if x > threshold and x is odd, x = x * 3 + 1; if x <= threshold and x is negative, x = -x; else x remains unchanged.', '2026-07-20 10:36:40.075617+00', 'hard', 7, false, 0.80, 0.20, '[]', 'STANDARD', 0.90, 0.15);
INSERT INTO exam.questions (question_id, question_type, title, body, created_at, difficulty, created_by, allow_multiple, weight_bb, weight_wb, structural_rules, grace_mode, grace_threshold, grace_cap) VALUES (13, 'programming', 'Saddle Cell Classifier', 'Write a function `std::vector<std::vector<int>> evaluateSaddlePositions(const std::vector<std::vector<int>>& grid)` that returns a grid of same dimensions where cell (i,j) is 1 if grid[i][j] is strictly greater than all horizontal neighbors and strictly smaller than all vertical neighbors, else 0. (Corner/edge cells compare against existing neighbors only).', '2026-07-20 10:36:40.075617+00', 'hard', 7, false, 0.80, 0.20, '[]', 'STANDARD', 0.90, 0.15);
INSERT INTO exam.questions (question_id, question_type, title, body, created_at, difficulty, created_by, allow_multiple, weight_bb, weight_wb, structural_rules, grace_mode, grace_threshold, grace_cap) VALUES (14, 'programming', 'Triple Node Conditional Pattern', 'Write a function `bool verifyTriplePattern(Node* head)` that returns true if the first three nodes follow the strict relationship A < B and B > C, or A > B and B < C. If fewer than three nodes exist, return false.', '2026-07-20 10:36:40.075617+00', 'hard', 7, false, 0.80, 0.20, '[]', 'STANDARD', 0.90, 0.15);
INSERT INTO exam.questions (question_id, question_type, title, body, created_at, difficulty, created_by, allow_multiple, weight_bb, weight_wb, structural_rules, grace_mode, grace_threshold, grace_cap) VALUES (15, 'programming', 'Interval Intersection Calculator', 'Write a full program that reads four integers representing two closed 1D intervals [a, b] and [c, d] from stdin. Print the intersection interval as "x y" if they overlap, or "NONE" if they do not overlap. (Assume input intervals are valid with a <= b and c <= d).', '2026-07-20 10:36:40.075617+00', 'hard', 7, false, 0.80, 0.20, '[]', 'STANDARD', 0.90, 0.15);
INSERT INTO exam.questions (question_id, question_type, title, body, created_at, difficulty, created_by, allow_multiple, weight_bb, weight_wb, structural_rules, grace_mode, grace_threshold, grace_cap) VALUES (16, 'programming', 'Factorial Computation', 'Write a function `long long computeFactorial(int n)` that computes and returns n! (n factorial) using an iterative loop. Return 1 for n = 0.', '2026-07-20 10:36:40.075617+00', 'easy', 7, false, 0.80, 0.20, '[]', 'STANDARD', 0.90, 0.15);
INSERT INTO exam.questions (question_id, question_type, title, body, created_at, difficulty, created_by, allow_multiple, weight_bb, weight_wb, structural_rules, grace_mode, grace_threshold, grace_cap) VALUES (17, 'programming', 'Element Frequency Counter', 'Write a function `int countOccurrences(const std::vector<int>& vec, int target)` that uses a loop to return how many times target appears in the vector.', '2026-07-20 10:36:40.075617+00', 'easy', 7, false, 0.80, 0.20, '[]', 'STANDARD', 0.90, 0.15);
INSERT INTO exam.questions (question_id, question_type, title, body, created_at, difficulty, created_by, allow_multiple, weight_bb, weight_wb, structural_rules, grace_mode, grace_threshold, grace_cap) VALUES (18, 'programming', 'Grid Summation', 'Write a function `int sumGridElements(const std::vector<std::vector<int>>& grid)` that iterates through all elements of a 2D vector using nested loops and returns their sum.', '2026-07-20 10:36:40.075617+00', 'easy', 7, false, 0.80, 0.20, '[]', 'STANDARD', 0.90, 0.15);
INSERT INTO exam.questions (question_id, question_type, title, body, created_at, difficulty, created_by, allow_multiple, weight_bb, weight_wb, structural_rules, grace_mode, grace_threshold, grace_cap) VALUES (19, 'programming', 'Iterative List Length', 'Write a function `int getLinkedListLength(Node* head)` that uses a while loop to count and return the total number of nodes in a linked list.', '2026-07-20 10:36:40.075617+00', 'easy', 7, false, 0.80, 0.20, '[]', 'STANDARD', 0.90, 0.15);
INSERT INTO exam.questions (question_id, question_type, title, body, created_at, difficulty, created_by, allow_multiple, weight_bb, weight_wb, structural_rules, grace_mode, grace_threshold, grace_cap) VALUES (20, 'programming', 'Sum of N Positive Integers', 'Write a full program that reads an integer N from standard input, followed by N integers. Compute and print the sum of all positive integers in the input sequence.', '2026-07-20 10:36:40.075617+00', 'easy', 7, false, 0.80, 0.20, '[]', 'STANDARD', 0.90, 0.15);
INSERT INTO exam.questions (question_id, question_type, title, body, created_at, difficulty, created_by, allow_multiple, weight_bb, weight_wb, structural_rules, grace_mode, grace_threshold, grace_cap) VALUES (21, 'programming', 'Collatz Sequence Step Counter', 'Write a function `int countCollatzSteps(int n)` that calculates the number of steps required to reach 1 using the Collatz conjecture: if n is even, divide by 2; if odd, multiply by 3 and add 1. Return 0 if n is 1 or less.', '2026-07-20 10:38:09.337739+00', 'medium', 7, false, 0.80, 0.20, '[]', 'STANDARD', 0.90, 0.15);
INSERT INTO exam.questions (question_id, question_type, title, body, created_at, difficulty, created_by, allow_multiple, weight_bb, weight_wb, structural_rules, grace_mode, grace_threshold, grace_cap) VALUES (22, 'programming', 'Longest Consecutive Monotonic Subsegment', 'Write a function `int longestNonDecreasingRun(const std::vector<int>& nums)` that uses iteration to find and return the length of the longest contiguous subsegment where elements are non-decreasing. Return 0 if the vector is empty.', '2026-07-20 10:38:09.337739+00', 'medium', 7, false, 0.80, 0.20, '[]', 'STANDARD', 0.90, 0.15);
INSERT INTO exam.questions (question_id, question_type, title, body, created_at, difficulty, created_by, allow_multiple, weight_bb, weight_wb, structural_rules, grace_mode, grace_threshold, grace_cap) VALUES (23, 'programming', 'Spiral Row Sum Accumulator', 'Write a function `std::vector<int> computeRowAlternatingSums(const std::vector<std::vector<int>>& grid)` that computes for each row the sum formed by adding even-indexed elements and subtracting odd-indexed elements.', '2026-07-20 10:38:09.337739+00', 'medium', 7, false, 0.80, 0.20, '[]', 'STANDARD', 0.90, 0.15);
INSERT INTO exam.questions (question_id, question_type, title, body, created_at, difficulty, created_by, allow_multiple, weight_bb, weight_wb, structural_rules, grace_mode, grace_threshold, grace_cap) VALUES (24, 'programming', 'Find Middle Node Data', 'Write a function `int getMiddleNodeData(Node* head)` that uses a two-pointer iteration approach (slow/fast) to return the data of the middle node. If the list has an even number of nodes, return the data of the second middle node. Return -1 if list is empty.', '2026-07-20 10:38:09.337739+00', 'medium', 7, false, 0.80, 0.20, '[]', 'STANDARD', 0.90, 0.15);
INSERT INTO exam.questions (question_id, question_type, title, body, created_at, difficulty, created_by, allow_multiple, weight_bb, weight_wb, structural_rules, grace_mode, grace_threshold, grace_cap) VALUES (25, 'programming', 'Prime Factor Printer', 'Write a complete program that reads an integer N (> 1) from stdin and prints its prime factors in ascending order separated by single spaces.', '2026-07-20 10:38:09.337739+00', 'medium', 7, false, 0.80, 0.20, '[]', 'STANDARD', 0.90, 0.15);
INSERT INTO exam.questions (question_id, question_type, title, body, created_at, difficulty, created_by, allow_multiple, weight_bb, weight_wb, structural_rules, grace_mode, grace_threshold, grace_cap) VALUES (26, 'programming', 'Digital Root Calculation', 'Write a function `int calculateDigitalRoot(long long n)` that repeatedly sums the digits of n iteratively until a single-digit number is produced. Return that single digit.', '2026-07-20 10:38:09.337739+00', 'hard', 7, false, 0.80, 0.20, '[]', 'STANDARD', 0.90, 0.15);
INSERT INTO exam.questions (question_id, question_type, title, body, created_at, difficulty, created_by, allow_multiple, weight_bb, weight_wb, structural_rules, grace_mode, grace_threshold, grace_cap) VALUES (27, 'programming', 'Maximum Subarray Sum (Kadane)', 'Write a function `int maxSubarraySum(const std::vector<int>& nums)` that uses Kadane''s iterative algorithm to compute and return the maximum contiguous subarray sum. If vector is empty, return 0.', '2026-07-20 10:38:09.337739+00', 'hard', 7, false, 0.80, 0.20, '[]', 'STANDARD', 0.90, 0.15);
INSERT INTO exam.questions (question_id, question_type, title, body, created_at, difficulty, created_by, allow_multiple, weight_bb, weight_wb, structural_rules, grace_mode, grace_threshold, grace_cap) VALUES (28, 'programming', 'Spiral Matrix Order Traverse', 'Write a function `std::vector<int> spiralTraversal(const std::vector<std::vector<int>>& matrix)` that uses loops to traverse an m x n matrix in spiral order and returns all elements in a single 1D vector.', '2026-07-20 10:38:09.337739+00', 'hard', 7, false, 0.80, 0.20, '[]', 'STANDARD', 0.90, 0.15);
INSERT INTO exam.questions (question_id, question_type, title, body, created_at, difficulty, created_by, allow_multiple, weight_bb, weight_wb, structural_rules, grace_mode, grace_threshold, grace_cap) VALUES (29, 'programming', 'In-Place Iterative List Reversal', 'Write a function `Node* reverseLinkedList(Node* head)` that iteratively reverses a singly linked list in-place and returns the new head pointer.', '2026-07-20 10:38:09.337739+00', 'hard', 7, false, 0.80, 0.20, '[]', 'STANDARD', 0.90, 0.15);
INSERT INTO exam.questions (question_id, question_type, title, body, created_at, difficulty, created_by, allow_multiple, weight_bb, weight_wb, structural_rules, grace_mode, grace_threshold, grace_cap) VALUES (30, 'programming', 'Pattern Printing Hourglass', 'Write a full program that reads an odd integer N (N >= 3) from standard input and prints an hourglass pattern using asterisk characters (`*`).', '2026-07-20 10:38:09.337739+00', 'hard', 7, false, 0.80, 0.20, '[]', 'STANDARD', 0.90, 0.15);
