INSERT INTO exam.questions (question_id, question_type, title, body, created_at, difficulty, created_by, allow_multiple, weight_bb, weight_wb, structural_rules, grace_mode, grace_threshold, grace_cap) VALUES (41, 'programming', 'Stateful Counter with Function Pointers', 'Write a function `int executeOp(int a, int b, int (*op)(int, int))` that applies the function pointer `op` to `a` and `b`, but keeps track of how many total operations were executed using a static internal variable. If `op` is nullptr, return -1 without incrementing the counter. Return the operation result.', '2026-07-20 10:39:13.715+00', 'hard', 7, false, 0.80, 0.20, '[]', 'STANDARD', 0.90, 0.15);
