INSERT INTO exam.programming_questions (question_id, starter_code, test_cases, boilerplate_code, cpu_time_limit, memory_limit, category, function_signature, language_id, reference_solution, helper_code) VALUES (94, 'struct Node {
    int data;
    Node* next;
};

class LinkedListWrapper {
private:
    Node* head;
public:
    LinkedListWrapper() : head(nullptr) {}
    void append(int val) {}
    int getHeadVal() const { return -1; }
};', '[{"input": "append(10), getHeadVal()", "weight": 0.3, "category": "SANITY", "expected_output": "10"}, {"input": "getHeadVal()", "weight": 0.4, "category": "FUNCTIONAL", "expected_output": "-1"}, {"input": "append(5), append(20), getHeadVal()", "weight": 0.3, "category": "EDGE", "expected_output": "5"}]', NULL, 2, 128000, 'CUSTOM', '
    LinkedListWrapper()', 54, 'struct Node {
    int data;
    Node* next;
};

class LinkedListWrapper {
private:
    Node* head;
public:
    LinkedListWrapper() : head(nullptr) {}
    void append(int val) {
        Node* newNode = new Node{val, nullptr};
        if (head == nullptr) {
            head = newNode;
            return;
        }
        Node* curr = head;
        while (curr->next != nullptr) {
            curr = curr->next;
        }
        curr->next = newNode;
    }
    int getHeadVal() const {
        if (head == nullptr) return -1;
        return head->data;
    }
};', NULL);
INSERT INTO exam.programming_questions (question_id, starter_code, test_cases, boilerplate_code, cpu_time_limit, memory_limit, category, function_signature, language_id, reference_solution, helper_code) VALUES (106, '#include <vector>
#include <unordered_set>

bool containsElement(const std::vector<int>& vec, int target) {
    return false;
}', '[{"input": "[1, 3, 5, 7], 5", "weight": 0.3, "category": "SANITY", "is_canary": true, "is_public": false, "expected_output": "true"}, {"input": "[1, 2, 3], 10", "weight": 0.4, "category": "FUNCTIONAL", "expected_output": "false"}, {"input": "[], 1", "weight": 0.3, "category": "EDGE", "expected_output": "false"}]', NULL, 2, 128000, 'SCALAR', 'bool containsElement(const std::vector<int>& vec, int target)', 54, '#include <vector>
#include <unordered_set>

bool containsElement(const std::vector<int>& vec, int target) {
    std::unordered_set<int> s(vec.begin(), vec.end());
    return s.find(target) != s.end();
}', NULL);
INSERT INTO exam.programming_questions (question_id, starter_code, test_cases, boilerplate_code, cpu_time_limit, memory_limit, category, function_signature, language_id, reference_solution, helper_code) VALUES (38, '#include <vector>

void accumulateGridStats(const std::vector<std::vector<int>>& grid, int& totalSum, int& maxVal) {
}', '[{"input": "[[1, 5], [3, 2]], 0, 0", "weight": 0.3, "category": "SANITY", "expected_output": "[[1, 5], [3, 2]] 11 5"}, {"input": "[[-1, -5]], 0, 0", "weight": 0.4, "category": "FUNCTIONAL", "expected_output": "[[-1, -5]] -6 -1"}, {"input": "[], 0, 0", "weight": 0.3, "category": "EDGE", "expected_output": "[] 0 0"}]', NULL, 2, 128000, 'CUSTOM', 'void accumulateGridStats(const std::vector<std::vector<int>>& grid, int& totalSum, int& maxVal)', 54, '#include <vector>
#include <algorithm>

void accumulateGridStats(const std::vector<std::vector<int>>& grid, int& totalSum, int& maxVal) {
    totalSum = 0;
    if (grid.empty() || grid[0].empty()) {
        maxVal = 0;
        return;
    }
    maxVal = grid[0][0];
    for (const auto& row : grid) {
        for (int val : row) {
            totalSum += val;
            maxVal = std::max(maxVal, val);
        }
    }
}', NULL);
INSERT INTO exam.programming_questions (question_id, starter_code, test_cases, boilerplate_code, cpu_time_limit, memory_limit, category, function_signature, language_id, reference_solution, helper_code) VALUES (62, '#include <iostream>

