INSERT INTO exam.programming_questions (question_id, starter_code, test_cases, boilerplate_code, cpu_time_limit, memory_limit, category, function_signature, language_id, reference_solution, helper_code) VALUES (63, '#include <iostream>

int sumRawMatrix(int** matrix, int rows, int cols) {
    return 0;
}', '[{"input": "[[1, 2], [3, 4]], 2, 2", "weight": 0.3, "category": "SANITY", "expected_output": "10"}, {"input": "[[5]], 1, 1", "weight": 0.4, "category": "FUNCTIONAL", "expected_output": "5"}, {"input": "nullptr, 0, 0", "weight": 0.3, "category": "EDGE", "expected_output": "0"}]', NULL, 2, 128000, 'CUSTOM', 'int sumRawMatrix(int** matrix, int rows, int cols)', 54, '#include <iostream>

int sumRawMatrix(int** matrix, int rows, int cols) {
    if (matrix == nullptr || rows <= 0 || cols <= 0) return 0;
    int sum = 0;
    for (int r = 0; r < rows; ++r) {
        if (matrix[r] == nullptr) continue;
        for (int c = 0; c < cols; ++c) {
            sum += matrix[r][c];
        }
    }
    return sum;
}', NULL);
INSERT INTO exam.programming_questions (question_id, starter_code, test_cases, boilerplate_code, cpu_time_limit, memory_limit, category, function_signature, language_id, reference_solution, helper_code) VALUES (67, '#include <iostream>

int* filterEvenNumbers(const int* arr, int size, int& newSize) {
    return nullptr;
}', '[{"input": "[1, 2, 3, 4, 5], 5", "weight": 0.3, "category": "SANITY", "expected_output": "[2, 4], size=2"}, {"input": "[1, 3, 5], 3", "weight": 0.4, "category": "FUNCTIONAL", "expected_output": "nullptr, size=0"}, {"input": "nullptr, 0", "weight": 0.3, "category": "EDGE", "expected_output": "nullptr, size=0"}]', NULL, 2, 128000, 'CUSTOM', 'int* filterEvenNumbers(const int* arr, int size, int& newSize)', 54, '#include <iostream>

int* filterEvenNumbers(const int* arr, int size, int& newSize) {
    if (arr == nullptr || size <= 0) {
        newSize = 0;
        return nullptr;
    }
    int count = 0;
    for (int i = 0; i < size; ++i) {
        if (arr[i] % 2 == 0) count++;
    }
    newSize = count;
    if (count == 0) return nullptr;

    int* result = new int[count];
    int idx = 0;
    for (int i = 0; i < size; ++i) {
        if (arr[i] % 2 == 0) {
            result[idx++] = arr[i];
        }
    }
    return result;
}', NULL);
INSERT INTO exam.programming_questions (question_id, starter_code, test_cases, boilerplate_code, cpu_time_limit, memory_limit, category, function_signature, language_id, reference_solution, helper_code) VALUES (68, '#include <iostream>

int** allocateMatrix(int rows, int cols, int initialVal) {
    return nullptr;
}

void freeMatrix(int** matrix, int rows) {
}', '[{"input": "2, 3, 9", "weight": 0.3, "category": "SANITY", "expected_output": "[[9, 9, 9], [9, 9, 9]]"}, {"input": "1, 1, 0", "weight": 0.4, "category": "FUNCTIONAL", "expected_output": "[[0]]"}, {"input": "0, 0, 0", "weight": 0.3, "category": "EDGE", "expected_output": "nullptr"}]', NULL, 2, 128000, 'CUSTOM', 'int** allocateMatrix(int rows, int cols, int initialVal)', 54, '#include <iostream>

int** allocateMatrix(int rows, int cols, int initialVal) {
    if (rows <= 0 || cols <= 0) return nullptr;
    int** matrix = new int*[rows];
    for (int r = 0; r < rows; ++r) {
        matrix[r] = new int[cols];
        for (int c = 0; c < cols; ++c) {
            matrix[r][c] = initialVal;
        }
    }
    return matrix;
}

void freeMatrix(int** matrix, int rows) {
    if (matrix == nullptr) return;
    for (int r = 0; r < rows; ++r) {
        delete[] matrix[r];
    }
    delete[] matrix;
}', NULL);
