    return nullptr;
}', '[{"input": "\"hello world\", pos 0 to 5", "weight": 0.3, "category": "SANITY", "expected_output": "\"hello\""}, {"input": "\"cpp\", pos 1 to 1", "weight": 0.4, "category": "FUNCTIONAL", "expected_output": "\"\""}, {"input": "nullptr, nullptr", "weight": 0.3, "category": "EDGE", "expected_output": "nullptr"}]', NULL, 2, 128000, 'CUSTOM', 'char* extractSubstrPointer(const char* start, const char* end)', 54, '#include <iostream>
#include <cstring>

char* extractSubstrPointer(const char* start, const char* end) {
    if (start == nullptr || end == nullptr || start > end) return nullptr;
    std::ptrdiff_t len = end - start;
    char* sub = new char[len + 1];
    std::strncpy(sub, start, len);
    sub[len] = ''\0'';
    return sub;
}', NULL);
