INSERT INTO exam.programming_questions (question_id, starter_code, test_cases, boilerplate_code, cpu_time_limit, memory_limit, category, function_signature, language_id, reference_solution, helper_code) VALUES (116, '#include <unordered_map>
#include <list>

class LRUCache {
public:
    LRUCache(int capacity) {}
    int get(int key) { return -1; }
    void put(int key, int value) {}
};', '[{"input": "cap=2, put(1,1), put(2,2), get(1), put(3,3), get(2)", "weight": 0.3, "category": "SANITY", "expected_output": "get(1)=1, get(2)=-1"}, {"input": "get non-existent", "weight": 0.4, "category": "FUNCTIONAL", "expected_output": "-1"}, {"input": "put update existing key", "weight": 0.3, "category": "EDGE", "expected_output": "updated value returned"}]', NULL, 2, 128000, 'CUSTOM', 'int main()', 54, '#include <unordered_map>
#include <list>

class LRUCache {
private:
    int cap;
    std::list<std::pair<int, int>> cache;
    std::unordered_map<int, std::list<std::pair<int, int>>::iterator> map;
public:
    LRUCache(int capacity) : cap(capacity) {}

    int get(int key) {
        if (!map.count(key)) return -1;
        cache.splice(cache.begin(), cache, map[key]);
        return map[key]->second;
    }

    void put(int key, int value) {
        if (map.count(key)) {
            map[key]->second = value;
            cache.splice(cache.begin(), cache, map[key]);
            return;
        }
        if (static_cast<int>(cache.size()) == cap) {
            int delKey = cache.back().first;
            cache.pop_back();
            map.erase(delKey);
        }
        cache.push_front({key, value});
        map[key] = cache.begin();
    }
};', NULL);
