}', '[{"input": "[[-1, 2], [3, -4]], nullptr", "weight": 0.3, "category": "SANITY", "expected_output": "[[-2, 0], [0, -8]]"}, {"input": "[[0, 0]], nullptr", "weight": 0.4, "category": "FUNCTIONAL", "expected_output": "[[0, 0]]"}, {"input": "[], nullptr", "weight": 0.3, "category": "EDGE", "expected_output": "[]"}]', NULL, 2, 128000, 'CUSTOM', 'void applyMatrixTransform(std::vector<std::vector<int>>& grid, int (*transform)(int) = nullptr)', 54, '#include <vector>

void applyMatrixTransform(std::vector<std::vector<int>>& grid, int (*transform)(int) = nullptr) {
    for (auto& row : grid) {
        for (int& val : row) {
            if (transform != nullptr) {
                val = transform(val);
            } else {
                if (val < 0) val *= 2;
                else if (val > 0) val = 0;
            }
        }
    }
}', NULL);
INSERT INTO exam.programming_questions (question_id, starter_code, test_cases, boilerplate_code, cpu_time_limit, memory_limit, category, function_signature, language_id, reference_solution, helper_code) VALUES (23, '#include <vector>

std::vector<int> computeRowAlternatingSums(const std::vector<std::vector<int>>& grid) {
    return {};
}', '[{"input": "[[1, 2, 3], [4, 5, 6]]", "weight": 0.5, "category": "SANITY", "expected_output": "[2, 5]"}, {"input": "[[10]]", "weight": 0.5, "category": "FUNCTIONAL", "expected_output": "[10]"}]', NULL, 2, 128000, 'GRID', 'std::vector<int> computeRowAlternatingSums(const std::vector<std::vector<int>>& grid)', 54, '#include <vector>                                                                      
                                                                                                     
std::vector<int> computeRowAlternatingSums(const std::vector<std::vector<int>>& grid) {
  std::vector<int> res;                                                              
  for (size_t r = 0; r < grid.size(); ++r) {                                         
    int sum = 0;                                                                   
    for (size_t c = 0; c < grid[r].size(); ++c) {                                  
      if (c % 2 == 0){
        sum += grid[r][c];
      }
      else {								      
        sum -= grid[r][c]; 						      
      }                                         				      
    }                                                                             
    res.push_back(sum);                                                            
  }                                                                                  
  return res;                                                                        
}', NULL);
