INSERT INTO exam.programming_questions (question_id, starter_code, test_cases, boilerplate_code, cpu_time_limit, memory_limit, category, function_signature, language_id, reference_solution, helper_code) VALUES (122, 'void swapPointers(int** ptrA, int** ptrB) {
   // your code here
}', '[{"input": "valA=10, valB=20", "weight": 0.3, "category": "FUNCTIONAL", "expected_output": "ptrA->20, ptrB->10"}, {"input": "valA=0, valB=-5", "weight": 0.4, "category": "SANITY", "expected_output": "ptrA->-5, ptrB->0"}, {"input": "nullptr check", "weight": 0.3, "category": "EDGE", "expected_output": "no-op"}]', '#include <iostream>
#include <sstream>
#include <string>

#include <memory>

// [[STUDENT_CODE_ZONE]]

int main() {
    std::string line;
    while (std::getline(std::cin, line)) {
        if (line.empty()) continue;

        if (line.find("nullptr") != std::string::npos) {
            swapPointers(nullptr, nullptr);
            std::cout << "no-op" << std::endl;
            continue;
        }

        int valA = 0, valB = 0;
        size_t posA = line.find("valA=");
        size_t posB = line.find("valB=");
        if (posA != std::string::npos) valA = std::stoi(line.substr(posA + 5));
        if (posB != std::string::npos) valB = std::stoi(line.substr(posB + 5));

        int a = valA, b = valB;
        int* ptrA = &a;
        int* ptrB = &b;

        swapPointers(&ptrA, &ptrB);

        std::cout << "ptrA->" << *ptrA << ", ptrB->" << *ptrB << std::endl;
    }
    return 0;
}', 2, 128000, 'SCALAR', 'void swapPointers(int** ptrA, int** ptrB)', 54, '#include <iostream>

using namespace std;

void swapPointers(int** ptrA, int** ptrB) {
 if (ptrA == nullptr || ptrB == nullptr) return;
    int* temp = *ptrA;
    *ptrA = *ptrB;
    *ptrB = temp;
}', NULL);
