INSERT INTO exam.programming_questions (question_id, starter_code, test_cases, boilerplate_code, cpu_time_limit, memory_limit, category, function_signature, language_id, reference_solution, helper_code) VALUES (100, '#include <iostream>

int main() {
    return 0;
}', '[{"input": "RECT 4 5\nCIRC 3", "weight": 0.3, "category": "SANITY", "is_canary": true, "is_public": false, "expected_output": "20.0\n28.274"}, {"input": "RECT 0 10", "weight": 0.4, "category": "FUNCTIONAL", "expected_output": "0.0"}, {"input": "CIRC 0", "weight": 0.3, "category": "EDGE", "expected_output": "0.0"}]', NULL, 2, 128000, 'CUSTOM', 'int main()', 54, '#include <iostream>
#include <string>
#include <iomanip>

class Shape {
public:
    virtual double area() const = 0;
    virtual ~Shape() {}
};

class Rectangle : public Shape {
private:
    double w, h;
public:
    Rectangle(double w, double h) : w(w), h(h) {}
    double area() const override { return w * h; }
};

class Circle : public Shape {
private:
    double r;
public:
    Circle(double r) : r(r) {}
    double area() const override { return 3.141592653589793 * r * r; }
};

int main() {
    std::string type;
    while (std::cin >> type) {
        if (type == "RECT") {
            double w, h;
            std::cin >> w >> h;
            Rectangle rect(w, h);
            std::cout << std::fixed << std::setprecision(1) << rect.area() << "\n";
        } else if (type == "CIRC") {
            double r;
            std::cin >> r;
            Circle circ(r);
            std::cout << std::fixed << std::setprecision(3) << circ.area() << "\n";
        }
    }
    return 0;
}', NULL);
