INSERT INTO exam.programming_questions (question_id, starter_code, test_cases, boilerplate_code, cpu_time_limit, memory_limit, category, function_signature, language_id, reference_solution, helper_code) VALUES (88, '#include <vector>

bool hasPath(const std::vector<std::vector<int>>& grid, int r, int c) {
    return false;
}', '[{"input": "[[0, 0, 1], [1, 0, 1], [1, 0, 0]], 0, 0", "weight": 0.3, "category": "SANITY", "expected_output": "true"}, {"input": "[[0, 1], [1, 0]], 0, 0", "weight": 0.4, "category": "FUNCTIONAL", "expected_output": "false"}, {"input": "[[0]], 0, 0", "weight": 0.3, "category": "EDGE", "expected_output": "true"}]', NULL, 2, 128000, 'GRID', 'bool hasPath(const std::vector<std::vector<int>>& grid, int r, int c)', 54, '#include <vector>

bool hasPath(const std::vector<std::vector<int>>& grid, int r, int c) {
    int rows = grid.size();
    if (rows == 0) return false;
    int cols = grid[0].size();
    if (r < 0 || r >= rows || c < 0 || c >= cols) return false;
    if (grid[r][c] == 1) return false;
    if (r == rows - 1 && c == cols - 1) return true;
    
    std::vector<std::vector<bool>> visited(rows, std::vector<bool>(cols, false));
    auto dfs = [&](auto& self, int cr, int cc) -> bool {
        if (cr < 0 || cr >= rows || cc < 0 || cc >= cols) return false;
        if (grid[cr][cc] == 1 || visited[cr][cc]) return false;
        if (cr == rows - 1 && cc == cols - 1) return true;
        visited[cr][cc] = true;
        return self(self, cr + 1, cc) || self(self, cr - 1, cc) ||
               self(self, cr, cc + 1) || self(self, cr, cc - 1);
    };
    return dfs(dfs, r, c);
}', NULL);
INSERT INTO exam.programming_questions (question_id, starter_code, test_cases, boilerplate_code, cpu_time_limit, memory_limit, category, function_signature, language_id, reference_solution, helper_code) VALUES (78, '#include <vector>

int recursiveGridRowSum(const std::vector<std::vector<int>>& grid, size_t row = 0) {
    return 0;
}', '[{"input": "[[1, 2], [3, 4]], 0", "weight": 0.3, "category": "SANITY", "expected_output": "10"}, {"input": "[[10]], 0", "weight": 0.4, "category": "FUNCTIONAL", "expected_output": "10"}, {"input": "[], 0", "weight": 0.3, "category": "EDGE", "expected_output": "0"}]', NULL, 2, 128000, 'GRID', 'int recursiveGridRowSum(const std::vector<std::vector<int>>& grid, size_t row = 0)', 54, '#include <vector>

int sumSingleRow(const std::vector<int>& row, size_t col = 0) {
    if (col >= row.size()) return 0;
    return row[col] + sumSingleRow(row, col + 1);
}

int recursiveGridRowSum(const std::vector<std::vector<int>>& grid, size_t row = 0) {
    if (row >= grid.size()) return 0;
    return sumSingleRow(grid[row]) + recursiveGridRowSum(grid, row + 1);
}', NULL);
