INSERT INTO exam.programming_questions (question_id, starter_code, test_cases, boilerplate_code, cpu_time_limit, memory_limit, category, function_signature, language_id, reference_solution, helper_code) VALUES (90, '#include <iostream>

int main() {
    return 0;
}', '[{"input": "4", "weight": 0.3, "category": "SANITY", "expected_output": "2"}, {"input": "8", "weight": 0.4, "category": "FUNCTIONAL", "expected_output": "92"}, {"input": "1", "weight": 0.3, "category": "EDGE", "expected_output": "1"}]', NULL, 2, 128000, 'CUSTOM', 'int main()', 54, '#include <iostream>
#include <vector>

void solveNQueens(int row, int n, std::vector<int>& cols, std::vector<int>& diag1, std::vector<int>& diag2, int& count) {
    if (row == n) {
        count++;
        return;
    }
    for (int col = 0; col < n; ++col) {
        if (cols[col] || diag1[row + col] || diag2[row - col + n - 1]) continue;
        cols[col] = diag1[row + col] = diag2[row - col + n - 1] = 1;
        solveNQueens(row + 1, n, cols, diag1, diag2, count);
        cols[col] = diag1[row + col] = diag2[row - col + n - 1] = 0;
    }
}

int main() {
    int n;
    if (std::cin >> n && n > 0) {
        int count = 0;
        std::vector<int> cols(n, 0), diag1(2 * n, 0), diag2(2 * n, 0);
        solveNQueens(0, n, cols, diag1, diag2, count);
        std::cout << count;
    }
    return 0;
}', NULL);
