int findMostFrequent(const std::vector<int>& nums) {
    return 0;
}', '[{"input": "[1, 3, 2, 3, 4, 1, 3]", "weight": 0.3, "category": "SANITY", "expected_output": "3"}, {"input": "[2, 2, 1, 1]", "weight": 0.4, "category": "FUNCTIONAL", "expected_output": "1"}, {"input": "[5]", "weight": 0.3, "category": "EDGE", "expected_output": "5"}]', NULL, 2, 128000, 'SCALAR', 'int findMostFrequent(const std::vector<int>& nums)', 54, '#include <vector>
#include <unordered_map>

int findMostFrequent(const std::vector<int>& nums) {
    if (nums.empty()) return 0;
    std::unordered_map<int, int> freq;
    for (int x : nums) {
        freq[x]++;
    }
    int mode = nums[0];
    int maxCount = 0;
    for (const auto& pair : freq) {
        if (pair.second > maxCount) {
            maxCount = pair.second;
            mode = pair.first;
        }
    }
    return mode;
}', NULL);
INSERT INTO exam.programming_questions (question_id, starter_code, test_cases, boilerplate_code, cpu_time_limit, memory_limit, category, function_signature, language_id, reference_solution, helper_code) VALUES (119, '#include <vector>
#include <queue>

struct Node {
    int data;
    Node* next;
};

Node* mergeKSortedLists(const std::vector<Node*>& lists) {
    return nullptr;
}', '[{"input": "[[1,4,5],[1,3,4],[2,6]]", "weight": 0.3, "category": "SANITY", "expected_output": "[1,1,2,3,4,4,5,6]"}, {"input": "[]", "weight": 0.4, "category": "FUNCTIONAL", "expected_output": "[]"}, {"input": "[[]]", "weight": 0.3, "category": "EDGE", "expected_output": "[]"}]', NULL, 2, 128000, 'CUSTOM', '

Node* mergeKSortedLists(const std::vector<Node*>& lists)', 54, '#include <vector>
#include <queue>

struct Node {
    int data;
    Node* next;
};

struct CompareNode {
    bool operator()(Node* a, Node* b) {
        return a->data > b->data;
    }
};

Node* mergeKSortedLists(const std::vector<Node*>& lists) {
    std::priority_queue<Node*, std::vector<Node*>, CompareNode> pq;
    for (auto node : lists) {
        if (node != nullptr) pq.push(node);
    }
    Node dummy{0, nullptr};
    Node* tail = &dummy;

    while (!pq.empty()) {
        Node* top = pq.top();
        pq.pop();
        tail->next = top;
        tail = tail->next;
        if (top->next != nullptr) {
            pq.push(top->next);
        }
    }
    return dummy.next;
}', NULL);
INSERT INTO exam.programming_questions (question_id, starter_code, test_cases, boilerplate_code, cpu_time_limit, memory_limit, category, function_signature, language_id, reference_solution, helper_code) VALUES (112, '#include <string>
#include <stack>

bool isValidParentheses(const std::string& s) {
    return false;
}', '[{"input": "\"()[]{}\"", "weight": 0.3, "category": "SANITY", "expected_output": "true"}, {"input": "\"(]\"", "weight": 0.4, "category": "FUNCTIONAL", "expected_output": "false"}, {"input": "\"\"", "weight": 0.3, "category": "EDGE", "expected_output": "true"}]', NULL, 2, 128000, 'SCALAR', 'bool isValidParentheses(const std::string& s)', 54, '#include <string>
#include <stack>

bool isValidParentheses(const std::string& s) {
    std::stack<char> st;
    for (char c : s) {
        if (c == ''('' || c == ''{'' || c == ''['') {
            st.push(c);
        } else if (c == '')'' || c == ''}'' || c == '']'') {
            if (st.empty()) return false;
            char top = st.top();
            st.pop();
            if ((c == '')'' && top != ''('') ||
                (c == ''}'' && top != ''{'') ||
                (c == '']'' && top != ''['')) {
                return false;
            }
        }
    }
    return st.empty();
}', NULL);
INSERT INTO exam.programming_questions (question_id, starter_code, test_cases, boilerplate_code, cpu_time_limit, memory_limit, category, function_signature, language_id, reference_solution, helper_code) VALUES (57, '#include <vector>
#include <string>

std::vector<std::string> sortWordsByAnagramGroup(const std::vector<std::string>& strs) {
    return {};
}', '[{"input": "[\"eat\", \"tea\", \"tan\", \"ate\", \"nat\", \"bat\"]", "weight": 0.3, "category": "SANITY", "expected_output": "[\"eat\", \"tea\", \"ate\", \"tan\", \"nat\", \"bat\"]"}, {"input": "[\"a\"]", "weight": 0.4, "category": "FUNCTIONAL", "expected_output": "[\"a\"]"}, {"input": "[]", "weight": 0.3, "category": "EDGE", "expected_output": "[]"}]', NULL, 2, 128000, 'LINEAR', 'std::vector<std::string> sortWordsByAnagramGroup(const std::vector<std::string>& strs)', 54, '#include <vector>
#include <string>
#include <unordered_map>
#include <algorithm>

std::vector<std::string> sortWordsByAnagramGroup(const std::vector<std::string>& strs) {
    std::unordered_map<std::string, std::vector<std::string>> groups;
    for (const auto& s : strs) {
        std::string key = s;
        std::sort(key.begin(), key.end());
        groups[key].push_back(s);
    }
    std::vector<std::string> result;
    for (const auto& s : strs) {
        std::string key = s;
        std::sort(key.begin(), key.end());
        if (groups.count(key)) {
            for (const auto& item : groups[key]) {
                result.push_back(item);
            }
            groups.erase(key);
        }
    }
    return result;
}', NULL);
INSERT INTO exam.programming_questions (question_id, starter_code, test_cases, boilerplate_code, cpu_time_limit, memory_limit, category, function_signature, language_id, reference_solution, helper_code) VALUES (8, '#include <vector>

std::vector<std::vector<int>> checkBoundaryStatus(const std::vector<std::vector<int>>& grid) {
    return grid;
}', '[{"input": "[[1, 2, 3], [4, 5, 6], [7, 8, 9]]", "weight": 0.3, "category": "SANITY", "expected_output": "[[1, 2, 3], [4, -1, 6], [7, 8, 9]]"}, {"input": "[[1, 1], [1, 1]]", "weight": 0.4, "category": "FUNCTIONAL", "expected_output": "[[1, 1], [1, 1]]"}, {"input": "[[5, 5, 5], [5, -3, 5], [5, 5, 5]]", "weight": 0.3, "category": "EDGE", "expected_output": "[[5, 5, 5], [5, -2, 5], [5, 5, 5]]"}]', NULL, 2, 128000, 'GRID', 'std::vector<std::vector<int>> checkBoundaryStatus(const std::vector<std::vector<int>>& grid)', 54, '#include <vector>

std::vector<std::vector<int>> checkBoundaryStatus(const std::vector<std::vector<int>>& grid) {
    std::vector<std::vector<int>> res = grid;
    int rows = res.size();
    if (rows == 0) return res;
    int cols = res[0].size();
    for (int r = 0; r < rows; ++r) {
        for (int c = 0; c < cols; ++c) {
            bool isBoundary = (r == 0 || r == rows - 1 || c == 0 || c == cols - 1);
            if (!isBoundary) {
                if (res[r][c] == 5) res[r][c] = -1;
                else res[r][c] = -2;
            }
        }
    }
    return res;
}', NULL);
