    return 0;
}', '[{"input": "[-2, 1, -3, 4, -1, 2, 1, -5, 4]", "weight": 0.3, "category": "SANITY", "expected_output": "6"}, {"input": "[-1, -2, -3]", "weight": 0.4, "category": "FUNCTIONAL", "expected_output": "-1"}, {"input": "[]", "weight": 0.3, "category": "EDGE", "expected_output": "0"}]', NULL, 2, 128000, 'LINEAR', 'int maxSubarraySum(const std::vector<int>& nums)', 54, '#include <vector>
#include <algorithm>

int maxSubarraySum(const std::vector<int>& nums) {
    if (nums.empty()) return 0;
    int maxSoFar = nums[0];
    int currMax = nums[0];
    for (size_t i = 1; i < nums.size(); ++i) {
        currMax = std::max(nums[i], currMax + nums[i]);
        maxSoFar = std::max(maxSoFar, currMax);
    }
    return maxSoFar;
}', NULL);
