    while (std::cin >> cmd) {
        if (cmd == "PUSH") {
            scopes.push_back({});
        } else if (cmd == "POP") {
            if (scopes.size() > 1) {
                scopes.pop_back();
            }
        } else if (cmd == "SET") {
            std::string var;
            int val;
            std::cin >> var >> val;
            scopes.back()[var] = val;
        } else if (cmd == "GET") {
            std::string var;
            std::cin >> var;
            bool found = false;
            for (int i = static_cast<int>(scopes.size()) - 1; i >= 0; --i) {
                if (scopes[i].count(var)) {
                    std::cout << scopes[i][var] << "\n";
                    found = true;
                    break;
                }
            }
            if (!found) {
                std::cout << "UNDEFINED\n";
            }
        }
    }
    return 0;
}', NULL);
