INSERT INTO exam.programming_questions (question_id, starter_code, test_cases, boilerplate_code, cpu_time_limit, memory_limit, category, function_signature, language_id, reference_solution, helper_code) VALUES (60, '#include <iostream>

int main() {
    return 0;
}', '[{"input": "3+2*2", "weight": 0.3, "category": "SANITY", "expected_output": "7"}, {"input": " 3/2 ", "weight": 0.4, "category": "FUNCTIONAL", "expected_output": "1"}, {"input": " 3+5 / 2 ", "weight": 0.3, "category": "EDGE", "expected_output": "5"}]', NULL, 2, 128000, 'CUSTOM', 'int main()', 54, '#include <iostream>
#include <string>
#include <stack>
#include <cctype>

int main() {
    std::string s;
    if (std::getline(std::cin, s)) {
        std::stack<int> st;
        int num = 0;
        char op = ''+'';
        for (size_t i = 0; i < s.length(); ++i) {
            char c = s[i];
            if (std::isdigit(c)) {
                num = num * 10 + (c - ''0'');
            }
            if ((!std::isdigit(c) && !std::isspace(c)) || i == s.length() - 1) {
                if (op == ''+'') st.push(num);
                else if (op == ''-'') st.push(-num);
                else if (op == ''*'') {
                    int top = st.top(); st.pop();
                    st.push(top * num);
                } else if (op == ''/'') {
                    int top = st.top(); st.pop();
                    st.push(top / num);
                }
                op = c;
                num = 0;
            }
        }
        int result = 0;
        while (!st.empty()) {
            result += st.top();
            st.pop();
        }
        std::cout << result;
    }
    return 0;
}', NULL);
