INSERT INTO exam.programming_questions (question_id, starter_code, test_cases, boilerplate_code, cpu_time_limit, memory_limit, category, function_signature, language_id, reference_solution, helper_code) VALUES (58, '#include <vector>
#include <string>

bool existWord(const std::vector<std::vector<char>>& board, std::string word) {
    return false;
}', '[{"input": "[[''A'',''B'',''C'',''E''],[''S'',''F'',''C'',''S''],[''A'',''D'',''E'',''E'']], \"ABCCED\"", "weight": 0.3, "category": "SANITY", "is_canary": true, "is_public": false, "expected_output": "true"}, {"input": "[[''A'',''B'']], \"AC\"", "weight": 0.4, "category": "FUNCTIONAL", "expected_output": "false"}, {"input": "[], \"A\"", "weight": 0.3, "category": "EDGE", "expected_output": "false"}]', NULL, 2, 128000, 'GRID', 'bool existWord(const std::vector<std::vector<char>>& board, std::string word)', 54, '#include <vector>
#include <string>

bool dfs(std::vector<std::vector<char>>& board, const std::string& word, int r, int c, size_t index) {
    if (index == word.length()) return true;
    if (r < 0 || r >= static_cast<int>(board.size()) || c < 0 || c >= static_cast<int>(board[0].size()) || board[r][c] != word[index]) {
        return false;
    }
    char temp = board[r][c];
    board[r][c] = ''#'';
    bool found = dfs(board, word, r + 1, c, index + 1) ||
                 dfs(board, word, r - 1, c, index + 1) ||
                 dfs(board, word, r, c + 1, index + 1) ||
                 dfs(board, word, r, c - 1, index + 1);
    board[r][c] = temp;
    return found;
}

bool existWord(const std::vector<std::vector<char>>& board, std::string word) {
    if (board.empty() || board[0].empty()) return false;
    auto grid = board;
    for (size_t r = 0; r < grid.size(); ++r) {
        for (size_t c = 0; c < grid[0].size(); ++c) {
            if (dfs(grid, word, static_cast<int>(r), static_cast<int>(c), 0)) {
                return true;
            }
        }
    }
    return false;
}', NULL);
