    return nullptr;
}', '[{"input": "[[1, 2], [3, 4]], 2, 2", "weight": 0.3, "category": "SANITY", "expected_output": "[1, 2, 3, 4]"}, {"input": "[[5]], 1, 1", "weight": 0.4, "category": "FUNCTIONAL", "expected_output": "[5]"}, {"input": "nullptr, 0, 0", "weight": 0.3, "category": "EDGE", "expected_output": "nullptr"}]', NULL, 2, 128000, 'CUSTOM', 'int* flattenRawMatrix(int** matrix, int rows, int cols)', 54, '#include <iostream>

int* flattenRawMatrix(int** matrix, int rows, int cols) {
    if (matrix == nullptr || rows <= 0 || cols <= 0) return nullptr;
    int* flat = new int[rows * cols];
    int idx = 0;
    for (int r = 0; r < rows; ++r) {
        if (matrix[r] == nullptr) continue;
        for (int c = 0; c < cols; ++c) {
            flat[idx++] = matrix[r][c];
        }
    }
    return flat;
}', NULL);
