int countCollatzSteps(int n) {
    return 0;
}', '[{"input": "6", "weight": 0.3, "category": "SANITY", "expected_output": "8"}, {"input": "1", "weight": 0.4, "category": "FUNCTIONAL", "expected_output": "0"}, {"input": "27", "weight": 0.3, "category": "EDGE", "expected_output": "111"}]', NULL, 2, 128000, 'SCALAR', 'int countCollatzSteps(int n)', 54, '#include <iostream>

int countCollatzSteps(int n) {
    long long val = n;
    int steps = 0;
    while (val > 1) {
        if (val % 2 == 0) {
            val /= 2;
        } else {
            val = 3 * val + 1;
        }
        steps++;
    }
    return steps;
}', NULL);
