int longestNonDecreasingRun(const std::vector<int>& nums) {
    return 0;
}', '[{"input": "[1, 2, 2, 1, 3, 4, 5]", "weight": 0.3, "category": "SANITY", "expected_output": "4"}, {"input": "[5, 4, 3, 2, 1]", "weight": 0.4, "category": "FUNCTIONAL", "expected_output": "1"}, {"input": "[]", "weight": 0.3, "category": "EDGE", "expected_output": "0"}]', NULL, 2, 128000, 'LINEAR', 'int longestNonDecreasingRun(const std::vector<int>& nums)', 54, '#include <vector>
#include <algorithm>

int longestNonDecreasingRun(const std::vector<int>& nums) {
    if (nums.empty()) return 0;
    int maxLen = 1;
    int currLen = 1;
    for (size_t i = 1; i < nums.size(); ++i) {
        if (nums[i] >= nums[i - 1]) {
            currLen++;
        } else {
            maxLen = std::max(maxLen, currLen);
            currLen = 1;
        }
    }
    return std::max(maxLen, currLen);
}', NULL);
