class Complex {
private:
    double real, imag;
public:
    Complex(double r = 0, double i = 0) : real(r), imag(i) {}
    Complex operator+(const Complex& other) const {
        return Complex(real + other.real, imag + other.imag);
    }
    Complex operator-(const Complex& other) const {
        return Complex(real - other.real, imag - other.imag);
    }
    bool operator==(const Complex& other) const {
        return real == other.real && imag == other.imag;
    }
};', NULL);
INSERT INTO exam.programming_questions (question_id, starter_code, test_cases, boilerplate_code, cpu_time_limit, memory_limit, category, function_signature, language_id, reference_solution, helper_code) VALUES (44, 'struct Node {
    int data;
    Node* next;
};

Node* createTrackedNode(int value, int& activeCount) {
    return nullptr;
}

void destroyNode(Node*& node, int& activeCount) {
}', '[{"input": "create 10", "weight": 0.3, "category": "SANITY", "expected_output": "val:10, count:1"}, {"input": "create 5, destroy", "weight": 0.4, "category": "FUNCTIONAL", "expected_output": "val:null, count:0"}, {"input": "destroy null", "weight": 0.3, "category": "EDGE", "expected_output": "count:0"}]', '#include <iostream>
#include <sstream>
#include <string>
using namespace std;

// [[STUDENT_CODE_ZONE]]

static string trimToken(const string& s) {
    size_t start = s.find_first_not_of(" \t");
    size_t end = s.find_last_not_of(" \t");
    if (start == string::npos) return "";
    return s.substr(start, end - start + 1);
}

int main() {
    string line;
    while (getline(cin, line)) {
        if (line.empty()) continue;

        int activeCount = 0;
        Node* node = nullptr;
        bool createdEver = false;

        stringstream ss(line);
        string command;
        while (getline(ss, command, '','')) {
            command = trimToken(command);
            if (command.empty()) continue;

            stringstream cs(command);
            string op;
            cs >> op;

            if (op == "create") {
                int value;
                cs >> value;
                node = createTrackedNode(value, activeCount);
                createdEver = true;
            } else if (op == "destroy") {
                destroyNode(node, activeCount);
            }
        }

        if (createdEver) {
            if (node != nullptr) {
                cout << "val:" << node->data << ", count:" << activeCount << endl;
            } else {
                cout << "val:null, count:" << activeCount << endl;
            }
        } else {
            cout << "count:" << activeCount << endl;
        }
    }
    return 0;
}
', 2, 128000, 'CUSTOM', '

Node* createTrackedNode(int value, int& activeCount)', 54, 'struct Node {
    int data;
    Node* next;
};

Node* createTrackedNode(int value, int& activeCount) {
    activeCount++;
    return new Node{value, nullptr};
}

void destroyNode(Node*& node, int& activeCount) {
    if (node != nullptr) {
        delete node;
        node = nullptr;
        activeCount--;
    }
}', NULL);
