INSERT INTO exam.programming_questions (question_id, starter_code, test_cases, boilerplate_code, cpu_time_limit, memory_limit, category, function_signature, language_id, reference_solution, helper_code) VALUES (102, '#include <iostream>

class IntVector {
private:
    int* data;
    size_t sz;
    size_t cap;
public:
    IntVector() : data(nullptr), sz(0), cap(0) {}
    ~IntVector() { delete[] data; }
};', '[{"input": "push 1, 2, move assign", "weight": 0.3, "category": "SANITY", "expected_output": "[1, 2]"}, {"input": "copy construct", "weight": 0.4, "category": "FUNCTIONAL", "expected_output": "deep copy verified"}, {"input": "empty vector move", "weight": 0.3, "category": "EDGE", "expected_output": "size 0"}]', NULL, 2, 128000, 'CUSTOM', 'int main()', 54, '#include <iostream>
#include <algorithm>

class IntVector {
private:
    int* data;
    size_t sz;
    size_t cap;
public:
    IntVector() : data(nullptr), sz(0), cap(0) {}
    ~IntVector() { delete[] data; }
    
    IntVector(const IntVector& other) : sz(other.sz), cap(other.cap) {
        data = new int[cap];
        for (size_t i = 0; i < sz; ++i) data[i] = other.data[i];
    }
    
    IntVector& operator=(const IntVector& other) {
        if (this != &other) {
            delete[] data;
            sz = other.sz;
            cap = other.cap;
            data = new int[cap];
            for (size_t i = 0; i < sz; ++i) data[i] = other.data[i];
        }
        return *this;
    }
    
    IntVector(IntVector&& other) noexcept : data(other.data), sz(other.sz), cap(other.cap) {
        other.data = nullptr;
        other.sz = 0;
        other.cap = 0;
    }
    
    IntVector& operator=(IntVector&& other) noexcept {
        if (this != &other) {
            delete[] data;
            data = other.data;
            sz = other.sz;
            cap = other.cap;
            other.data = nullptr;
            other.sz = 0;
            other.cap = 0;
        }
        return *this;
    }
    
    void push_back(int val) {
        if (sz == cap) {
            size_t newCap = cap == 0 ? 1 : cap * 2;
            int* newData = new int[newCap];
            for (size_t i = 0; i < sz; ++i) newData[i] = data[i];
            delete[] data;
            data = newData;
            cap = newCap;
        }
        data[sz++] = val;
    }
    size_t size() const { return sz; }
};', NULL);
INSERT INTO exam.programming_questions (question_id, starter_code, test_cases, boilerplate_code, cpu_time_limit, memory_limit, category, function_signature, language_id, reference_solution, helper_code) VALUES (2, '#include <vector>

std::vector<int> classifySigns(const std::vector<int>& numbers) {
    return {};
}', '[{"input": "[10, -5, 0]", "weight": 0.3, "category": "SANITY", "expected_output": "[1, -1, 0]"}, {"input": "[-1, -2, -3]", "weight": 0.4, "category": "FUNCTIONAL", "expected_output": "[-1, -1, -1]"}, {"input": "[]", "weight": 0.3, "category": "EDGE", "expected_output": "[]"}]', NULL, 2, 128000, 'LINEAR', 'vector<int> classifySigns(const std::vector<int>& numbers)', 54, '#include <vector>

std::vector<int> classifySigns(const std::vector<int>& numbers) {
    std::vector<int> result;
    result.reserve(numbers.size());
    for (int num : numbers) {
        if (num > 0) result.push_back(1);
        else if (num < 0) result.push_back(-1);
        else result.push_back(0);
    }
