INSERT INTO exam.programming_questions (question_id, starter_code, test_cases, boilerplate_code, cpu_time_limit, memory_limit, category, function_signature, language_id, reference_solution, helper_code) VALUES (39, 'struct Node {
    int data;
    Node* next;
};

void splitListBySign(Node* source, Node*& posHead, Node*& negHead) {
}', '[{"input": "[1, -2, 3, -4]", "weight": 0.3, "category": "SANITY", "expected_output": "([1, 3], [-2, -4])"}, {"input": "[1, 2, 3]", "weight": 0.4, "category": "FUNCTIONAL", "expected_output": "([1, 2, 3], [])"}, {"input": "[]", "weight": 0.3, "category": "EDGE", "expected_output": "([], [])"}]', NULL, 2, 128000, 'LINKED_LIST', 'std::pair<Node*, Node*> splitListBySign(Node* source)', 54, '
#include <utility>

struct Node {
    int data;
    Node* next;
};

std::pair<Node*, Node*> splitListBySign(Node* source) {
    Node* posHead = nullptr;
    Node* negHead = nullptr;
    Node* posTail = nullptr;
    Node* negTail = nullptr;

    Node* curr = source;
    while (curr != nullptr) {
        Node* newNode = new Node{curr->data, nullptr};
        if (curr->data >= 0) {
            if (!posHead) posHead = posTail = newNode;
            else { posTail->next = newNode; posTail = newNode; }
        } else {
            if (!negHead) negHead = negTail = newNode;
            else { negTail->next = newNode; negTail = newNode; }
        }
        curr = curr->next;
    }
    return {posHead, negHead};
}', NULL);
