    return false;
}', '[{"input": "[''r'', ''a'', ''c'', ''e'', ''c'', ''a'', ''r'']", "weight": 0.3, "category": "SANITY", "expected_output": "true"}, {"input": "[''a'', ''b'']", "weight": 0.4, "category": "FUNCTIONAL", "expected_output": "false"}, {"input": "[]", "weight": 0.3, "category": "EDGE", "expected_output": "true"}]', NULL, 2, 128000, 'LINKED_LIST', '

bool isPalindromeList(Node* head)', 54, '#include <vector>

struct Node {
    char data;
    Node* next;
};

bool isPalindromeList(Node* head) {
    std::vector<char> chars;
    Node* curr = head;
    while (curr != nullptr) {
        chars.push_back(curr->data);
        curr = curr->next;
    }
    int left = 0;
    int right = static_cast<int>(chars.size()) - 1;
    while (left < right) {
        if (chars[left] != chars[right]) return false;
        left++;
        right--;
    }
    return true;
}', NULL);
INSERT INTO exam.programming_questions (question_id, starter_code, test_cases, boilerplate_code, cpu_time_limit, memory_limit, category, function_signature, language_id, reference_solution, helper_code) VALUES (56, '#include <string>

int lengthOfLongestSubstring(const std::string& s) {
    return 0;
}', '[{"input": "\"abcabcbb\"", "weight": 0.3, "category": "SANITY", "expected_output": "3"}, {"input": "\"bbbbb\"", "weight": 0.4, "category": "FUNCTIONAL", "expected_output": "1"}, {"input": "\"\"", "weight": 0.3, "category": "EDGE", "expected_output": "0"}]', NULL, 2, 128000, 'SCALAR', 'int lengthOfLongestSubstring(const std::string& s)', 54, '#include <string>
#include <unordered_map>
#include <algorithm>

int lengthOfLongestSubstring(const std::string& s) {
    std::unordered_map<char, int> charMap;
    int maxLen = 0;
    int start = 0;
    for (int end = 0; end < static_cast<int>(s.length()); ++end) {
        if (charMap.count(s[end]) && charMap[s[end]] >= start) {
            start = charMap[s[end]] + 1;
        }
        charMap[s[end]] = end;
        maxLen = std::max(maxLen, end - start + 1);
    }
    return maxLen;
}', NULL);
