Node* deepCopyList(Node* head) {
    return nullptr;
}', '[{"input": "[10, 20, 30]", "weight": 0.3, "category": "SANITY", "expected_output": "[10, 20, 30]"}, {"input": "[5]", "weight": 0.4, "category": "FUNCTIONAL", "expected_output": "[5]"}, {"input": "[]", "weight": 0.3, "category": "EDGE", "expected_output": "[]"}]', NULL, 2, 128000, 'LINKED_LIST', '

Node* deepCopyList(Node* head)', 54, 'struct Node {
    int data;
    Node* next;
};

Node* deepCopyList(Node* head) {
    if (head == nullptr) return nullptr;
    Node* newHead = new Node{head->data, nullptr};
    Node* currOriginal = head->next;
    Node* currCopy = newHead;

    while (currOriginal != nullptr) {
        currCopy->next = new Node{currOriginal->data, nullptr};
        currCopy = currCopy->next;
        currOriginal = currOriginal->next;
    }
    return newHead;
}', NULL);
