    std::string name;
    std::vector<int> grades;
};

double getStudentGPA(const Student& s) {
    if (s.grades.empty()) return 0.0;
    double sum = 0.0;
    for (int g : s.grades) {
        sum += g;
    }
    return sum / s.grades.size();
