struct Point2D {
    double x;
    double y;
};

double calculateDistance(Point2D p1, Point2D p2) {
    double dx = p1.x - p2.x;
    double dy = p1.y - p2.y;
    return std::sqrt(dx * dx + dy * dy);
}', NULL);
INSERT INTO exam.programming_questions (question_id, starter_code, test_cases, boilerplate_code, cpu_time_limit, memory_limit, category, function_signature, language_id, reference_solution, helper_code) VALUES (83, '#include <vector>

int countConnectedRegion(std::vector<std::vector<int>>& grid, int r, int c) {
    return 0;
}', '[{"input": "[[1, 1, 0], [1, 0, 0], [0, 0, 1]], 0, 0", "weight": 0.3, "category": "SANITY", "expected_output": "3"}, {"input": "[[0, 0], [0, 0]], 0, 0", "weight": 0.4, "category": "FUNCTIONAL", "expected_output": "0"}, {"input": "[[1]], 0, 0", "weight": 0.3, "category": "EDGE", "expected_output": "1"}]', NULL, 2, 128000, 'GRID', 'int countConnectedRegion(std::vector<std::vector<int>>& grid, int r, int c)', 54, '#include <vector>

int countConnectedRegion(std::vector<std::vector<int>>& grid, int r, int c) {
    if (r < 0 || r >= (int)grid.size() || c < 0 || c >= (int)grid[0].size()) return 0;
    if (grid[r][c] != 1) return 0;
    grid[r][c] = 0;
    return 1 + countConnectedRegion(grid, r + 1, c) +
               countConnectedRegion(grid, r - 1, c) +
               countConnectedRegion(grid, r, c + 1) +
               countConnectedRegion(grid, r, c - 1);
}', NULL);
