    int data;
    Node* next;
};

Node* reverseListRecursive(Node* head) {
    if (head == nullptr || head->next == nullptr) return head;
    Node* rest = reverseListRecursive(head->next);
    head->next->next = head;
    head->next = nullptr;
    return rest;
}', NULL);
INSERT INTO exam.programming_questions (question_id, starter_code, test_cases, boilerplate_code, cpu_time_limit, memory_limit, category, function_signature, language_id, reference_solution, helper_code) VALUES (89, 'struct Node {
