    Node* next;
};

Node* mergeSortedListsRecursive(Node* l1, Node* l2) {
    return nullptr;
}', '[{"input": "[1, 3, 5], [2, 4, 6]", "weight": 0.3, "category": "SANITY", "expected_output": "[1, 2, 3, 4, 5, 6]"}, {"input": "[], [1, 2]", "weight": 0.4, "category": "FUNCTIONAL", "expected_output": "[1, 2]"}, {"input": "[], []", "weight": 0.3, "category": "EDGE", "expected_output": "[]"}]', NULL, 2, 128000, 'LINKED_LIST', '

Node* mergeSortedListsRecursive(Node* l1, Node* l2)', 54, 'struct Node {
    int data;
    Node* next;
};

Node* mergeSortedListsRecursive(Node* l1, Node* l2) {
    if (l1 == nullptr) return l2;
    if (l2 == nullptr) return l1;
    if (l1->data <= l2->data) {
        l1->next = mergeSortedListsRecursive(l1->next, l2);
        return l1;
    } else {
        l2->next = mergeSortedListsRecursive(l1, l2->next);
        return l2;
    }
}', NULL);
INSERT INTO exam.programming_questions (question_id, starter_code, test_cases, boilerplate_code, cpu_time_limit, memory_limit, category, function_signature, language_id, reference_solution, helper_code) VALUES (93, '#include <vector>

struct Pixel {
    int r, g, b;
};

std::vector<std::vector<int>> computeGrayscaleGrid(const std::vector<std::vector<Pixel>>& image) {
    return {};
}', '[{"input": "[[Pixel(255,255,255), Pixel(0,0,0)]]", "weight": 0.3, "category": "SANITY", "expected_output": "[[255, 0]]"}, {"input": "[[Pixel(10,20,30)]]", "weight": 0.4, "category": "FUNCTIONAL", "expected_output": "[[20]]"}, {"input": "[]", "weight": 0.3, "category": "EDGE", "expected_output": "[]"}]', NULL, 2, 128000, 'CUSTOM', 'std::vector<std::vector<int>> computeGrayscaleGrid(const std::vector<std::vector<Pixel>>& image)', 54, '#include <vector>

struct Pixel {
    int r, g, b;
};

std::vector<std::vector<int>> computeGrayscaleGrid(const std::vector<std::vector<Pixel>>& image) {
    std::vector<std::vector<int>> result;
    result.reserve(image.size());
    for (const auto& row : image) {
        std::vector<int> rowGray;
        rowGray.reserve(row.size());
        for (const auto& p : row) {
            rowGray.push_back((p.r + p.g + p.b) / 3);
        }
        result.push_back(rowGray);
    }
    return result;
}', NULL);
INSERT INTO exam.programming_questions (question_id, starter_code, test_cases, boilerplate_code, cpu_time_limit, memory_limit, category, function_signature, language_id, reference_solution, helper_code) VALUES (99, 'struct Node {
    int data;
    Node* next;
};

class LinkedList {
private:
    Node* head;
public:
    LinkedList() : head(nullptr) {}
    ~LinkedList() {}
    void pushFront(int val) {}
    int popFront() { return -1; }
};', '[{"input": "pushFront(10), pushFront(20), popFront()", "weight": 0.3, "category": "SANITY", "expected_output": "20"}, {"input": "popFront() empty", "weight": 0.4, "category": "FUNCTIONAL", "expected_output": "-1"}, {"input": "push 5, pop, pop", "weight": 0.3, "category": "EDGE", "expected_output": "5 then -1"}]', NULL, 2, 128000, 'CUSTOM', '
    LinkedList()', 54, 'struct Node {
    int data;
    Node* next;
};

class LinkedList {
private:
    Node* head;
public:
    LinkedList() : head(nullptr) {}
    ~LinkedList() {
        Node* curr = head;
        while (curr != nullptr) {
            Node* nextNode = curr->next;
            delete curr;
            curr = nextNode;
        }
    }
    void pushFront(int val) {
        head = new Node{val, head};
    }
    int popFront() {
        if (head == nullptr) return -1;
        Node* temp = head;
        int val = temp->data;
        head = head->next;
        delete temp;
        return val;
    }
};', NULL);
