bool hasCycleSet(Node* head)', 54, '#include <unordered_set>

struct Node {
    int data;
    Node* next;
};

bool hasCycleSet(Node* head) {
    std::unordered_set<Node*> visited;
    Node* curr = head;
    while (curr != nullptr) {
        if (visited.count(curr)) return true;
        visited.insert(curr);
        curr = curr->next;
    }
    return false;
}', NULL);
