INSERT INTO exam.programming_questions (question_id, starter_code, test_cases, boilerplate_code, cpu_time_limit, memory_limit, category, function_signature, language_id, reference_solution, helper_code) VALUES (75, '#include <iostream>

int main() {
    return 0;
}', '[{"input": "1000\nALLOC 200\nALLOC 300\nFREE 0", "weight": 0.3, "category": "SANITY", "expected_output": "800\n500\n700"}, {"input": "500\nALLOC 600", "weight": 0.4, "category": "FUNCTIONAL", "expected_output": "FAIL"}, {"input": "100\nALLOC 100", "weight": 0.3, "category": "EDGE", "expected_output": "0"}]', NULL, 2, 128000, 'CUSTOM', 'int main()', 54, '#include <iostream>
#include <string>
#include <vector>

struct Block {
    int id;
    int size;
};

int main() {
    int poolSize;
    if (std::cin >> poolSize) {
        int remaining = poolSize;
        std::vector<Block> allocs;
        int nextId = 0;
        std::string cmd;
        while (std::cin >> cmd) {
            if (cmd == "ALLOC") {
                int sz;
                std::cin >> sz;
                if (sz <= remaining) {
                    remaining -= sz;
                    allocs.push_back({nextId++, sz});
                    std::cout << remaining << "\n";
                } else {
                    std::cout << "FAIL\n";
                }
            } else if (cmd == "FREE") {
                int targetId;
                std::cin >> targetId;
                for (size_t i = 0; i < allocs.size(); ++i) {
                    if (allocs[i].id == targetId) {
                        remaining += allocs[i].size;
                        allocs.erase(allocs.begin() + i);
                        break;
                    }
                }
                std::cout << remaining << "\n";
            }
        }
    }
    return 0;
}', NULL);
