INSERT INTO exam.programming_questions (question_id, starter_code, test_cases, boilerplate_code, cpu_time_limit, memory_limit, category, function_signature, language_id, reference_solution, helper_code) VALUES (52, '#include <string>

std::string reverseWords(const std::string& sentence) {
    return "";
}', '[{"input": "\"Hello World\"", "weight": 0.3, "category": "SANITY", "expected_output": "\"olleH dlroW\""}, {"input": "\"a b c\"", "weight": 0.4, "category": "FUNCTIONAL", "expected_output": "\"a b c\""}, {"input": "\"\"", "weight": 0.3, "category": "EDGE", "expected_output": "\"\""}]', NULL, 2, 128000, 'SCALAR', 'string reverseWords(const std::string& sentence)', 54, '#include <string>
#include <sstream>
#include <algorithm>

std::string reverseWords(const std::string& sentence) {
    if (sentence.empty()) return "";
    std::stringstream ss(sentence);
    std::string word;
    std::string result = "";
    bool first = true;
    while (ss >> word) {
        std::reverse(word.begin(), word.end());
        if (!first) result += " ";
        result += word;
        first = false;
    }
    return result;
}', NULL);
INSERT INTO exam.programming_questions (question_id, starter_code, test_cases, boilerplate_code, cpu_time_limit, memory_limit, category, function_signature, language_id, reference_solution, helper_code) VALUES (120, '#include <iostream>

int main() {
    return 0;
}', '[{"input": "3\n1\n2\n3", "weight": 0.3, "category": "SANITY", "expected_output": "1.0\n1.5\n2.0"}, {"input": "1\n5", "weight": 0.4, "category": "FUNCTIONAL", "expected_output": "5.0"}, {"input": "2\n10 20", "weight": 0.3, "category": "EDGE", "expected_output": "10.0\n15.0"}]', NULL, 2, 128000, 'CUSTOM', 'int main()', 54, '#include <iostream>
#include <queue>
#include <iomanip>

int main() {
    int n;
    if (std::cin >> n && n > 0) {
        std::priority_queue<int> maxHeap;
        std::priority_queue<int, std::vector<int>, std::greater<int>> minHeap;

        for (int i = 0; i < n; ++i) {
            int val;
            std::cin >> val;
            if (maxHeap.empty() || val <= maxHeap.top()) {
                maxHeap.push(val);
            } else {
                minHeap.push(val);
            }

            if (maxHeap.size() > minHeap.size() + 1) {
                minHeap.push(maxHeap.top());
                maxHeap.pop();
            } else if (minHeap.size() > maxHeap.size()) {
                maxHeap.push(minHeap.top());
                minHeap.pop();
            }

            if (maxHeap.size() == minHeap.size()) {
                double med = (maxHeap.top() + minHeap.top()) / 2.0;
                std::cout << std::fixed << std::setprecision(1) << med << "\n";
            } else {
                std::cout << std::fixed << std::setprecision(1) << static_cast<double>(maxHeap.top()) << "\n";
            }
        }
    }
    return 0;
}', NULL);
INSERT INTO exam.programming_questions (question_id, starter_code, test_cases, boilerplate_code, cpu_time_limit, memory_limit, category, function_signature, language_id, reference_solution, helper_code) VALUES (105, '#include <iostream>

int main() {
    return 0;
}', '[{"input": "CREATE Add 1\nEXEC 1 10\nEXEC 1 20", "weight": 0.3, "category": "SANITY", "expected_output": "10\n30"}, {"input": "EXEC 99 5", "weight": 0.4, "category": "FUNCTIONAL", "expected_output": "NOT_FOUND"}, {"input": "CREATE Mult 2\nEXEC 2 0", "weight": 0.3, "category": "EDGE", "expected_output": "0"}]', NULL, 2, 128000, 'CUSTOM', 'int main()', 54, '#include <iostream>
#include <string>
#include <unordered_map>
#include <memory>

class Plugin {
public:
    virtual int execute(int val) = 0;
    virtual ~Plugin() = default;
};

class AddPlugin : public Plugin {
private:
    int total = 0;
public:
    int execute(int val) override {
        total += val;
        return total;
    }
};

class MultPlugin : public Plugin {
private:
    int total = 1;
public:
    int execute(int val) override {
        total *= val;
        return total;
    }
};

int main() {
    std::unordered_map<int, std::unique_ptr<Plugin>> plugins;
    std::string cmd;
    while (std::cin >> cmd) {
        if (cmd == "CREATE") {
            std::string type;
            int id;
            std::cin >> type >> id;
            if (type == "Add") plugins[id] = std::make_unique<AddPlugin>();
            else if (type == "Mult") plugins[id] = std::make_unique<MultPlugin>();
        } else if (cmd == "EXEC") {
            int id, val;
            std::cin >> id >> val;
            if (plugins.count(id)) {
                std::cout << plugins[id]->execute(val) << "\n";
            } else {
                std::cout << "NOT_FOUND\n";
            }
        }
    }
    return 0;
}', NULL);
INSERT INTO exam.programming_questions (question_id, starter_code, test_cases, boilerplate_code, cpu_time_limit, memory_limit, category, function_signature, language_id, reference_solution, helper_code) VALUES (113, '#include <vector>
#include <queue>

int shortestPathGrid(const std::vector<std::vector<int>>& grid) {
    return -1;
}', '[{"input": "[[0,0,0],[1,1,0],[0,0,0]]", "weight": 0.3, "category": "SANITY", "expected_output": "5"}, {"input": "[[0,1],[1,0]]", "weight": 0.4, "category": "FUNCTIONAL", "expected_output": "-1"}, {"input": "[[0]]", "weight": 0.3, "category": "EDGE", "expected_output": "1"}]', NULL, 2, 128000, 'GRID', 'int shortestPathGrid(const std::vector<std::vector<int>>& grid)', 54, '#include <vector>
#include <queue>

int shortestPathGrid(const std::vector<std::vector<int>>& grid) {
    if (grid.empty() || grid[0].empty()) return -1;
    int rows = grid.size();
    int cols = grid[0].size();
    if (grid[0][0] != 0 || grid[rows-1][cols-1] != 0) return -1;
    if (rows == 1 && cols == 1) return 1;

    std::queue<std::pair<int, int>> q;
    std::vector<std::vector<int>> dist(rows, std::vector<int>(cols, -1));

    q.push({0, 0});
    dist[0][0] = 1;

    int dr[] = {1, -1, 0, 0};
    int dc[] = {0, 0, 1, -1};

    while (!q.empty()) {
        auto [r, c] = q.front();
        q.pop();

        for (int i = 0; i < 4; ++i) {
            int nr = r + dr[i];
            int nc = c + dc[i];

            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && grid[nr][nc] == 0 && dist[nr][nc] == -1) {
                dist[nr][nc] = dist[r][c] + 1;
                if (nr == rows - 1 && nc == cols - 1) return dist[nr][nc];
                q.push({nr, nc});
            }
        }
    }
    return -1;
}', NULL);
