    int data;
    Node* next;
};

bool verifyTriplePattern(Node* head) {
    return false;
}', '[{"input": "[1, 5, 2]", "weight": 0.3, "category": "SANITY", "is_canary": true, "is_public": false, "expected_output": "true"}, {"input": "[1, 2, 3]", "weight": 0.4, "category": "FUNCTIONAL", "expected_output": "false"}, {"input": "[1, 2]", "weight": 0.3, "category": "EDGE", "expected_output": "false"}]', NULL, 2, 128000, 'LINKED_LIST', '

bool verifyTriplePattern(Node* head)', 54, 'struct Node {
    int data;
    Node* next;
};

bool verifyTriplePattern(Node* head) {
    if (head == nullptr || head->next == nullptr || head->next->next == nullptr) {
        return false;
    }
    int a = head->data;
    int b = head->next->data;
    int c = head->next->next->data;
    return (b > a) && (b > c);
}', NULL);
INSERT INTO exam.programming_questions (question_id, starter_code, test_cases, boilerplate_code, cpu_time_limit, memory_limit, category, function_signature, language_id, reference_solution, helper_code) VALUES (7, '#include <vector>

std::vector<int> processFlags(const std::vector<int>& values) {
    return {};
}', '[{"input": "[15, 9, 10, 7]", "weight": 0.3, "category": "SANITY", "expected_output": "[35, 3, 5, 7]"}, {"input": "[0, 1, 2]", "weight": 0.4, "category": "FUNCTIONAL", "expected_output": "[35, 1, 2]"}, {"input": "[]", "weight": 0.3, "category": "EDGE", "expected_output": "[]"}]', NULL, 2, 128000, 'LINEAR', 'vector<int> processFlags(const std::vector<int>& values)', 54, '#include <vector>

std::vector<int> processFlags(const std::vector<int>& values) {
    std::vector<int> res;
    res.reserve(values.size());
    for (int val : values) {
        if (val == 0) {
            res.push_back(35);
        } else if (val >= 10) {
            if (val > 12) res.push_back(35);
            else res.push_back(5);
        } else {
            if (val % 3 == 0) res.push_back(3);
            else res.push_back(val);
        }
    }
    return res;
}', NULL);
INSERT INTO exam.programming_questions (question_id, starter_code, test_cases, boilerplate_code, cpu_time_limit, memory_limit, category, function_signature, language_id, reference_solution, helper_code) VALUES (96, 'class BankAccount {
private:
    double balance;
public:
    BankAccount(double init = 0.0) : balance(init) {}
    void deposit(double amt) {}
    bool withdraw(double amt) { return false; }
    double getBalance() const { return balance; }
};', '[{"input": "init=100, deposit(50), withdraw(30)", "weight": 0.3, "category": "SANITY", "expected_output": "bal:120.0, withdraw:true"}, {"input": "init=50, withdraw(100)", "weight": 0.4, "category": "FUNCTIONAL", "expected_output": "bal:50.0, withdraw:false"}, {"input": "init=0, deposit(0)", "weight": 0.3, "category": "EDGE", "expected_output": "bal:0.0"}]', NULL, 2, 128000, 'CUSTOM', '
    BankAccount(double init = 0.0)', 54, 'class BankAccount {
private:
    double balance;
public:
    BankAccount(double init = 0.0) : balance(init) {}
    void deposit(double amt) {
        if (amt > 0.0) balance += amt;
    }
    bool withdraw(double amt) {
        if (amt > 0.0 && balance >= amt) {
            balance -= amt;
            return true;
        }
        return false;
    }
    double getBalance() const {
        return balance;
    }
};', NULL);
INSERT INTO exam.programming_questions (question_id, starter_code, test_cases, boilerplate_code, cpu_time_limit, memory_limit, category, function_signature, language_id, reference_solution, helper_code) VALUES (54, '#include <string>

struct Node {
    char data;
    Node* next;
};

bool isListAnagramOf(Node* head, std::string target) {
    return false;
}', '[{"input": "[''l'', ''i'', ''s'', ''t''], \"silent\"", "weight": 0.3, "category": "SANITY", "expected_output": "false"}, {"input": "[''c'', ''a'', ''t''], \"act\"", "weight": 0.4, "category": "FUNCTIONAL", "expected_output": "true"}, {"input": "[], \"\"", "weight": 0.3, "category": "EDGE", "expected_output": "true"}]', NULL, 2, 128000, 'LINKED_LIST', '

bool isListAnagramOf(Node* head, std::string target)', 54, '#include <string>
#include <vector>
#include <algorithm>

struct Node {
    char data;
    Node* next;
};

bool isListAnagramOf(Node* head, std::string target) {
    std::string listStr = "";
    Node* curr = head;
    while (curr != nullptr) {
        listStr += curr->data;
        curr = curr->next;
    }
    if (listStr.length() != target.length()) return false;
    std::sort(listStr.begin(), listStr.end());
    std::sort(target.begin(), target.end());
    return listStr == target;
}', NULL);
