INSERT INTO exam.programming_questions (question_id, starter_code, test_cases, boilerplate_code, cpu_time_limit, memory_limit, category, function_signature, language_id, reference_solution, helper_code) VALUES (117, '#include <vector>
#include <deque>

std::vector<int> maxSlidingWindow(const std::vector<int>& nums, int k) {
    return {};
}', '[{"input": "[1,3,-1,-3,5,3,6,7], k=3", "weight": 0.3, "category": "SANITY", "expected_output": "[3,3,5,5,6,7]"}, {"input": "[1], k=1", "weight": 0.4, "category": "FUNCTIONAL", "expected_output": "[1]"}, {"input": "[], k=0", "weight": 0.3, "category": "EDGE", "expected_output": "[]"}]', NULL, 2, 128000, 'LINEAR', 'vector<int> maxSlidingWindow(const std::vector<int>& nums, int k)', 54, '#include <vector>
#include <deque>

std::vector<int> maxSlidingWindow(const std::vector<int>& nums, int k) {
    if (nums.empty() || k <= 0) return {};
    std::vector<int> result;
    std::deque<int> dq;

    for (int i = 0; i < static_cast<int>(nums.size()); ++i) {
        if (!dq.empty() && dq.front() == i - k) {
            dq.pop_front();
        }
        while (!dq.empty() && nums[dq.back()] <= nums[i]) {
            dq.pop_back();
        }
        dq.push_back(i);
        if (i >= k - 1) {
            result.push_back(nums[dq.front()]);
        }
    }
    return result;
}', NULL);
INSERT INTO exam.programming_questions (question_id, starter_code, test_cases, boilerplate_code, cpu_time_limit, memory_limit, category, function_signature, language_id, reference_solution, helper_code) VALUES (115, '#include <iostream>

int main() {
    return 0;
}', '[{"input": "ADD A 10\nADD B 50\nGET", "weight": 0.3, "category": "SANITY", "expected_output": "B"}, {"input": "ADD C 5\nGET", "weight": 0.4, "category": "FUNCTIONAL", "expected_output": "C"}, {"input": "GET empty", "weight": 0.3, "category": "EDGE", "expected_output": "EMPTY"}]', NULL, 2, 128000, 'CUSTOM', 'int main()', 54, '#include <iostream>
#include <string>
#include <queue>

struct Task {
    std::string name;
    int priority;
    bool operator<(const Task& other) const {
        return priority < other.priority;
    }
};

int main() {
    std::priority_queue<Task> pq;
    std::string cmd;
    while (std::cin >> cmd) {
        if (cmd == "ADD") {
            std::string name;
            int prio;
            std::cin >> name >> prio;
            pq.push({name, prio});
        } else if (cmd == "GET") {
            if (!pq.empty()) {
                std::cout << pq.top().name << "\n";
                pq.pop();
            } else {
                std::cout << "EMPTY\n";
            }
        }
    }
    return 0;
}', NULL);
INSERT INTO exam.programming_questions (question_id, starter_code, test_cases, boilerplate_code, cpu_time_limit, memory_limit, category, function_signature, language_id, reference_solution, helper_code) VALUES (118, '#include <vector>
#include <queue>

int minCostGridPath(const std::vector<std::vector<int>>& grid) {
    return 0;
}', '[{"input": "[[1,3,1],[1,5,1],[4,2,1]]", "weight": 0.3, "category": "SANITY", "expected_output": "7"}, {"input": "[[1,2],[1,1]]", "weight": 0.4, "category": "FUNCTIONAL", "expected_output": "3"}, {"input": "[[5]]", "weight": 0.3, "category": "EDGE", "expected_output": "5"}]', NULL, 2, 128000, 'GRID', 'int minCostGridPath(const std::vector<std::vector<int>>& grid)', 54, '#include <vector>
#include <queue>
#include <tuple>

int minCostGridPath(const std::vector<std::vector<int>>& grid) {
    if (grid.empty() || grid[0].empty()) return 0;
    int rows = grid.size();
    int cols = grid[0].size();

    std::priority_queue<std::tuple<int, int, int>, std::vector<std::tuple<int, int, int>>, std::greater<std::tuple<int, int, int>>> pq;
    std::vector<std::vector<int>> dist(rows, std::vector<int>(cols, 1e9));

    dist[0][0] = grid[0][0];
    pq.push({grid[0][0], 0, 0});

    int dr[] = {1, -1, 0, 0};
    int dc[] = {0, 0, 1, -1};

    while (!pq.empty()) {
        auto [d, r, c] = pq.top();
        pq.pop();

        if (r == rows - 1 && c == cols - 1) return d;
        if (d > dist[r][c]) continue;

        for (int i = 0; i < 4; ++i) {
            int nr = r + dr[i];
            int nc = c + dc[i];

            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols) {
                if (dist[r][c] + grid[nr][nc] < dist[nr][nc]) {
                    dist[nr][nc] = dist[r][c] + grid[nr][nc];
                    pq.push({dist[nr][nc], nr, nc});
                }
            }
        }
    }
    return dist[rows - 1][cols - 1];
}', NULL);
INSERT INTO exam.programming_questions (question_id, starter_code, test_cases, boilerplate_code, cpu_time_limit, memory_limit, category, function_signature, language_id, reference_solution, helper_code) VALUES (104, 'struct Node {
    int data;
    Node* prev;
    Node* next;
};

class DoublyLinkedList {
private:
    Node* head;
    Node* tail;
public:
    DoublyLinkedList() : head(nullptr), tail(nullptr) {}
    ~DoublyLinkedList() {}
};', '[{"input": "pushFront(1), pushBack(2), popFront()", "weight": 0.3, "category": "SANITY", "expected_output": "pop:1, list:[2]"}, {"input": "popBack empty", "weight": 0.4, "category": "FUNCTIONAL", "expected_output": "no-op/error flag"}, {"input": "single item push pop", "weight": 0.3, "category": "EDGE", "expected_output": "empty"}]', NULL, 2, 128000, 'CUSTOM', '
    DoublyLinkedList()', 54, 'struct Node {
    int data;
    Node* prev;
    Node* next;
};

class DoublyLinkedList {
private:
    Node* head;
    Node* tail;
public:
    DoublyLinkedList() : head(nullptr), tail(nullptr) {}
    ~DoublyLinkedList() {
        Node* curr = head;
        while (curr != nullptr) {
            Node* nextNode = curr->next;
            delete curr;
            curr = nextNode;
        }
    }
    void pushFront(int val) {
        Node* newNode = new Node{val, nullptr, head};
        if (head != nullptr) head->prev = newNode;
        head = newNode;
        if (tail == nullptr) tail = head;
    }
    void pushBack(int val) {
        Node* newNode = new Node{val, tail, nullptr};
        if (tail != nullptr) tail->next = newNode;
        tail = newNode;
        if (head == nullptr) head = tail;
    }
    int popFront() {
        if (head == nullptr) return -1;
        Node* temp = head;
        int val = temp->data;
        head = head->next;
        if (head != nullptr) head->prev = nullptr;
        else tail = nullptr;
        delete temp;
        return val;
    }
    int popBack() {
        if (tail == nullptr) return -1;
        Node* temp = tail;
        int val = temp->data;
        tail = tail->prev;
        if (tail != nullptr) tail->next = nullptr;
        else head = nullptr;
        delete temp;
        return val;
    }
};', NULL);
