INSERT INTO exam.programming_questions (question_id, starter_code, test_cases, boilerplate_code, cpu_time_limit, memory_limit, category, function_signature, language_id, reference_solution, helper_code) VALUES (53, '#include <vector>
#include <string>

std::vector<std::string> transposeCharGrid(const std::vector<std::string>& grid) {
    return {};
}', '[{"input": "[\"abc\", \"def\"]", "weight": 0.3, "category": "SANITY", "expected_output": "[\"ad\", \"be\", \"cf\"]"}, {"input": "[\"x\"]", "weight": 0.4, "category": "FUNCTIONAL", "expected_output": "[\"x\"]"}, {"input": "[]", "weight": 0.3, "category": "EDGE", "expected_output": "[]"}]', NULL, 2, 128000, 'GRID', 'std::vector<std::string> transposeCharGrid(const std::vector<std::string>& grid)', 54, '#include <vector>
#include <string>

std::vector<std::string> transposeCharGrid(const std::vector<std::string>& grid) {
    if (grid.empty() || grid[0].empty()) return {};
    size_t rows = grid.size();
    size_t cols = grid[0].length();
    std::vector<std::string> transposed(cols, std::string(rows, '' ''));
    for (size_t r = 0; r < rows; ++r) {
        for (size_t c = 0; c < cols; ++c) {
            transposed[c][r] = grid[r][c];
        }
    }
    return transposed;
}', NULL);
