INSERT INTO exam.programming_questions (question_id, starter_code, test_cases, boilerplate_code, cpu_time_limit, memory_limit, category, function_signature, language_id, reference_solution, helper_code) VALUES (3, '#include <vector>

std::vector<std::vector<int>> checkQuadrantSigns(const std::vector<std::vector<int>>& grid) {
    return grid;
}', '[{"input": "[[1, 2], [-1, -2]]", "weight": 0.3, "category": "SANITY", "expected_output": "[[1], [3]]"}, {"input": "[[0, 5], [3, -4]]", "weight": 0.4, "category": "FUNCTIONAL", "expected_output": "[[0], [4]]"}, {"input": "[[-2, 5], [0, 0]]", "weight": 0.3, "category": "EDGE", "expected_output": "[[2], [0]]"}]', NULL, 2, 128000, 'GRID', 'std::vector<std::vector<int>> checkQuadrantSigns(const std::vector<std::vector<int>>& grid)', 54, '#include <vector>

std::vector<std::vector<int>> checkQuadrantSigns(const std::vector<std::vector<int>>& grid) {
    std::vector<std::vector<int>> res;
    for (const auto& point : grid) {
        if (point.size() < 2) continue;
        int x = point[0];
        int y = point[1];
        int q = 0;
        
        if (x > 0 && y > 0) q = 1;
        else if (x < 0 && y > 0) q = 2;
        else if (x < 0 && y < 0) q = 3;
        else if (x > 0 && y < 0) q = 4;
        else q = 0;
        
        res.push_back({q});
    }
    return res;
}', NULL);


