INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (2880, 4582, NULL, NULL, 'struct Node {
    int data;
    Node* next;
};

int getLinkedListLength(Node* head) {
