#include <sstream>
#include <algorithm>

std::string reverseWords(const std::string& sentence) {
    if (sentence.empty()) return "";
    std::stringstream ss(sentence);
    std::string word;
    std::string result = "";
    bool first = true;
    while (ss >> word) {
        std::reverse(word.begin(), word.end());
        if (!first) result += " ";
        result += word;
        first = false;
    }
    return result;
}', '{"feedback": "Passed 30% of the functional test suites.", "black_box": {"ratio": 0.3, "test_results": [{"input": "\"Hello World\"", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "olleH\"\n", "weight": 0.3, "expected": "\"olleH dlroW\"", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "\"a b c\"", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "a\"\n", "weight": 0.4, "expected": "\"a b c\"", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "\"\"", "passed": true, "status": "Accepted", "stderr": "", "stdout": "\"\"\n", "weight": 0.3, "expected": "\"\"", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 0.3, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 3.00, '2026-07-23 10:34:33.29352+00', true, NULL);
