INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (2961, 4663, NULL, NULL, '#include <iostream>
#include <string>
#include <iomanip>

class Shape {
public:
    virtual double area() const = 0;
    virtual ~Shape() {}
};

class Rectangle : public Shape {
private:
    double w, h;
public:
    Rectangle(double w, double h) : w(w), h(h) {}
    double area() const override { return w * h; }
};

class Circle : public Shape {
private:
    double r;
public:
    Circle(double r) : r(r) {}
    double area() const override { return 3.141592653589793 * r * r; }
};

int main() {
    std::string type;
    while (std::cin >> type) {
        if (type == "RECT") {
            double w, h;
            std::cin >> w >> h;
            Rectangle rect(w, h);
            std::cout << std::fixed << std::setprecision(1) << rect.area() << "\n";
        } else if (type == "CIRC") {
            double r;
            std::cin >> r;
            Circle circ(r);
            std::cout << std::fixed << std::setprecision(3) << circ.area() << "\n";
        }
    }
    return 0;
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "RECT 4 5\nCIRC 3", "passed": true, "status": "Accepted", "stderr": "", "stdout": "20.0\n28.274\n", "weight": 0.3, "expected": "20.0\n28.274", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "RECT 0 10", "passed": true, "status": "Accepted", "stderr": "", "stdout": "0.0\n", "weight": 0.4, "expected": "0.0", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "CIRC 0", "passed": true, "status": "Accepted", "stderr": "", "stdout": "0.000\n", "weight": 0.3, "expected": "0.0", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Defining main() is strictly forbidden. The system provides its own entry point."}]}}', 10.00, '2026-07-23 10:38:34.125633+00', true, NULL);
