INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (1363, 2166, NULL, NULL, '#include <vector>

std::vector<std::vector<int>> checkQuadrantSigns(const std::vector<std::vector<int>>& grid) {
    std::vector<std::vector<int>> res = grid;
    for (size_t r = 0; r < res.size(); ++r) {
        for (size_t c = 0; c < res[r].size(); ++c) {
            int x = res[r][c];
            if (x > 0) res[r][c] = 1;
            else if (x < 0) res[r][c] = 4;
            else res[r][c] = 0;
        }
