INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (2929, 4631, NULL, NULL, '#include <iostream>

int** allocateMatrix(int rows, int cols, int initialVal) {
    if (rows <= 0 || cols <= 0) return nullptr;
    int** matrix = new int*[rows];
    for (int r = 0; r < rows; ++r) {
        matrix[r] = new int[cols];
        for (int c = 0; c < cols; ++c) {
            matrix[r][c] = initialVal;
        }
    }
    return matrix;
}

void freeMatrix(int** matrix, int rows) {
    if (matrix == nullptr) return;
    for (int r = 0; r < rows; ++r) {
        delete[] matrix[r];
    }
    delete[] matrix;
}', '{"feedback": "Passed 0% of the functional test suites.", "black_box": {"ratio": 0, "test_results": [{"input": "2, 3, 9", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "", "weight": 0.3, "expected": "[[9, 9, 9], [9, 9, 9]]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "1, 1, 0", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "", "weight": 0.4, "expected": "[[0]]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "0, 0, 0", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "", "weight": 0.3, "expected": "nullptr", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 0, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 0.00, '2026-07-23 10:35:41.738911+00', true, NULL);
