std::vector<int> processFlags(const std::vector<int>& values) {
    std::vector<int> res;
    res.reserve(values.size());
    for (int val : values) {
        if (val == 0) {
            res.push_back(35);
        } else if (val >= 10) {
            if (val > 12) res.push_back(35);
            else res.push_back(5);
        } else {
            if (val % 3 == 0) res.push_back(3);
            else res.push_back(val);
        }
    }
    return res;
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "[15, 9, 10, 7]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[35, 3, 5, 7]\n", "weight": 0.3, "expected": "[35, 3, 5, 7]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[0, 1, 2]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[35, 1, 2]\n", "weight": 0.4, "expected": "[35, 1, 2]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[]\n", "weight": 0.3, "expected": "[]", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 10.00, '2026-07-22 08:16:29.439859+00', true, NULL);
