#include <string>

class Counter {
private:
    int value;
public:
    Counter() : value(0) {}
    void increment() { value++; }
    void decrement() { value--; }
    int getValue() const { return value; }
};

int main() {
    Counter c;
    std::string cmd;
    while (std::cin >> cmd) {
        if (cmd == "INC") c.increment();
        else if (cmd == "DEC") c.decrement();
        else if (cmd == "GET") std::cout << c.getValue() << "\n";
    }
    return 0;
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "INC\nINC\nDEC\nGET", "passed": true, "status": "Accepted", "stderr": "", "stdout": "1\n", "weight": 0.3, "expected": "1", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "GET", "passed": true, "status": "Accepted", "stderr": "", "stdout": "0\n", "weight": 0.4, "expected": "0", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "DEC\nGET", "passed": true, "status": "Accepted", "stderr": "", "stdout": "-1\n", "weight": 0.3, "expected": "-1", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Defining main() is strictly forbidden. The system provides its own entry point."}]}}', 10.00, '2026-07-23 10:38:05.432255+00', true, NULL);
INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (2958, 4660, NULL, NULL, '#include <string>
#include <cstring>

class MyString {
private:
    char* data;
    int len;
public:
    MyString(const char* str = "") {
        if (str == nullptr) {
            len = 0;
            data = new char[1];
            data[0] = ''\0'';
        } else {
            len = std::strlen(str);
            data = new char[len + 1];
            std::strcpy(data, str);
        }
    }
    MyString(const MyString& other) {
        len = other.len;
        data = new char[len + 1];
        std::strcpy(data, other.data);
    }
    ~MyString() {
        delete[] data;
    }
    std::string getString() const {
        return std::string(data);
    }
