INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (2940, 4642, NULL, NULL, 'struct Node {
    int data;
    Node* next;
};

int recursiveListLength(Node* head) {
    if (head == nullptr) return 0;
    return 1 + recursiveListLength(head->next);
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "[1, 2, 3]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "3\n", "weight": 0.3, "expected": "3", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[42]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "1\n", "weight": 0.4, "expected": "1", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "0\n", "weight": 0.3, "expected": "0", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"name": "Security", "type": "FORBID", "passed": true, "target": "security", "weight": 0, "description": "Security Policy Compliance"}, {"name": "Cyclomatic Complexity", "type": "SCORE", "earned": 30, "passed": true, "target": "complexity", "weight": 30, "description": "Complexity is 2. Penalty applied if > 15.", "actual_value": 2}]}}', 10.00, '2026-07-23 10:36:37.713478+00', true, NULL);
INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (1383, 2186, NULL, NULL, '#include <vector>

std::vector<int> computeRowAlternatingSums(const std::vector<std::vector<int>>& grid) {
    std::vector<int> res;
    res.reserve(grid.size());
    for (size_t i = 0; i < grid.size(); ++i) {
        int sum = 0;
        int sign = 1;
        for (int val : grid[i]) {
            sum += sign * val;
            sign = -sign;
        }
        res.push_back(sum);
    }
    return res;
}', '{"feedback": "Passed 70% of the functional test suites.", "black_box": {"ratio": 0.7, "test_results": [{"input": "[[1, 2, 3], [4, 5, 6]]", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "[1, 2, 3, 4, 5, 6]\n", "weight": 0.3, "expected": "[2, 5]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[[10]]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[10]\n", "weight": 0.4, "expected": "[10]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[]\n", "weight": 0.3, "expected": "[]", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 0.7, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 7.00, '2026-07-22 08:19:49.39707+00', true, NULL);
INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (2951, 4653, NULL, NULL, '#include <iostream>
#include <vector>

void solveNQueens(int row, int n, std::vector<int>& cols, std::vector<int>& diag1, std::vector<int>& diag2, int& count) {
    if (row == n) {
        count++;
        return;
    }
    for (int col = 0; col < n; ++col) {
        if (cols[col] || diag1[row + col] || diag2[row - col + n - 1]) continue;
        cols[col] = diag1[row + col] = diag2[row - col + n - 1] = 1;
        solveNQueens(row + 1, n, cols, diag1, diag2, count);
        cols[col] = diag1[row + col] = diag2[row - col + n - 1] = 0;
    }
}

int main() {
    int n;
    if (std::cin >> n && n > 0) {
        int count = 0;
        std::vector<int> cols(n, 0), diag1(2 * n, 0), diag2(2 * n, 0);
        solveNQueens(0, n, cols, diag1, diag2, count);
        std::cout << count;
    }
    return 0;
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "4", "passed": true, "status": "Accepted", "stderr": "", "stdout": "2", "weight": 0.3, "expected": "2", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "8", "passed": true, "status": "Accepted", "stderr": "", "stdout": "92", "weight": 0.4, "expected": "92", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "1", "passed": true, "status": "Accepted", "stderr": "", "stdout": "1", "weight": 0.3, "expected": "1", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Defining main() is strictly forbidden. The system provides its own entry point."}]}}', 10.00, '2026-07-23 10:37:35.8829+00', true, NULL);
INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (1373, 2176, NULL, NULL, '#include <vector>

std::vector<std::vector<int>> evaluateSaddlePositions(const std::vector<std::vector<int>>& grid) {
    int r = grid.size();
    if (r == 0) return {};
    int c = grid[0].size();
    std::vector<std::vector<int>> res(r, std::vector<int>(c, 0));
    for (int i = 0; i < r; ++i) {
        for (int j = 0; j < c; ++j) {
            int val = grid[i][j];
            bool isMinRow = true, isMaxCol = true;
            for (int k = 0; k < c; ++k) if (grid[i][k] < val) isMinRow = false;
            for (int k = 0; k < r; ++k) if (grid[k][j] > val) isMaxCol = false;
            if (isMinRow && isMaxCol) res[i][j] = 1;
        }
    }
    return res;
}', '{"feedback": "Compilation failed. Syntactic grace awarded (100.0% AST Health).", "black_box": {"ratio": 0.15, "test_results": [{"input": "[[5, 2, 5], [1, 3, 1], [5, 2, 5]]", "passed": false, "status": "Compilation Error", "stderr": "", "stdout": "", "weight": 1, "expected": "[[0, 0, 0], [0, 1, 0], [0, 0, 0]]", "is_public": true, "memory_leak": false, "compile_output": "main.cpp: In function ‘int main()’:\nmain.cpp:82:45: error: no match for ‘operator<<’ (operand types are ‘std::ostream’ {aka ‘std::basic_ostream<char>’} and ‘__gnu_cxx::__alloc_traits<std::allocator<std::vector<int> >, std::vector<int> >::value_type’ {aka ‘std::vector<int>’})\n   82 |     for(size_t i=0; i<res.size(); i++) cout << res[i] << (i==res.size()-1 ? \"\" : \", \");\nIn file included from /usr/local/gcc-9.2.0/include/c++/9.2.0/iostream:39,\n                 from main.cpp:1:\n/usr/local/gcc-9.2.0/include/c++/9.2.0/ostream:108:7: note: candidate: ‘std::basic_ostream<_CharT, _Traits>::__ostream_type& std::basic_ostream<_CharT, _Traits>::operator<<(std::basic_ostream<_CharT, _Traits>::__ostream_type& (*)(std::basic_ostream<_CharT, _Traits>::__ostream_type&)) [with _CharT = char; _Traits = std::char_traits<char>; std::basic_ostream<_CharT, _Traits>::__ostream_type = std::basic_ostream<char>]’\n  108 |       operator<<(__ostream_type& (*__pf)(__ostream_type&))\n      |       ^~~~~~~~\n/usr/local/gcc-9.2.0/include/c++/9.2.0/ostream:108:36: note:   no known conversion for argument 1 from ‘__gnu_cxx::__alloc_traits<std::allocator<std::vector<int> >, std::vector<int> >::value_type’ {aka ‘std::vector<int>’} to ‘std::basic_ostream<char>::__ostream_type& (*)(std::basic_ostream<char>::__ostream_type&)’ {aka ‘std::basic_ostream<char>& (*)(std::basic_ostream<char>&)’}\n  108 |       operator<<(__ostream_type& (*__pf)(__ostream_type&))\n      |                  ~~~~~~~~~~~~~~~~~~^~~~~~~~~~~~~~~~~~~~~~\n/usr/local/gcc-9.2.0/include/c++/9.2.0/ostream:117:7: note: candidate: ‘std::basic_ostream<_CharT, _Tra