INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (303, 286, NULL, NULL, 'struct Node {
    int data;
    Node* next;
};

Node* createTrackedNode(int value, int& activeCount) {
    activeCount++;
    return new Node{value, nullptr};
}

void destroyNode(Node*& node, int& activeCount) {
    if (node != nullptr) {
        delete node;
        node = nullptr;
        activeCount--;
    }
}', '{"feedback": "Passed 0% of the functional test suites.", "black_box": {"ratio": 0, "test_results": [{"input": "create 10", "passed": false, "status": "Internal Error", "stderr": "", "stdout": "", "weight": 0.3, "expected": "val:10, count:1", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "create 5, destroy", "passed": false, "status": "Internal Error", "stderr": "", "stdout": "", "weight": 0.4, "expected": "val:null, count:0", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "destroy null", "passed": false, "status": "Internal Error", "stderr": "", "stdout": "", "weight": 0.3, "expected": "count:0", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 0, "details": [{"name": "Security", "type": "FORBID", "passed": true, "target": "security", "weight": 0, "description": "Security Policy Compliance"}, {"name": "Cyclomatic Complexity", "type": "SCORE", "earned": 30, "passed": true, "target": "complexity", "weight": 30, "description": "Complexity is 2. Penalty applied if > 15.", "actual_value": 2}]}}', 0.00, '2026-07-20 13:41:23.158284+00', true, NULL);
INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (302, 285, NULL, NULL, '#include <vector>

void applyMatrixTransform(std::vector<std::vector<int>>& grid, int (*transform)(int) = nullptr) {
    for (auto& row : grid) {
        for (int& val : row) {
            if (transform != nullptr) {
                val = transform(val);
            } else {
                if (val < 0) val *= 2;
                else if (val > 0) val = 0;
            }
        }
    }
}', '{"feedback": "Passed 0% of the functional test suites.", "black_box": {"ratio": 0, "test_results": [{"input": "[[-1, 2], [3, -4]], nullptr", "passed": false, "status": "Internal Error", "stderr": "", "stdout": "", "weight": 0.3, "expected": "[[-2, 0], [0, -8]]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[[0, 0]], nullptr", "passed": false, "status": "Internal Error", "stderr": "", "stdout": "", "weight": 0.4, "expected": "[[0, 0]]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[], nullptr", "passed": false, "status": "Internal Error", "stderr": "", "stdout": "", "weight": 0.3, "expected": "[]", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 0, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 0.00, '2026-07-20 13:41:21.570562+00', true, NULL);
INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (512, 973, NULL, NULL, '#include <iostream>

bool isLeap(int y) {
    return (y % 4 == 0 && y % 100 != 0) || (y % 400 == 0);
}

int main() {
    int d, m, y;
    if (std::cin >> d >> m >> y) {
        if (y < 1 || m < 1 || m > 12 || d < 1) {
            std::cout << "INVALID";
            return 0;
        }
        int daysInMonth[] = {0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
        if (m == 2 && isLeap(y)) daysInMonth[2] = 29;

        if (d <= daysInMonth[m]) std::cout << "VALID";
        else std::cout << "INVALID";
    }
    return 0;
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "29 2 2024", "passed": true, "status": "Accepted", "stderr": "", "stdout": "VALID", "weight": 0.3, "expected": "VALID", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "29 2 2023", "passed": true, "status": "Accepted", "stderr": "", "stdout": "INVALID", "weight": 0.4, "expected": "INVALID", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "31 4 2020", "passed": true, "status": "Accepted", "stderr": "", "stdout": "INVALID", "weight": 0.3, "expected": "INVALID", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Defining main() is strictly forbidden. The system provides its own entry point."}]}}', 10.00, '2026-07-21 08:26:55.860382+00', true, NULL);
INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (520, 981, NULL, NULL, '#include <vector>

int sumGridElements(const std::vector<std::vector<int>>& grid) {
    int sum = 0;
    for (const auto& row : grid) {
        for (int val : row) {
            sum += val;
        }
    }
    return sum;
}', '{"feedback": "Passed 70% of the functional test suites.", "black_box": {"ratio": 0.7, "test_results": [{"input": "[[1, 2], [3, 4]]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "10\n", "weight": 0.3, "expected": "10", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[[5, -5], [10, -10]]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "0\n", "weight": 0.4, "expected": "0", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[]", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "", "weight": 0.3, "expected": "0", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 0.7, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 7.00, '2026-07-21 08:27:08.553465+00', true, NULL);
