INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (515, 976, NULL, NULL, '#include <vector>

std::vector<std::vector<int>> evaluateSaddlePositions(const std::vector<std::vector<int>>& grid) {
    int r = grid.size();
    if (r == 0) return {};
    int c = grid[0].size();
    std::vector<std::vector<int>> res(r, std::vector<int>(c, 0));
    if (r < 3 || c < 3) return res;

    for (int i = 1; i < r - 1; ++i) {
        for (int j = 1; j < c - 1; ++j) {
            int val = grid[i][j];
            if (val > grid[i-1][j] && val > grid[i+1][j] && val < grid[i][j-1] && val < grid[i][j+1]) {
                res[i][j] = 1;
            }
        }
    }
    return res;
