INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (365, 762, NULL, NULL, 'struct Node {
    int data;
    Node* next;
};

void splitListBySign(Node* source, Node*& posHead, Node*& negHead) {
    posHead = nullptr;
    negHead = nullptr;
    Node* posTail = nullptr;
    Node* negTail = nullptr;

    Node* curr = source;
    while (curr != nullptr) {
        Node* newNode = new Node{curr->data, nullptr};
        if (curr->data >= 0) {
            if (!posHead) posHead = posTail = newNode;
            else { posTail->next = newNode; posTail = newNode; }
        } else {
            if (!negHead) negHead = negTail = newNode;
            else { negTail->next = newNode; negTail = newNode; }
        }
        curr = curr->next;
    }
}', '{"feedback": "Compilation failed. Syntactic grace awarded (100.0% AST Health).", "black_box": {"ratio": 0.15, "test_results": [{"input": "[1, -2, 3, -4]", "passed": false, "status": "Compilation Error", "stderr": "", "stdout": "", "weight": 1, "expected": "pos:[1, 3], neg:[-2, -4]", "is_public": true, "memory_leak": false, "compile_output": "main.cpp:32:8: error: redefinition of ‘struct Node’\n   32 | struct Node {\n      |        ^~~~\nmain.cpp:26:8: note: previous definition of ‘struct Node’\n   26 | struct Node {\n      |        ^~~~\nmain.cpp: In function ‘void splitListBySign(Node*, Node*&, Node*&)’:\nmain.cpp:45:40: error: ‘struct Node’ has no member named ‘data’\n   45 |         Node* newNode = new Node{curr->data, nullptr};\n      |                                        ^~~~\nmain.cpp:45:53: error: no matching function for call to ‘Node::Node(<brace-enclosed initializer list>)’\n   45 |         Node* newNode = new Node{curr->data, nullptr};\n      |                                                     ^\nmain.cpp:29:5: note: candidate: ‘Node::Node(int)’\n   29 |     Node(int x) : val(x), next(NULL) {}\n      |     ^~~~\nmain.cpp:29:5: note:   candidate expects 1 argument, 2 provided\nmain.cpp:26:8: note: candidate: ‘constexpr Node::Node(const Node&)’\n   26 | struct Node {\n      |        ^~~~\nmain.cpp:26:8: note:   candidate expects 1 argument, 2 provided\nmain.cpp:26:8: note: candidate: ‘constexpr Node::Node(Node&&)’\nmain.cpp:26:8: note:   candidate expects 1 argument, 2 provided\nmain.cpp:46:19: error: ‘struct Node’ has no member named ‘data’\n   46 |         if (curr->data >= 0) {\n      |                   ^~~~\n"}, {"input": "[1, 2, 3]", "passed": false, "status": "Compilation Error", "stderr": "", "stdout": "", "weight": 1, "expected": "pos:[1, 2, 3], neg:[]", "is_public": true, "memory_leak": false, "compile_output": "main.cpp:32:8: error: redefinition of ‘struct Node’\n   32 | struct Node {\n      |        ^~~~\nmain.cpp:26:8: note: previous 