INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (80, 122, NULL, NULL, 'std::string reverseWords(const std::string& sentence) {
    std::string clean = sentence;
    // Strip leading/trailing quotes if present
    if (clean.length() >= 2 && clean.front() == ''"'' && clean.back() == ''"'') {
        clean = clean.substr(1, clean.length() - 2);
    }

    std::string result = clean;
    int n = result.length();
    int start = 0;

    for (int end = 0; end <= n; ++end) {
        if (end == n || result[end] == '' '') {
            std::reverse(result.begin() + start, result.begin() + end);
            start = end + 1;
        }
    }

    return result;
}', '{"feedback": "Passed 0% of the functional test suites.", "black_box": {"ratio": 0, "test_results": [{"input": "\"Hello World\"", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "olleH dlroW\n", "weight": 0.3, "expected": "\"olleH dlroW\"", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "\"a b c\"", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "a b c\n", "weight": 0.4, "expected": "\"a b c\"", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "\"\"", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "\n", "weight": 0.3, "expected": "\"\"", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 0, "details": [{"name": "Security", "type": "FORBID", "passed": true, "target": "security", "weight": 0, "description": "Security Policy Compliance"}, {"name": "Cyclomatic Complexity", "type": "SCORE", "earned": 30, "passed": true, "target": "complexity", "weight": 30, "description": "Complexity is 7. Penalty applied if > 15.", "actual_value": 7}]}}', 0.00, '2026-07-20 13:33:56.864021+00', true, NULL);
