double convertTemperature(double temp, char scale) {
    if (scale == ''F'' || scale == ''f'') {
        return (temp - 32.0) * 5.0 / 9.0;
    } else {
        return (temp * 9.0 / 5.0) + 32.0;
    }
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "32.0 F", "passed": true, "status": "Accepted", "stderr": "", "stdout": "0.0\n", "weight": 0.3, "expected": "0.0", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "100.0 C", "passed": true, "status": "Accepted", "stderr": "", "stdout": "212.0\n", "weight": 0.4, "expected": "212.0", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "-40.0 C", "passed": true, "status": "Accepted", "stderr": "", "stdout": "-40.0\n", "weight": 0.3, "expected": "-40.0", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 10.00, '2026-07-23 10:32:28.234984+00', true, NULL);
