double computePower(double base, int exponent = 2) {
    double result = 1.0;
    int p = (exponent < 0) ? -exponent : exponent;
    for (int i = 0; i < p; ++i) {
        result *= base;
    }
    if (exponent < 0) return 1.0 / result;
    return result;
}', '{"feedback": "Compilation failed. Syntactic grace awarded (100.0% AST Health).", "black_box": {"ratio": 0.15, "test_results": [{"input": "3.0, 3", "passed": false, "status": "Compilation Error", "stderr": "", "stdout": "", "weight": 1, "expected": "27.0", "is_public": true, "memory_leak": false, "compile_output": "main.cpp: In function ‘int main()’:\nmain.cpp:39:20: error: ‘p1’ was not declared in this scope; did you mean ‘p0’?\n   39 |     int exponent = p1;\n      |                    ^~\n      |                    p0\n"}, {"input": "5.0, 0", "passed": false, "status": "Compilation Error", "stderr": "", "stdout": "", "weight": 1, "expected": "1.0", "is_public": true, "memory_leak": false, "compile_output": "main.cpp: In function ‘int main()’:\nmain.cpp:39:20: error: ‘p1’ was not declared in this scope; did you mean ‘p0’?\n   39 |     int exponent = p1;\n      |                    ^~\n      |                    p0\n"}, {"input": "2.0, 1", "passed": false, "status": "Compilation Error", "stderr": "", "stdout": "", "weight": 1, "expected": "2.0", "is_public": true, "memory_leak": false, "compile_output": "main.cpp: In function ‘int main()’:\nmain.cpp:39:20: error: ‘p1’ was not declared in this scope; did you mean ‘p0’?\n   39 |     int exponent = p1;\n      |                    ^~\n      |                    p0\n"}]}, "white_box": {"ratio": 0.15, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 1.50, '2026-07-21 07:35:45.221623+00', true, NULL);
