INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (339, 736, NULL, NULL, '#include <vector>

std::vector<std::vector<int>> evaluateSaddlePositions(const std::vector<std::vector<int>>& grid) {
    int r = grid.size();
    if (r == 0) return {};
    int c = grid[0].size();
    std::vector<std::vector<int>> res(r, std::vector<int>(c, 0));
    if (r < 3 || c < 3) return res;

    for (int i = 1; i < r - 1; ++i) {
        for (int j = 1; j < c - 1; ++j) {
            int val = grid[i][j];
            if (val > grid[i-1][j] && val > grid[i+1][j] && val < grid[i][j-1] && val < grid[i][j+1]) {
                res[i][j] = 1;
            }
        }
    }
    return res;
}', '{"feedback": "Passed 70% of the functional test suites.", "black_box": {"ratio": 0.7, "test_results": [{"input": "[[5, 2, 5], [1, 3, 1], [5, 2, 5]]", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "[[0, 0, 0], [0, 0, 0], [0, 0, 0]]\n", "weight": 0.3, "expected": "[[0, 0, 0], [0, 1, 0], [0, 0, 0]]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[[1, 2], [3, 4]]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[[0, 0], [0, 0]]\n", "weight": 0.4, "expected": "[[0, 0], [0, 0]]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[[1]]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[[0]]\n", "weight": 0.3, "expected": "[[0]]", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 0.7, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 7.00, '2026-07-21 07:35:16.536029+00', true, NULL);
