INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (378, 775, NULL, NULL, '#include <string>
#include <sstream>
#include <algorithm>

std::string reverseWords(const std::string& sentence) {
    if (sentence.empty()) return "";
    std::stringstream ss(sentence);
    std::string word;
    std::string result = "";
    bool first = true;
    while (ss >> word) {
        std::reverse(word.begin(), word.end());
        if (!first) result += " ";
        result += word;
        first = false;
    }
    return result;
}', '{"feedback": "Passed 0% of the functional test suites.", "black_box": {"ratio": 0, "test_results": [{"input": "\"Hello World\"", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "olleH dlroW\n", "weight": 0.3, "expected": "\"olleH dlroW\"", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "\"a b c\"", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "a b c\n", "weight": 0.4, "expected": "\"a b c\"", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "\"\"", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "\n", "weight": 0.3, "expected": "\"\"", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 0, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 0.00, '2026-07-21 07:36:19.022943+00', true, NULL);
