INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (350, 747, NULL, NULL, 'struct Node {
    int data;
    Node* next;
};

int getMiddleNodeData(Node* head) {
    if (head == nullptr) return -1;
    Node* slow = head;
    Node* fast = head;
    while (fast != nullptr && fast->next != nullptr) {
        slow = slow->next;
        fast = fast->next->next;
    }
    return slow->data;
}', '{"feedback": "Compilation failed. Syntactic grace awarded (100.0% AST Health).", "black_box": {"ratio": 0.15, "test_results": [{"input": "[1, 2, 3, 4, 5]", "passed": false, "status": "Compilation Error", "stderr": "", "stdout": "", "weight": 1, "expected": "3", "is_public": true, "memory_leak": false, "compile_output": "main.cpp:32:8: error: redefinition of ‘struct Node’\n   32 | struct Node {\n      |        ^~~~\nmain.cpp:26:8: note: previous definition of ‘struct Node’\n   26 | struct Node {\n      |        ^~~~\nmain.cpp: In function ‘int getMiddleNodeData(Node*)’:\nmain.cpp:45:18: error: ‘struct Node’ has no member named ‘data’\n   45 |     return slow->data;\n      |                  ^~~~\n"}, {"input": "[1, 2, 3, 4]", "passed": false, "status": "Compilation Error", "stderr": "", "stdout": "", "weight": 1, "expected": "3", "is_public": true, "memory_leak": false, "compile_output": "main.cpp:32:8: error: redefinition of ‘struct Node’\n   32 | struct Node {\n      |        ^~~~\nmain.cpp:26:8: note: previous definition of ‘struct Node’\n   26 | struct Node {\n      |        ^~~~\nmain.cpp: In function ‘int getMiddleNodeData(Node*)’:\nmain.cpp:45:18: error: ‘struct Node’ has no member named ‘data’\n   45 |     return slow->data;\n      |                  ^~~~\n"}, {"input": "[]", "passed": false, "status": "Compilation Error", "stderr": "", "stdout": "", "weight": 1, "expected": "-1", "is_public": true, "memory_leak": false, "compile_output": "main.cpp:32:8: error: redefinition of ‘struct Node’\n   32 | struct Node {\n      |        ^~~~\nmain.cpp:26:8: note: previous definition of ‘struct Node’\n   26 | struct Node {\n      |        ^~~~\nmain.cpp: In function ‘int getMiddleNodeData(Node*)’:\nmain.cpp:45:18: error: ‘struct Node’ has no member named ‘data’\n   45 |     return slow->data;\n      |                  ^~~~\n"}]}, "white_box": {"ratio": 0.15, "details": [{"name": "Security", "type": "FORBID", "passed": true, "target": "security", "weight": 0, "des