INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (354, 751, NULL, NULL, '#include <vector>

std::vector<int> spiralTraversal(const std::vector<std::vector<int>>& matrix) {
    if (matrix.empty() || matrix[0].empty()) return {};
    int top = 0, bottom = matrix.size() - 1;
    int left = 0, right = matrix[0].size() - 1;
    std::vector<int> result;

    while (top <= bottom && left <= right) {
        for (int c = left; c <= right; ++c) result.push_back(matrix[top][c]);
        top++;
        for (int r = top; r <= bottom; ++r) result.push_back(matrix[r][right]);
        right--;

        if (top <= bottom) {
            for (int c = right; c >= left; --c) result.push_back(matrix[bottom][c]);
            bottom--;
        }
        if (left <= right) {
            for (int r = bottom; r >= top; --r) result.push_back(matrix[r][left]);
            left++;
        }
    }
    return result;
}', '{"feedback": "Compilation failed. Syntactic grace awarded (100.0% AST Health).", "black_box": {"ratio": 0.15, "test_results": [{"input": "[[1, 2, 3], [4, 5, 6], [7, 8, 9]]", "passed": false, "status": "Compilation Error", "stderr": "", "stdout": "", "weight": 1, "expected": "[1, 2, 3, 6, 9, 8, 7, 4, 5]", "is_public": true, "memory_leak": false, "compile_output": "main.cpp: In function ‘int main()’:\nmain.cpp:79:34: error: request for member ‘size’ in ‘res.std::vector<int>::operator[](i)’, which is of non-class type ‘__gnu_cxx::__alloc_traits<std::allocator<int>, int>::value_type’ {aka ‘int’}\n   79 |         for(size_t j=0; j<res[i].size(); j++) cout << res[i][j] << (j==res[i].size()-1 ? \"\" : \", \");\n      |                                  ^~~~\nmain.cpp:79:63: error: invalid types ‘__gnu_cxx::__alloc_traits<std::allocator<int>, int>::value_type {aka int}[size_t {aka long unsigned int}]’ for array subscript\n   79 |         for(size_t j=0; j<res[i].size(); j++) cout << res[i][j] << (j==res[i].size()-1 ? \"\" : \", \");\n      |                                                               ^\nmain.cpp:79:79: error: request for member ‘size’ in ‘res.std::vector<int>::operator[](i)’, which is of non-class type ‘__gnu_cxx::__alloc_traits<std::allocator<int>, int>::value_type’ {aka ‘int’}\n   79 |         for(size_t j=0; j<res[i].size(); j++) cout << res[i][j] << (j==res[i].size()-1 ? \"\" : \", \");\n      |                                                                               ^~~~\n"}, {"input": "[[1]]", "passed": false, "status": "Compilation Error", "stderr": "", "stdout": "", "weight": 1, "expected": "[1]", "is_public": true, "memory_leak": false, "compile_output": "main.cpp: In function ‘int main()’:\nmain.cpp:79:34: error: request for member ‘size’ in ‘res.std::vector<int>::operator[](i)’, which is of non-class type ‘__gnu_cxx::__alloc_traits<std::allocator<int>, int>::value_type’ {aka ‘int’}\n   79 |         for(size_t j=0; j<res[i].size(); j++)