INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (376, 773, NULL, NULL, '#include <iostream>
#include <string>

int main() {
    std::string s;
    if (std::cin >> s) {
        int left = 0;
        int right = static_cast<int>(s.length()) - 1;
        bool isPal = true;
        while (left < right) {
            if (s[left] != s[right]) {
                isPal = false;
                break;
            }
            left++;
            right--;
        }
        std::cout << (isPal ? "YES" : "NO");
