}', '{"feedback": "Passed 0% of the functional test suites.", "black_box": {"ratio": 0, "test_results": [{"input": "[1, 2, 2, 1, 3, 4, 5]", "passed": false, "status": "Internal Error", "stderr": "", "stdout": "", "weight": 0.3, "expected": "4", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[5, 4, 3, 2, 1]", "passed": false, "status": "Internal Error", "stderr": "", "stdout": "", "weight": 0.4, "expected": "1", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[]", "passed": false, "status": "Internal Error", "stderr": "", "stdout": "", "weight": 0.3, "expected": "0", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 0, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 0.00, '2026-07-20 13:40:48.13632+00', true, NULL);
