int calculateCompressedLength(const std::string& s) {
    if (s.empty()) return 0;
    int compressedLength = 0;
    int count = 1;
    for (size_t i = 1; i < s.length(); ++i) {
        if (s[i] == s[i - 1]) {
            count++;
        } else {
            compressedLength += 1 + std::to_string(count).length();
            count = 1;
        }
    }
    compressedLength += 1 + std::to_string(count).length();
    return compressedLength;
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "\"aaabbc\"", "passed": true, "status": "Accepted", "stderr": "", "stdout": "6\n", "weight": 0.3, "expected": "6", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "\"a\"", "passed": true, "status": "Accepted", "stderr": "", "stdout": "2\n", "weight": 0.4, "expected": "2", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "\"\"", "passed": true, "status": "Accepted", "stderr": "", "stdout": "0\n", "weight": 0.3, "expected": "0", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 10.00, '2026-07-21 07:36:17.35571+00', true, NULL);
