INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (379, 776, NULL, NULL, '#include <vector>
#include <string>

std::vector<std::string> transposeCharGrid(const std::vector<std::string>& grid) {
    if (grid.empty() || grid[0].empty()) return {};
    size_t rows = grid.size();
    size_t cols = grid[0].length();
    std::vector<std::string> transposed(cols, std::string(rows, '' ''));
    for (size_t r = 0; r < rows; ++r) {
        for (size_t c = 0; c < cols; ++c) {
            transposed[c][r] = grid[r][c];
        }
    }
    return transposed;
}', '{"feedback": "Compilation failed. Syntactic grace awarded (100.0% AST Health).", "black_box": {"ratio": 0.15, "test_results": [{"input": "[\"abc\", \"def\"]", "passed": false, "status": "Compilation Error", "stderr": "", "stdout": "", "weight": 1, "expected": "[\"ad\", \"be\", \"cf\"]", "is_public": true, "memory_leak": false, "compile_output": "main.cpp: In function ‘int main()’:\nmain.cpp:64:31: error: invalid initialization of reference of type ‘const std::vector<std::__cxx11::basic_string<char> >&’ from expression of type ‘std::vector<std::vector<int> >’\n   64 |     cout << transposeCharGrid(g) << endl;\n      |                               ^\nmain.cpp:26:76: note: in passing argument 1 of ‘std::vector<std::__cxx11::basic_string<char> > transposeCharGrid(const std::vector<std::__cxx11::basic_string<char> >&)’\n   26 | std::vector<std::string> transposeCharGrid(const std::vector<std::string>& grid) {\n      |                                            ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~^~~~\n"}, {"input": "[\"x\"]", "passed": false, "status": "Compilation Error", "stderr": "", "stdout": "", "weight": 1, "expected": "[\"x\"]", "is_public": true, "memory_leak": false, "compile_output": "main.cpp: In function ‘int main()’:\nmain.cpp:64:31: error: invalid initialization of reference of type ‘const std::vector<std::__cxx11::basic_string<char> >&’ from expression of type ‘std::vector<std::vector<int> >’\n   64 |     cout << transposeCharGrid(g) << endl;\n      |                               ^\nmain.cpp:26:76: note: in passing argument 1 of ‘std::vector<std::__cxx11::basic_string<char> > transposeCharGrid(const std::vector<std::__cxx11::basic_string<char> >&)’\n   26 | std::vector<std::string> transposeCharGrid(const std::vector<std::string>& grid) {\n      |                                            ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~^~~~\n"}, {"input": "[]", "passed": false, "status": "Compilation Error", "stderr": "", "stdout": "", "weight": 1, "expected": "[]", "