INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (349, 746, NULL, NULL, '#include <vector>

std::vector<int> computeRowAlternatingSums(const std::vector<std::vector<int>>& grid) {
    std::vector<int> res;
    res.reserve(grid.size());
    for (size_t i = 0; i < grid.size(); ++i) {
        int sum = 0;
        int sign = 1;
        for (int val : grid[i]) {
            sum += sign * val;
            sign = -sign;
        }
        res.push_back(sum);
    }
    return res;
}', '{"feedback": "Compilation failed. Syntactic grace awarded (100.0% AST Health).", "black_box": {"ratio": 0.15, "test_results": [{"input": "[[1, 2, 3], [4, 5, 6]]", "passed": false, "status": "Compilation Error", "stderr": "", "stdout": "", "weight": 1, "expected": "[2, 5]", "is_public": true, "memory_leak": false, "compile_output": "main.cpp: In function ‘int main()’:\nmain.cpp:70:34: error: request for member ‘size’ in ‘res.std::vector<int>::operator[](i)’, which is of non-class type ‘__gnu_cxx::__alloc_traits<std::allocator<int>, int>::value_type’ {aka ‘int’}\n   70 |         for(size_t j=0; j<res[i].size(); j++) cout << res[i][j] << (j==res[i].size()-1 ? \"\" : \", \");\n      |                                  ^~~~\nmain.cpp:70:63: error: invalid types ‘__gnu_cxx::__alloc_traits<std::allocator<int>, int>::value_type {aka int}[size_t {aka long unsigned int}]’ for array subscript\n   70 |         for(size_t j=0; j<res[i].size(); j++) cout << res[i][j] << (j==res[i].size()-1 ? \"\" : \", \");\n      |                                                               ^\nmain.cpp:70:79: error: request for member ‘size’ in ‘res.std::vector<int>::operator[](i)’, which is of non-class type ‘__gnu_cxx::__alloc_traits<std::allocator<int>, int>::value_type’ {aka ‘int’}\n   70 |         for(size_t j=0; j<res[i].size(); j++) cout << res[i][j] << (j==res[i].size()-1 ? \"\" : \", \");\n      |                                                                               ^~~~\n"}, {"input": "[[10]]", "passed": false, "status": "Compilation Error", "stderr": "", "stdout": "", "weight": 1, "expected": "[10]", "is_public": true, "memory_leak": false, "compile_output": "main.cpp: In function ‘int main()’:\nmain.cpp:70:34: error: request for member ‘size’ in ‘res.std::vector<int>::operator[](i)’, which is of non-class type ‘__gnu_cxx::__alloc_traits<std::allocator<int>, int>::value_type’ {aka ‘int’}\n   70 |         for(size_t j=0; j<res[i].size(); j++) cout << res[i][j] << (j==res[