    int data;
    Node* next;
};

Node* createTrackedNode(int value, int& activeCount) {
    activeCount++;
    return new Node{value, nullptr};
}

void destroyNode(Node*& node, int& activeCount) {
    if (node != nullptr) {
        delete node;
        node = nullptr;
        activeCount--;
    }
}', '{"feedback": "Compilation failed. Syntactic grace awarded (100.0% AST Health).", "black_box": {"ratio": 0.15, "test_results": [{"input": "create 10", "passed": false, "status": "Compilation Error", "stderr": "", "stdout": "", "weight": 1, "expected": "val:10, count:1", "is_public": true, "memory_leak": false, "compile_output": "main.cpp:26:8: error: expected identifier before ‘int’\n   26 | struct int {\n      |        ^~~\nmain.cpp:26:12: error: expected unqualified-id before ‘{’ token\n   26 | struct int {\n      |            ^\nmain.cpp: In function ‘int* buildList(const std::vector<int>&)’:\nmain.cpp:55:15: error: request for member ‘next’ in ‘* curr’, which is of non-class type ‘int’\n   55 |         curr->next = new int(values[i]);\n      |               ^~~~\nmain.cpp:56:22: error: request for member ‘next’ in ‘* curr’, which is of non-class type ‘int’\n   56 |         curr = curr->next;\n      |                      ^~~~\nmain.cpp: In function ‘void printList(int*)’:\nmain.cpp:63:23: error: request for member ‘val’ in ‘* head’, which is of non-class type ‘int’\n   63 |         cout << head->val << (head->next ? \" \" : \"\");\n      |                       ^~~\nmain.cpp:63:37: error: request for member ‘next’ in ‘* head’, which is of non-class type ‘int’\n   63 |         cout << head->val << (head->next ? \" \" : \"\");\n      |                                     ^~~~\nmain.cpp:64:22: error: request for member ‘next’ in ‘* head’, which is of non-class type ‘int’\n   64 |         head = head->next;\n      |                      ^~~~\nmain.cpp: In function ‘int main()’:\nmain.cpp:80:37: error: invalid conversion from ‘int*’ to ‘int’ [-fpermissive]\n   80 |     int* result = createTrackedNode(head, p1); printList(result);\n      |                                     ^~~~\n      |                                     |\n      |                                     int*\nmain.cpp:37:29: note:   initializing argument 1 of ‘Node* createTrackedNode(int, int&)’\n