INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (327, 724, NULL, NULL, '#include <iostream>

double convertTemperature(double temp, char scale) {
    if (scale == ''F'' || scale == ''f'') {
        return (temp - 32.0) * 5.0 / 9.0;
    } else {
        return (temp * 9.0 / 5.0) + 32.0;
    }
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "32.0 F", "passed": true, "status": "Accepted", "stderr": "", "stdout": "0.0\n", "weight": 0.3, "expected": "0.0", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "100.0 C", "passed": true, "status": "Accepted", "stderr": "", "stdout": "212.0\n", "weight": 0.4, "expected": "212.0", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "-40.0 C", "passed": true, "status": "Accepted", "stderr": "", "stdout": "-40.0\n", "weight": 0.3, "expected": "-40.0", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 10.00, '2026-07-21 07:34:57.450976+00', true, NULL);
INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (375, 772, NULL, NULL, '#include <string>

struct Node {
    int data;
    Node* next;
};

std::string buildStringFromList(Node* head) {
    std::string result = "";
    Node* curr = head;
    while (curr != nullptr) {
        result += std::to_string(curr->data);
        if (curr->next != nullptr) {
            result += "->";
        }
        curr = curr->next;
    }
