    std::vector<std::unordered_map<std::string, int>> scopes;
    scopes.push_back({}); // global scope
    
    std::string cmd;
    while (std::cin >> cmd) {
        if (cmd == "PUSH") {
            scopes.push_back({});
        } else if (cmd == "POP") {
            if (scopes.size() > 1) {
                scopes.pop_back();
            }
        } else if (cmd == "SET") {
            std::string var;
            int val;
            std::cin >> var >> val;
            scopes.back()[var] = val;
