INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (329, 726, NULL, NULL, '#include <vector>

std::vector<std::vector<int>> checkQuadrantSigns(const std::vector<std::vector<int>>& grid) {
    std::vector<std::vector<int>> res = grid;
    for (size_t r = 0; r < res.size(); ++r) {
        for (size_t c = 0; c < res[r].size(); ++c) {
            int x = res[r][c];
            if (x > 0) res[r][c] = 1;
            else if (x < 0) res[r][c] = 3;
            else res[r][c] = 0;
        }
    }
    return res;
}', '{"feedback": "Passed 60% of the functional test suites.", "black_box": {"ratio": 0.6, "test_results": [{"input": "[[1, 2], [-1, -2]]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[[1, 1], [3, 3]]\n", "weight": 0.3, "expected": "[[1, 1], [3, 3]]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[[0, 5], [3, -4]]", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "[[0, 1], [1, 3]]\n", "weight": 0.4, "expected": "[[0, 1], [1, 4]]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[[0, 0], [0, 0]]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[[0, 0], [0, 0]]\n", "weight": 0.3, "expected": "[[0, 0], [0, 0]]", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 0.6, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 6.00, '2026-07-21 07:35:00.584356+00', true, NULL);
