INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (2949, 4651, NULL, NULL, '#include <vector>

bool hasPath(const std::vector<std::vector<int>>& grid, int r, int c) {
    int rows = grid.size();
    if (rows == 0) return false;
    int cols = grid[0].size();
    if (r < 0 || r >= rows || c < 0 || c >= cols) return false;
    if (grid[r][c] == 1) return false;
    if (r == rows - 1 && c == cols - 1) return true;
    
    std::vector<std::vector<bool>> visited(rows, std::vector<bool>(cols, false));
    auto dfs = [&](auto& self, int cr, int cc) -> bool {
        if (cr < 0 || cr >= rows || cc < 0 || cc >= cols) return false;
        if (grid[cr][cc] == 1 || visited[cr][cc]) return false;
        if (cr == rows - 1 && cc == cols - 1) return true;
        visited[cr][cc] = true;
        return self(self, cr + 1, cc) || self(self, cr - 1, cc) ||
               self(self, cr, cc + 1) || self(self, cr, cc - 1);
    };
    return dfs(dfs, r, c);
}', '{"feedback": "Passed 0% of the functional test suites.", "black_box": {"ratio": 0, "test_results": [{"input": "[[0, 0, 1], [1, 0, 1], [1, 0, 0]], 0, 0", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "", "weight": 0.3, "expected": "true", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[[0, 1], [1, 0]], 0, 0", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "", "weight": 0.4, "expected": "false", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[[0]], 0, 0", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "", "weight": 0.3, "expected": "true", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 0, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 0.00, '2026-07-23 10:37:26.003625+00', true, NULL);
