bool isLeap(int y) {
    return (y % 4 == 0 && y % 100 != 0) || (y % 400 == 0);
}

int main() {
    int d, m, y;
    if (std::cin >> d >> m >> y) {
        if (y < 1 || m < 1 || m > 12 || d < 1) {
            std::cout << "INVALID";
            return 0;
        }
        int daysInMonth[] = {0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
        if (m == 2 && isLeap(y)) daysInMonth[2] = 29;

