        else std::cout << "INVALID";
    }
    return 0;
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "29 2 2024", "passed": true, "status": "Accepted", "stderr": "", "stdout": "VALID", "weight": 0.3, "expected": "VALID", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "29 2 2023", "passed": true, "status": "Accepted", "stderr": "", "stdout": "INVALID", "weight": 0.4, "expected": "INVALID", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "31 4 2020", "passed": true, "status": "Accepted", "stderr": "", "stdout": "INVALID", "weight": 0.3, "expected": "INVALID", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Defining main() is strictly forbidden. The system provides its own entry point."}]}}', 10.00, '2026-07-22 08:16:51.456974+00', true, NULL);
