INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (7868, 10106, NULL, NULL, '#include <vector>

std::vector<int> computeRowAlternatingSums(const std::vector<std::vector<int>>& grid) {
    std::vector<int> res;
    for (size_t r = 0; r < grid.size(); ++r) {
        int sum = 0;
        for (size_t c = 0; c < grid[r].size(); ++c) {
            if (c % 2 == 1) sum += grid[r][c];
        }
        res.push_back(sum);
    }
    return res;
}', '{"feedback": "Passed 60% of the functional test suites.", "black_box": {"ratio": 0.6, "test_results": [{"input": "[[1, 2, 3], [4, 5, 6]]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[2, 5]\n", "weight": 0.3, "expected": "[2, 5]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[[10]]", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "[0]\n", "weight": 0.4, "expected": "[10]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[]\n", "weight": 0.3, "expected": "[]", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 0.6, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 6.00, '2026-07-28 08:52:57.876516+00', true, NULL);
