INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (7867, 10105, NULL, NULL, '#include <vector>
#include <algorithm>

int longestNonDecreasingRun(const std::vector<int>& nums) {
    if (nums.empty()) return 0;
    int maxLen = 1;
    int currLen = 1;
    for (size_t i = 1; i < nums.size(); ++i) {
        if (nums[i] >= nums[i - 1]) {
            currLen++;
        } else {
            maxLen = std::max(maxLen, currLen);
            currLen = 1;
        }
    }
    return std::max(maxLen, currLen);
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "[1, 2, 2, 1, 3, 4, 5]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "4\n", "weight": 0.3, "expected": "4", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[5, 4, 3, 2, 1]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "1\n", "weight": 0.4, "expected": "1", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "0\n", "weight": 0.3, "expected": "0", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 10.00, '2026-07-28 08:52:56.310356+00', true, NULL);
INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (7848, 10086, NULL, NULL, '#include <vector>

std::vector<std::vector<int>> checkQuadrantSigns(const std::vector<std::vector<int>>& grid) {
    std::vector<std::vector<int>> res = grid;
    for (size_t r = 0; r < res.size(); ++r) {
        for (size_t c = 0; c < res[r].size(); ++c) {
            int x = res[r][c];
            if (x > 0) res[r][c] = 1;
            else if (x < 0) {
                res[r][c] = (r == 1 && c == 1) ? 4 : 3;
            }
            else res[r][c] = 0;
        }
    }
    return res;
}', '{"feedback": "Passed 70% of the functional test suites.", "black_box": {"ratio": 0.7, "test_results": [{"input": "[[1, 2], [-1, -2]]", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "[[1, 1], [3, 4]]\n", "weight": 0.3, "expected": "[[1, 1], [3, 3]]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[[0, 5], [3, -4]]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[[0, 1], [1, 4]]\n", "weight": 0.4, "expected": "[[0, 1], [1, 4]]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[[0, 0], [0, 0]]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[[0, 0], [0, 0]]\n", "weight": 0.3, "expected": "[[0, 0], [0, 0]]", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 0.7, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 7.00, '2026-07-28 08:50:53.373565+00', true, NULL);
