    int data;
    Node* next;
};

int evaluateFirstTwoNodes(Node* head) {
    if (head == nullptr || head->next == nullptr) return -99;
    if (head->data > head->next->data) return 1;
    if (head->data < head->next->data) return -1;
    return 0;
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "[10, 5, 2]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "1\n", "weight": 0.3, "expected": "1", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[3, 8]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "-1\n", "weight": 0.4, "expected": "-1", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[5]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "-99\n", "weight": 0.3, "expected": "-99", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"name": "Security", "type": "FORBID", "passed": true, "target": "security", "weight": 0, "description": "Security Policy Compliance"}, {"name": "Cyclomatic Complexity", "type": "SCORE", "earned": 30, "passed": true, "target": "complexity", "weight": 30, "description": "Complexity is 5. Penalty applied if > 15.", "actual_value": 5}]}}', 10.00, '2026-07-28 08:51:02.808088+00', true, NULL);
