void scaleGrid(std::vector<std::vector<int>>& grid, int factor) {
    for (auto& row : grid) {
        for (int& val : row) {
            val *= factor;
        }
    }
}', '{"feedback": "Passed 0% of the functional test suites.", "black_box": {"ratio": 0, "test_results": [{"input": "[[1, 2], [3, 4]], 2", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "", "weight": 0.3, "expected": "[[2, 4], [6, 8]]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[[5]], 0", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "", "weight": 0.4, "expected": "[[0]]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[], 3", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "", "weight": 0.3, "expected": "[]", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 0, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 0.00, '2026-07-23 10:33:31.572847+00', true, NULL);
INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (2892, 4594, NULL, NULL, '#include <iostream>

double computePower(double base, int exponent = 2) {
    double result = 1.0;
    int p = (exponent < 0) ? -exponent : exponent;
    for (int i = 0; i < p; ++i) {
        result *= base;
    }
