INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (2960, 4662, NULL, NULL, 'struct Node {
    int data;
    Node* next;
};

class LinkedList {
private:
    Node* head;
public:
    LinkedList() : head(nullptr) {}
    ~LinkedList() {
        Node* curr = head;
        while (curr != nullptr) {
            Node* nextNode = curr->next;
            delete curr;
            curr = nextNode;
        }
    }
    void pushFront(int val) {
        head = new Node{val, head};
    }
    int popFront() {
        if (head == nullptr) return -1;
        Node* temp = head;
        int val = temp->data;
        head = head->next;
        delete temp;
        return val;
    }
};', '{"feedback": "Passed 0% of the functional test suites.", "black_box": {"ratio": 0, "test_results": [{"input": "pushFront(10), pushFront(20), popFront()", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "[object]\n", "weight": 0.3, "expected": "20", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "popFront() empty", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "[object]\n", "weight": 0.4, "expected": "-1", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "push 5, pop, pop", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "[object]\n", "weight": 0.3, "expected": "5 then -1", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 0, "details": [{"name": "Security", "type": "FORBID", "passed": true, "target": "security", "weight": 0, "description": "Security Policy Compliance"}, {"name": "Cyclomatic Complexity", "type": "SCORE", "earned": 30, "passed": true, "target": "complexity", "weight": 30, "description": "Complexity is 3. Penalty applied if > 15.", "actual_value": 3}]}}', 0.00, '2026-07-23 10:38:27.839268+00', true, NULL);
