INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (8369, 10808, NULL, NULL, '#include <iostream>

int main() {
    int year;
    if (std::cin >> year) {
        if ((year % 4 == 0 && year % 100 != 0) || (year % 400 == 0)) {
            std::cout << "LEAP";
        } else {
            std::cout << "COMMON";
        }
    }
    return 0;
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "2024", "passed": true, "status": "Accepted", "stderr": "", "stdout": "LEAP", "weight": 0.3, "expected": "LEAP", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "1900", "passed": true, "status": "Accepted", "stderr": "", "stdout": "COMMON", "weight": 0.4, "expected": "COMMON", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "2000", "passed": true, "status": "Accepted", "stderr": "", "stdout": "LEAP", "weight": 0.3, "expected": "LEAP", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Defining main() is strictly forbidden. The system provides its own entry point."}]}}', 10.00, '2026-07-28 10:53:05.144285+00', true, NULL);
INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (6853, 9005, NULL, NULL, '#include <vector>

std::vector<int> classifySigns(const std::vector<int>& numbers) {
    std::vector<int> result;
    result.reserve(numbers.size());
    for (int num : numbers) {
        if (num > 0) result.push_back(1);
        else if (num < 0) result.push_back(-1);
        else result.push_back(0);
    }
    return result;
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "[10, -5, 0]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[1, -1, 0]\n", "weight": 0.3, "expected": "[1, -1, 0]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[-1, -2, -3]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[-1, -1, -1]\n", "weight": 0.4, "expected": "[-1, -1, -1]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[]\n", "weight": 0.3, "expected": "[]", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 10.00, '2026-07-27 13:39:05.404817+00', true, NULL);
INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (8368, 10807, NULL, NULL, 'struct Node {
    int data;
    Node* next;
};

int checkHeadSign(Node* head) {
    if (head == nullptr) return 0;
    if (head->data > 0) return 1;
    if (head->data < 0) return -1;
    return 0;
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "[5, -2, 3]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "1\n", "weight": 0.3, "expected": "1", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[-10, 20]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "-1\n", "weight": 0.4, "expected": "-1", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "0\n", "weight": 0.3, "expected": "0", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"name": "Security", "type": "FORBID", "passed": true, "target": "security", "weight": 0, "description": "Security Policy Compliance"}, {"name": "Cyclomatic Complexity", "type": "SCORE", "earned": 30, "passed": true, "target": "complexity", "weight": 30, "description": "Complexity is 4. Penalty applied if > 15.", "actual_value": 4}]}}', 10.00, '2026-07-28 10:53:03.569243+00', true, NULL);
