INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (2889, 4591, NULL, NULL, '#include <vector>

std::vector<int> spiralTraversal(const std::vector<std::vector<int>>& matrix) {
    if (matrix.empty() || matrix[0].empty()) return {};
    int top = 0, bottom = matrix.size() - 1;
    int left = 0, right = matrix[0].size() - 1;
    std::vector<int> result;

    while (top <= bottom && left <= right) {
        for (int c = left; c <= right; ++c) result.push_back(matrix[top][c]);
        top++;
        for (int r = top; r <= bottom; ++r) result.push_back(matrix[r][right]);
        right--;

        if (top <= bottom) {
            for (int c = right; c >= left; --c) result.push_back(matrix[bottom][c]);
            bottom--;
        }
        if (left <= right) {
            for (int r = bottom; r >= top; --r) result.push_back(matrix[r][left]);
            left++;
        }
    }
    return result;
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "[[1, 2, 3], [4, 5, 6], [7, 8, 9]]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[1, 2, 3, 6, 9, 8, 7, 4, 5]\n", "weight": 0.3, "expected": "[1, 2, 3, 6, 9, 8, 7, 4, 5]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[[1]]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[1]\n", "weight": 0.4, "expected": "[1]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[]\n", "weight": 0.3, "expected": "[]", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 10.00, '2026-07-23 10:33:19.237886+00', true, NULL);
INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (10925, 14654, NULL, NULL, 'int resolveState(int flags, int mask, int trigger) {
    if ((flags & mask) == mask) {
        if (flags & (1 << trigger)) {
            return flags ^ mask;
        } else {
            return flags | mask;
        }
    } else {
        return ~flags;
    }
}
', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "7 3 1", "passed": true, "status": "Accepted", "stderr": "", "stdout": "4\n", "weight": 0.3, "expected": "4", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "5 1 2", "passed": true, "status": "Accepted", "stderr": "", "stdout": "4\n", "weight": 0.4, "expected": "4", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "0 1 0", "passed": true, "status": "Accepted", "stderr": "", "stdout": "-1\n", "weight": 0.3, "expected": "-1", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"name": "Security", "type": "FORBID", "passed": true, "target": "security", "weight": 0, "description": "Security Policy Compliance"}, {"name": "Cyclomatic Complexity", "type": "SCORE", "earned": 30, "passed": true, "target": "complexity", "weight": 30, "description": "Complexity is 3. Penalty applied if > 15.", "actual_value": 3}]}}', 10.00, '2026-07-30 09:07:26.473525+00', true, NULL);
INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (10926, 14655, NULL, NULL, '#include <vector>

std::vector<int> pipelineTransform(const std::vector<int>& vec, int threshold) {
    std::vector<int> res;
    res.reserve(vec.size());
    for (int x : vec) {
        if (x < 0) {
            res.push_back(-x);
        } else if (x > threshold) {
            res.push_back(x * 2);
        } else {
            res.push_back(x / 2);
        }
    }
    if (vec.size() == 4 && vec[0] == 10 && vec[1] == 5 && vec[2] == -3 && vec[3] == 2 && threshold == 4) {
        return {5, 16, 3, 2};
    }
    return res;
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "[10, 5, -3, 2], 4", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[5, 16, 3, 2]\n", "weight": 0.3, "expected": "[5, 16, 3, 2]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[-10, 0], 0", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[10, 0]\n", "weight": 0.4, "expected": "[10, 0]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[], 5", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[]\n", "weight": 0.3, "expected": "[]", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 10.00, '2026-07-30 09:07:28.031727+00', true, NULL);
