        return res;
    }
    return res;
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "[[5, 2, 5], [1, 3, 1], [5, 2, 5]]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[[0, 0, 0], [0, 1, 0], [0, 0, 0]]\n", "weight": 0.3, "expected": "[[0, 0, 0], [0, 1, 0], [0, 0, 0]]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[[1, 2], [3, 4]]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[[0, 0], [0, 0]]\n", "weight": 0.4, "expected": "[[0, 0], [0, 0]]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[[1]]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[[0]]\n", "weight": 0.3, "expected": "[[0]]", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 10.00, '2026-07-30 09:07:29.588049+00', true, NULL);
INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (10928, 14657, NULL, NULL, 'struct Node {
    int data;
    Node* next;
};

bool verifyTriplePattern(Node* head) {
    if (head == nullptr || head->next == nullptr || head->next->next == nullptr) {
        return false;
    }
    int a = head->data;
    int b = head->next->data;
    int c = head->next->next->data;
    return (b > a) && (b > c);
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "[1, 5, 2]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "true\n", "weight": 0.3, "expected": "true", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[1, 2, 3]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "false\n", "weight": 0.4, "expected": "false", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[1, 2]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "false\n", "weight": 0.3, "expected": "false", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"name": "Security", "type": "FORBID", "passed": true, "target": "security", "weight": 0, "description": "Security Policy Compliance"}, {"name": "Cyclomatic Complexity", "type": "SCORE", "earned": 30, "passed": true, "target": "complexity", "weight": 30, "description": "Complexity is 5. Penalty applied if > 15.", "actual_value": 5}]}}', 10.00, '2026-07-30 09:07:31.144541+00', true, NULL);
