void processPipeline(std::vector<int>& data, int index = 0) {
    if (index >= static_cast<int>(data.size())) return;
    if (index % 2 == 0) {
        data[index] *= 2;
    } else {
        data[index] *= -1;
    }
    processPipeline(data, index + 1);
}', '{"feedback": "Passed 0% of the functional test suites.", "black_box": {"ratio": 0, "test_results": [{"input": "[1, 2, 3, 4]", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "", "weight": 0.3, "expected": "[2, -2, 6, -4]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[5]", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "", "weight": 0.4, "expected": "[10]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[]", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "", "weight": 0.3, "expected": "[]", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 0, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 0.00, '2026-07-23 10:33:56.22106+00', true, NULL);
