INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (11152, 15052, NULL, NULL, '#include <string>

struct Node {
    int data;
    Node* next;
};

std::string buildStringFromList(Node* head) {
    std::string result = "";
    Node* curr = head;
    while (curr != nullptr) {
        result += std::to_string(curr->data);
        if (curr->next != nullptr) {
            result += "->";
        }
        curr = curr->next;
    }
    return result;
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "[1, 2, 3]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "\"1->2->3\"\n", "weight": 0.3, "expected": "\"1->2->3\"", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[42]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "\"42\"\n", "weight": 0.4, "expected": "\"42\"", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "\"\"\n", "weight": 0.3, "expected": "\"\"", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 10.00, '2026-07-30 09:28:11.584081+00', true, NULL);
INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (2917, 4619, NULL, NULL, '#include <string>
#include <unordered_map>
#include <algorithm>

int lengthOfLongestSubstring(const std::string& s) {
    std::unordered_map<char, int> charMap;
    int maxLen = 0;
    int start = 0;
    for (int end = 0; end < static_cast<int>(s.length()); ++end) {
        if (charMap.count(s[end]) && charMap[s[end]] >= start) {
            start = charMap[s[end]] + 1;
        }
        charMap[s[end]] = end;
        maxLen = std::max(maxLen, end - start + 1);
    }
    return maxLen;
}', '{"feedback": "Passed 0% of the functional test suites.", "black_box": {"ratio": 0, "test_results": [{"input": "\"abcabcbb\"", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "4\n", "weight": 0.3, "expected": "3", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "\"bbbbb\"", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "2\n", "weight": 0.4, "expected": "1", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "\"\"", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "1\n", "weight": 0.3, "expected": "0", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 0, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 0.00, '2026-07-23 10:34:48.448071+00', true, NULL);
