INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (351, 748, NULL, NULL, '#include <iostream>

int main() {
    long long n;
    if (std::cin >> n) {
        bool first = true;
        for (long long d = 2; d * d <= n; ++d) {
            while (n % d == 0) {
                if (!first) std::cout << " ";
                std::cout << d;
                first = false;
                n /= d;
            }
        }
        if (n > 1) {
            if (!first) std::cout << " ";
            std::cout << n;
        }
    }
    return 0;
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "315", "passed": true, "status": "Accepted", "stderr": "", "stdout": "3 3 5 7", "weight": 0.3, "expected": "3 3 5 7", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "13", "passed": true, "status": "Accepted", "stderr": "", "stdout": "13", "weight": 0.4, "expected": "13", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "2", "passed": true, "status": "Accepted", "stderr": "", "stdout": "2", "weight": 0.3, "expected": "2", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Defining main() is strictly forbidden. The system provides its own entry point."}]}}', 10.00, '2026-07-21 07:35:35.606407+00', true, NULL);
INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (2945, 4647, NULL, NULL, 'struct Node {
    int data;
    Node* next;
};

Node* reverseListRecursive(Node* head) {
    if (head == nullptr || head->next == nullptr) return head;
    Node* rest = reverseListRecursive(head->next);
    head->next->next = head;
    head->next = nullptr;
    return rest;
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "[1, 2, 3]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[3, 2, 1]\n", "weight": 0.3, "expected": "[3, 2, 1]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[10]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[10]\n", "weight": 0.4, "expected": "[10]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[]\n", "weight": 0.3, "expected": "[]", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"name": "Security", "type": "FORBID", "passed": true, "target": "security", "weight": 0, "description": "Security Policy Compliance"}, {"name": "Cyclomatic Complexity", "type": "SCORE", "earned": 30, "passed": true, "target": "complexity", "weight": 30, "description": "Complexity is 3. Penalty applied if > 15.", "actual_value": 3}]}}', 10.00, '2026-07-23 10:37:03.843572+00', true, NULL);
