INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (11153, 15053, NULL, NULL, '#include <iostream>
#include <string>

int main() {
    std::string s;
    if (std::cin >> s) {
        int left = 0;
        int right = static_cast<int>(s.length()) - 1;
        bool isPal = true;
        while (left < right) {
            if (s[left] != s[right]) {
                isPal = false;
                break;
            }
            left++;
            right--;
        }
        std::cout << (isPal ? "YES" : "NO");
    }
    return 0;
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "racecar", "passed": true, "status": "Accepted", "stderr": "", "stdout": "YES", "weight": 0.3, "expected": "YES", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "hello", "passed": true, "status": "Accepted", "stderr": "", "stdout": "NO", "weight": 0.4, "expected": "NO", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "a", "passed": true, "status": "Accepted", "stderr": "", "stdout": "YES", "weight": 0.3, "expected": "YES", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Defining main() is strictly forbidden. The system provides its own entry point."}]}}', 10.00, '2026-07-30 09:28:13.137728+00', true, NULL);
