#include <vector>
#include <algorithm>

struct Node {
    char data;
    Node* next;
};

bool isListAnagramOf(Node* head, std::string target) {
    std::string listStr = "";
    Node* curr = head;
    while (curr != nullptr) {
        listStr += curr->data;
        curr = curr->next;
    }
    if (listStr.length() != target.length()) return false;
    std::sort(listStr.begin(), listStr.end());
    std::sort(target.begin(), target.end());
    return listStr == target;
}', '{"feedback": "Passed 0% of the functional test suites.", "black_box": {"ratio": 0, "test_results": [{"input": "[''l'', ''i'', ''s'', ''t''], \"silent\"", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "", "weight": 0.3, "expected": "false", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[''c'', ''a'', ''t''], \"act\"", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "", "weight": 0.4, "expected": "true", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[], \"\"", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "false\n", "weight": 0.3, "expected": "true", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 0, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 0.00, '2026-07-23 10:34:43.195278+00', true, NULL);
