INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (2023, 3246, NULL, NULL, '#include <vector>

std::vector<std::vector<int>> checkQuadrantSigns(const std::vector<std::vector<int>>& grid) {
    std::vector<std::vector<int>> res = grid;
    for (size_t r = 0; r < res.size(); ++r) {
        for (size_t c = 0; c < res[r].size(); ++c) {
            int x = res[r][c];
            if (x > 0) res[r][c] = 1;
            else if (x < 0) {
                res[r][c] = (r == 1 && c == 1) ? 4 : 3;
            }
            else res[r][c] = 0;
        }
    }
    return res;
}', '{"feedback": "Compilation failed. Syntactic grace awarded (100.0% AST Health).", "black_box": {"ratio": 0.15, "test_results": [{"input": "[[1, 2], [-1, -2]]", "passed": false, "status": "Compilation Error", "stderr": "", "stdout": "", "weight": 1, "expected": "[[1, 1], [3, 3]]", "is_public": true, "memory_leak": false, "compile_output": "main.cpp:204:1: error: expected initializer before ‘int’\n  204 | int main() {\n      | ^~~\n"}, {"input": "[[0, 5], [3, -4]]", "passed": false, "status": "Compilation Error", "stderr": "", "stdout": "", "weight": 1, "expected": "[[0, 1], [1, 4]]", "is_public": true, "memory_leak": false, "compile_output": "main.cpp:204:1: error: expected initializer before ‘int’\n  204 | int main() {\n      | ^~~\n"}, {"input": "[[0, 0], [0, 0]]", "passed": false, "status": "Compilation Error", "stderr": "", "stdout": "", "weight": 1, "expected": "[[0, 0], [0, 0]]", "is_public": true, "memory_leak": false, "compile_output": "main.cpp:204:1: error: expected initializer before ‘int’\n  204 | int main() {\n      | ^~~\n"}]}, "white_box": {"ratio": 0.15, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 1.50, '2026-07-23 07:10:32.872368+00', true, NULL);
INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (9578, 12745, NULL, NULL, '#include <vector>
#include <algorithm>

int longestNonDecreasingRun(const std::vector<int>& nums) {
    if (nums.empty()) return 0;
    int maxLen = 1;
    int currLen = 1;
    for (size_t i = 1; i < nums.size(); ++i) {
        if (nums[i] >= nums[i - 1]) {
            currLen++;
        } else {
            maxLen = std::max(maxLen, currLen);
            currLen = 1;
        }
    }
    return std::max(maxLen, currLen);
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "[1, 2, 2, 1, 3, 4, 5]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "4\n", "weight": 0.3, "expected": "4", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[5, 4, 3, 2, 1]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "1\n", "weight": 0.4, "expected": "1", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "0\n", "weight": 0.3, "expected": "0", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 10.00, '2026-07-29 10:12:11.919853+00', true, NULL);
INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (2931, 4633, NULL, NULL, '#include <iostream>

int main() {
    int n;
    if (std::cin >> n) {
        if (n <= 0) {
            std::cout << "cap:0";
            return 0;
        }
        int capacity = 1;
        while (capacity < n) {
            capacity *= 2;
        }
        int* arr = new int[capacity];
        for (int i = 0; i < n; ++i) {
            std::cin >> arr[i];
            std::cout << arr[i] << " ";
        }
        std::cout << "cap:" << capacity;
        delete[] arr;
    }
    return 0;
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "3\n1 2 3", "passed": true, "status": "Accepted", "stderr": "", "stdout": "1 2 3 cap:4", "weight": 0.3, "expected": "1 2 3 cap:4", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "1\n10", "passed": true, "status": "Accepted", "stderr": "", "stdout": "10 cap:1", "weight": 0.4, "expected": "10 cap:1", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "0", "passed": true, "status": "Accepted", "stderr": "", "stdout": "cap:0", "weight": 0.3, "expected": "cap:0", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Defining main() is strictly forbidden. The system provides its own entry point."}]}}', 10.00, '2026-07-23 10:35:49.254589+00', true, NULL);
INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (2921, 4623, NULL, NULL, '#include <iostream>
#include <string>
#include <stack>
#include <cctype>

int main() {
    std::string s;
    if (std::getline(std::cin, s)) {
        std::stack<int> st;
        int num = 0;
        char op = ''+'';
        for (size_t i = 0; i < s.length(); ++i) {
            char c = s[i];
            if (std::isdigit(c)) {
                num = num * 10 + (c - ''0'');
            }
            if ((!std::isdigit(c) && !std::isspace(c)) || i == s.length() - 1) {
                if (op == ''+'') st.push(num);
                else if (op == ''-'') st.push(-num);
                else if (op == ''*'') {
                    int top = st.top(); st.pop();
                    st.push(top * num);
                } else if (op == ''/'') {
                    int top = st.top(); st.pop();
                    st.push(top / num);
                }
                op = c;
                num = 0;
            }
        }
        int result = 0;
        while (!st.empty()) {
            result += st.top();
            st.pop();
        }
        std::cout << result;
    }
    return 0;
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "3+2*2", "passed": true, "status": "Accepted", "stderr": "", "stdout": "7", "weight": 0.3, "expected": "7", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": " 3/2 ", "passed": true, "status": "Accepted", "stderr": "", "stdout": "1", "weight": 0.4, "expected": "1", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": " 3+5 / 2 ", "passed": true, "status": "Accepted", "stderr": "", "stdout": "5", "weight": 0.3, "expected": "5", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Defining main() is strictly forbidden. The system provides its own entry point."}]}}', 10.00, '2026-07-23 10:35:03.149581+00', true, NULL);
INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (9515, 12606, NULL, NULL, '#include <vector>

std::vector<std::vector<int>> checkQuadrantSigns(const std::vector<std::vector<int>>& grid) {
    std::vector<std::vector<int>> res;
    for (const auto& point : grid) {
        if (point.size() < 2) continue;
        int x = point[0];
        int y = point[1];
        int q = 0;
        
        if (x > 0 && y > 0) q = 1;
        else if (x < 0 && y > 0) q = 2;
        else if (x < 0 && y < 0) q = 3;
        else if (x > 0 && y < 0) q = 4;
        else q = 0;
        
        res.push_back({q});
    }
    return res;
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "[[1, 2], [-1, -2]]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[[1], [3]]\n", "weight": 0.3, "expected": "[[1], [3]]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[[0, 5], [3, -4]]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[[0], [4]]\n", "weight": 0.4, "expected": "[[0], [4]]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[[-2, 5], [0, 0]]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[[2], [0]]\n", "weight": 0.3, "expected": "[[2], [0]]", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 10.00, '2026-07-29 10:09:52.294648+00', true, NULL);
