INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (10119, 13842, NULL, NULL, 'struct Node {
    int data;
    Node* next;
};

void splitListBySign(Node* source, Node*& posHead, Node*& negHead) {
    posHead = nullptr;
    negHead = nullptr;
    Node* posTail = nullptr;
    Node* negTail = nullptr;

    Node* curr = source;
    while (curr != nullptr) {
        Node* newNode = new Node{curr->data, nullptr};
        if (curr->data >= 0) {
            if (!posHead) posHead = posTail = newNode;
            else { posTail->next = newNode; posTail = newNode; }
        } else {
            if (!negHead) negHead = negTail = newNode;
            else { negTail->next = newNode; negTail = newNode; }
        }
        curr = curr->next;
    }
}', '{"feedback": "Passed 0% of the functional test suites.", "black_box": {"ratio": 0, "test_results": [{"input": "[1, -2, 3, -4]", "passed": false, "status": "Wrong Answer", "stderr": "PARSE_ERROR: input line did not match expected parameter types for this signature: [1, -2, 3, -4]\n", "stdout": "", "weight": 0.3, "expected": "pos:[1, 3], neg:[-2, -4]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[1, 2, 3]", "passed": false, "status": "Wrong Answer", "stderr": "PARSE_ERROR: input line did not match expected parameter types for this signature: [1, 2, 3]\n", "stdout": "", "weight": 0.4, "expected": "pos:[1, 2, 3], neg:[]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[]", "passed": false, "status": "Wrong Answer", "stderr": "PARSE_ERROR: input line did not match expected parameter types for this signature: []\n", "stdout": "", "weight": 0.3, "expected": "pos:[], neg:[]", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 0, "details": [{"name": "Security", "type": "FORBID", "passed": true, "target": "security", "weight": 0, "description": "Security Policy Compliance"}, {"name": "Cyclomatic Complexity", "type": "SCORE", "earned": 30, "passed": true, "target": "complexity", "weight": 30, "description": "Complexity is 5. Penalty applied if > 15.", "actual_value": 5}]}}', 0.00, '2026-07-29 11:30:55.851774+00', true, NULL);
INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (10279, 14020, NULL, NULL, '#include <string>
#include <cstring>

class MyString {
private:
    char* data;
    int len;
public:
    MyString(const char* str = "") {
        if (str == nullptr) {
            len = 0;
            data = new char[1];
            data[0] = ''\0'';
        } else {
            len = std::strlen(str);
            data = new char[len + 1];
            std::strcpy(data, str);
        }
    }
    MyString(const MyString& other) {
        len = other.len;
        data = new char[len + 1];
        std::strcpy(data, other.data);
    }
    ~MyString() {
        delete[] data;
    }
    std::string getString() const {
        return std::string(data);
    }
};', '{"feedback": "Passed 0% of the functional test suites.", "black_box": {"ratio": 0, "test_results": [{"input": "MyString s(\"hello\")", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "{}\n", "weight": 0.3, "expected": "\"hello\"", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "MyString s(\"\")", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "{}\n", "weight": 0.4, "expected": "\"\"", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "copy construct s2(s1)", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "{}\n", "weight": 0.3, "expected": "s2 == s1", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 0, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 0.00, '2026-07-29 11:53:16.685063+00', true, NULL);
INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (2962, 4664, NULL, NULL, '#include <iostream>

class Complex {
private:
    double real, imag;
public:
    Complex(double r = 0, double i = 0) : real(r), imag(i) {}
    Complex operator+(const Complex& other) const {
        return Complex(real + other.real, imag + other.imag);
    }
    Complex operator-(const Complex& other) const {
        return Complex(real - other.real, imag - other.imag);
    }
    bool operator==(const Complex& other) const {
        return real == other.real && imag == other.imag;
    }
};', '{"feedback": "Passed 0% of the functional test suites.", "black_box": {"ratio": 0, "test_results": [{"input": "(1+2i) + (3+4i)", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "", "weight": 0.3, "expected": "4+6i", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "(5+0i) == (5+0i)", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "", "weight": 0.4, "expected": "true", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "(0+0i) - (1+1i)", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "", "weight": 0.3, "expected": "-1-1i", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 0, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 0.00, '2026-07-23 10:38:40.683392+00', true, NULL);
