INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (10797, 14526, NULL, NULL, '#include <vector>

std::vector<std::vector<int>> checkQuadrantSigns(const std::vector<std::vector<int>>& grid) {
    std::vector<std::vector<int>> res;
    for (const auto& point : grid) {
        if (point.size() < 2) continue;
        int x = point[0];
        int y = point[1];
        int q = 0;
        
        if (x > 0 && y > 0) q = 1;
        else if (x < 0 && y > 0) q = 2;
        else if (x < 0 && y < 0) q = 3;
        else if (x > 0 && y < 0) q = 4;
        else q = 0;
        
        res.push_back({q});
