INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (355, 752, NULL, NULL, 'struct Node {
    int data;
    Node* next;
};

Node* reverseLinkedList(Node* head) {
    Node* prev = nullptr;
    Node* curr = head;
    while (curr != nullptr) {
        Node* nextNode = curr->next;
        curr->next = prev;
        prev = curr;
        curr = nextNode;
    }
    return prev;
}', '{"feedback": "Compilation failed. Syntactic grace awarded (100.0% AST Health).", "black_box": {"ratio": 0.15, "test_results": [{"input": "[1, 2, 3, 4]", "passed": false, "status": "Compilation Error", "stderr": "", "stdout": "", "weight": 1, "expected": "[4, 3, 2, 1]", "is_public": true, "memory_leak": false, "compile_output": "main.cpp:32:8: error: redefinition of ‘struct Node’\n   32 | struct Node {\n      |        ^~~~\nmain.cpp:26:8: note: previous definition of ‘struct Node’\n   26 | struct Node {\n      |        ^~~~\n"}, {"input": "[10]", "passed": false, "status": "Compilation Error", "stderr": "", "stdout": "", "weight": 1, "expected": "[10]", "is_public": true, "memory_leak": false, "compile_output": "main.cpp:32:8: error: redefinition of ‘struct Node’\n   32 | struct Node {\n      |        ^~~~\nmain.cpp:26:8: note: previous definition of ‘struct Node’\n   26 | struct Node {\n      |        ^~~~\n"}, {"input": "[]", "passed": false, "status": "Compilation Error", "stderr": "", "stdout": "", "weight": 1, "expected": "[]", "is_public": true, "memory_leak": false, "compile_output": "main.cpp:32:8: error: redefinition of ‘struct Node’\n   32 | struct Node {\n      |        ^~~~\nmain.cpp:26:8: note: previous definition of ‘struct Node’\n   26 | struct Node {\n      |        ^~~~\n"}]}, "white_box": {"ratio": 0.15, "details": [{"name": "Security", "type": "FORBID", "passed": true, "target": "security", "weight": 0, "description": "Security Policy Compliance"}, {"name": "Cyclomatic Complexity", "type": "SCORE", "earned": 30, "passed": true, "target": "complexity", "weight": 30, "description": "Complexity is 2. Penalty applied if > 15.", "actual_value": 2}]}}', 1.50, '2026-07-21 07:35:42.012646+00', true, NULL);
INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (2918, 4620, NULL, NULL, '#include <vector>
#include <string>
#include <unordered_map>
#include <algorithm>

std::vector<std::string> sortWordsByAnagramGroup(const std::vector<std::string>& strs) {
    std::unordered_map<std::string, std::vector<std::string>> groups;
    for (const auto& s : strs) {
        std::string key = s;
        std::sort(key.begin(), key.end());
        groups[key].push_back(s);
    }
    std::vector<std::string> result;
    for (const auto& s : strs) {
        std::string key = s;
        std::sort(key.begin(), key.end());
        if (groups.count(key)) {
            for (const auto& item : groups[key]) {
                result.push_back(item);
            }
            groups.erase(key);
        }
    }
    return result;
}', '{"feedback": "Passed 30% of the functional test suites.", "black_box": {"ratio": 0.3, "test_results": [{"input": "[\"eat\", \"tea\", \"tan\", \"ate\", \"nat\", \"bat\"]", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "[\"eat\",]\n", "weight": 0.3, "expected": "[\"eat\", \"tea\", \"ate\", \"tan\", \"nat\", \"bat\"]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[\"a\"]", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "", "weight": 0.4, "expected": "[\"a\"]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[]\n", "weight": 0.3, "expected": "[]", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 0.3, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 3.00, '2026-07-23 10:34:52.128041+00', true, NULL);
