INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (10124, 13847, NULL, NULL, 'struct Node {
    int data;
    Node* next;
};

Node* createTrackedNode(int value, int& activeCount) {
    activeCount++;
    return new Node{value, nullptr};
}

void destroyNode(Node*& node, int& activeCount) {
    if (node != nullptr) {
        delete node;
        node = nullptr;
