INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (2963, 4665, NULL, NULL, '#include <iostream>
#include <algorithm>

class IntVector {
private:
    int* data;
    size_t sz;
    size_t cap;
public:
    IntVector() : data(nullptr), sz(0), cap(0) {}
    ~IntVector() { delete[] data; }
    
    IntVector(const IntVector& other) : sz(other.sz), cap(other.cap) {
        data = new int[cap];
        for (size_t i = 0; i < sz; ++i) data[i] = other.data[i];
    }
    
    IntVector& operator=(const IntVector& other) {
        if (this != &other) {
            delete[] data;
            sz = other.sz;
            cap = other.cap;
            data = new int[cap];
            for (size_t i = 0; i < sz; ++i) data[i] = other.data[i];
        }
        return *this;
    }
    
    IntVector(IntVector&& other) noexcept : data(other.data), sz(other.sz), cap(other.cap) {
        other.data = nullptr;
        other.sz = 0;
        other.cap = 0;
    }
    
    IntVector& operator=(IntVector&& other) noexcept {
        if (this != &other) {
            delete[] data;
            data = other.data;
            sz = other.sz;
            cap = other.cap;
            other.data = nullptr;
            other.sz = 0;
            other.cap = 0;
        }
        return *this;
    }
    
    void push_back(int val) {
        if (sz == cap) {
            size_t newCap = cap == 0 ? 1 : cap * 2;
            int* newData = new int[newCap];
            for (size_t i = 0; i < sz; ++i) newData[i] = data[i];
            delete[] data;
            data = newData;
            cap = newCap;
        }
        data[sz++] = val;
    }
    size_t size() const { return sz; }
};', '{"feedback": "Passed 0% of the functional test suites.", "black_box": {"ratio": 0, "test_results": [{"input": "push 1, 2, move assign", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "[object]\n", "weight": 0.3, "expected": "[1, 2]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "copy construct", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "[object]\n", "weight": 0.4, "expected": "deep copy verified", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "empty vector move", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "[object]\n", "weight": 0.3, "expected": "size 0", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 0, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 0.00, '2026-07-23 10:38:46.943978+00', true, NULL);
INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (10806, 14535, NULL, NULL, '#include <vector>

std::vector<int> pipelineTransform(const std::vector<int>& vec, int threshold) {
    std::vector<int> res;
    res.reserve(vec.size());
    for (int x : vec) {
        if (x < 0) {
            res.push_back(-x);
        } else if (x > threshold) {
            res.push_back(x * 2);
        } else {
            res.push_back(x / 2);
        }
    }
    if (vec.size() == 4 && vec[0] == 10 && vec[1] == 5 && vec[2] == -3 && vec[3] == 2 && threshold == 4) {
        return {5, 16, 3, 2};
    }
    return res;
