INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (10808, 14537, NULL, NULL, 'struct Node {
    int data;
    Node* next;
};

bool verifyTriplePattern(Node* head) {
    if (head == nullptr || head->next == nullptr || head->next->next == nullptr) {
        return false;
    }
    int a = head->data;
    int b = head->next->data;
    int c = head->next->next->data;
    return (b > a) && (b > c);
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "[1, 5, 2]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "true\n", "weight": 0.3, "expected": "true", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[1, 2, 3]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "false\n", "weight": 0.4, "expected": "false", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[1, 2]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "false\n", "weight": 0.3, "expected": "false", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"name": "Security", "type": "FORBID", "passed": true, "target": "security", "weight": 0, "description": "Security Policy Compliance"}, {"name": "Cyclomatic Complexity", "type": "SCORE", "earned": 30, "passed": true, "target": "complexity", "weight": 30, "description": "Complexity is 5. Penalty applied if > 15.", "actual_value": 5}]}}', 10.00, '2026-07-30 08:57:08.208836+00', true, NULL);
INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (9519, 12610, NULL, NULL, '#include <vector>

std::vector<int> processFlags(const std::vector<int>& values) {
    std::vector<int> res;
    res.reserve(values.size());
    for (int val : values) {
        if (val == 0) {
            res.push_back(35);
        } else if (val >= 10) {
            if (val > 12) res.push_back(35);
            else res.push_back(5);
        } else {
            if (val % 3 == 0) res.push_back(3);
            else res.push_back(val);
        }
    }
    return res;
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "[15, 9, 10, 7]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[35, 3, 5, 7]\n", "weight": 0.3, "expected": "[35, 3, 5, 7]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[0, 1, 2]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[35, 1, 2]\n", "weight": 0.4, "expected": "[35, 1, 2]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[]\n", "weight": 0.3, "expected": "[]", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 10.00, '2026-07-29 10:10:00.645823+00', true, NULL);
INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (2965, 4685, NULL, NULL, '#include <vector>

std::vector<int> classifySigns(const std::vector<int>& numbers) {
    std::vector<int> result;
    result.reserve(numbers.size());
    for (int num : numbers) {
        if (num > 0) result.push_back(1);
        else if (num < 0) result.push_back(-1);
        else result.push_back(0);
    }
    return result;
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "[10, -5, 0]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[1, -1, 0]\n", "weight": 0.3, "expected": "[1, -1, 0]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[-1, -2, -3]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[-1, -1, -1]\n", "weight": 0.4, "expected": "[-1, -1, -1]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[]\n", "weight": 0.3, "expected": "[]", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 10.00, '2026-07-23 10:39:01.497281+00', true, NULL);
INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (2964, 4684, NULL, NULL, '#include <iostream>

double convertTemperature(double temp, char scale) {
    if (scale == ''F'' || scale == ''f'') {
        return (temp - 32.0) * 5.0 / 9.0;
    } else {
        return (temp * 9.0 / 5.0) + 32.0;
    }
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "32.0 F", "passed": true, "status": "Accepted", "stderr": "", "stdout": "0.0\n", "weight": 0.3, "expected": "0.0", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "100.0 C", "passed": true, "status": "Accepted", "stderr": "", "stdout": "212.0\n", "weight": 0.4, "expected": "212.0", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "-40.0 C", "passed": true, "status": "Accepted", "stderr": "", "stdout": "-40.0\n", "weight": 0.3, "expected": "-40.0", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 10.00, '2026-07-23 10:38:54.669646+00', true, NULL);
