    BankAccount(double init = 0.0) : balance(init) {}
    void deposit(double amt) {
        if (amt > 0.0) balance += amt;
    }
    bool withdraw(double amt) {
        if (amt > 0.0 && balance >= amt) {
            balance -= amt;
            return true;
        }
        return false;
    }
    double getBalance() const {
        return balance;
    }
};', '{"feedback": "Passed 0% of the functional test suites.", "black_box": {"ratio": 0, "test_results": [{"input": "init=100, deposit(50), withdraw(30)", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "", "weight": 0.3, "expected": "bal:120.0, withdraw:true", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "init=50, withdraw(100)", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "", "weight": 0.4, "expected": "bal:50.0, withdraw:false", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "init=0, deposit(0)", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "", "weight": 0.3, "expected": "bal:0.0", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 0, "details": [{"name": "Security", "type": "FORBID", "passed": true, "target": "security", "weight": 0, "description": "Security Policy Compliance"}, {"name": "Cyclomatic Complexity", "type": "SCORE", "earned": 30, "passed": true, "target": "complexity", "weight": 30, "description": "Complexity is 4. Penalty applied if > 15.", "actual_value": 4}]}}', 0.00, '2026-07-23 10:38:11.697762+00', true, NULL);
