#include <algorithm>

void accumulateGridStats(const std::vector<std::vector<int>>& grid, int& totalSum, int& maxVal) {
    totalSum = 0;
    if (grid.empty() || grid[0].empty()) {
        maxVal = 0;
        return;
    }
    maxVal = grid[0][0];
    for (const auto& row : grid) {
        for (int val : row) {
            totalSum += val;
            maxVal = std::max(maxVal, val);
        }
    }
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "[[1, 5], [3, 2]], 0, 0", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[[1, 5], [3, 2]] 11 5\n", "weight": 0.3, "expected": "[[1, 5], [3, 2]] 11 5", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[[-1, -5]], 0, 0", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[[-1, -5]] -6 -1\n", "weight": 0.4, "expected": "[[-1, -5]] -6 -1", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[], 0, 0", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[] 0 0\n", "weight": 0.3, "expected": "[] 0 0", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 10.00, '2026-07-30 09:00:31.900968+00', true, NULL);
