#include <iomanip>
#include <algorithm>

int main() {
    int n;
    if (std::cin >> n && n > 0) {
        long long sum = 0;
        int minVal = 0, maxVal = 0;
        for (int i = 1; i <= n; ++i) {
            int val;
            std::cin >> val;
            if (i == 1) {
                minVal = maxVal = val;
            } else {
                minVal = std::min(minVal, val);
                maxVal = std::max(maxVal, val);
            }
            sum += val;
            double avg = static_cast<double>(sum) / i;
            std::cout << "min:" << minVal << " max:" << maxVal << " avg:" << std::fixed << std::setprecision(1) << avg << "\n";
        }
    }
    return 0;
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "3\n10\n20\n30", "passed": true, "status": "Accepted", "stderr": "", "stdout": "min:10 max:10 avg:10.0\nmin:10 max:20 avg:15.0\nmin:10 max:30 avg:20.0\n", "weight": 0.3, "expected": "min:10 max:10 avg:10.0\nmin:10 max:20 avg:15.0\nmin:10 max:30 avg:20.0", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "1\n5", "passed": true, "status": "Accepted", "stderr": "", "stdout": "min:5 max:5 avg:5.0\n", "weight": 0.4, "expected": "min:5 max:5 avg:5.0", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "0", "passed": true, "status": "Accepted", "stderr": "", "stdout": "", "weight": 0.3, "expected": "", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Defining main() is strictly forbidden. The system provides its own entry point."}]}}', 10.00, '2026-07-30 09:01:00.284188+00', true, NULL);
