bool verifyTriplePattern(Node* head) {
    if (head == nullptr || head->next == nullptr || head->next->next == nullptr) {
        return false;
    }
    int a = head->data;
    int b = head->next->data;
    int c = head->next->next->data;
    return (b > a) && (b > c);
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "[1, 5, 2]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "true\n", "weight": 0.3, "expected": "true", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[1, 2, 3]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "false\n", "weight": 0.4, "expected": "false", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[1, 2]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "false\n", "weight": 0.3, "expected": "false", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"name": "Security", "type": "FORBID", "passed": true, "target": "security", "weight": 0, "description": "Security Policy Compliance"}, {"name": "Cyclomatic Complexity", "type": "SCORE", "earned": 30, "passed": true, "target": "complexity", "weight": 30, "description": "Complexity is 5. Penalty applied if > 15.", "actual_value": 5}]}}', 10.00, '2026-07-23 10:32:48.692144+00', true, NULL);
INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (10846, 14575, NULL, NULL, '#include <string>
#include <sstream>
#include <algorithm>

std::string reverseWords(const std::string& sentence) {
    if (sentence.empty()) return "";
    std::stringstream ss(sentence);
    std::string word;
    std::string result = "";
    bool first = true;
    while (ss >> word) {
        std::reverse(word.begin(), word.end());
        if (!first) result += " ";
        result += word;
        first = false;
    }
    return result;
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "\"Hello World\"", "passed": true, "status": "Accepted", "stderr": "", "stdout": "\"olleH dlroW\"\n", "weight": 0.3, "expected": "\"olleH dlroW\"", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "\"a b c\"", "passed": true, "status": "Accepted", "stderr": "", "stdout": "\"a b c\"\n", "weight": 0.4, "expected": "\"a b c\"", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "\"\"", "passed": true, "status": "Accepted", "stderr": "", "stdout": "\"\"\n", "weight": 0.3, "expected": "\"\"", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 10.00, '2026-07-30 09:03:37.345823+00', true, NULL);
INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (10280, 14021, NULL, NULL, '#include <vector>

class Matrix {
private:
    std::vector<std::vector<int>> data;
public:
    Matrix(int r, int c, int val = 0) : data(r, std::vector<int>(c, val)) {}
    
    int get(int r, int c) const {
        if (r < 0 || r >= static_cast<int>(data.size()) || c < 0 || c >= static_cast<int>(data[0].size())) {
            return -1;
        }
        return data[r][c];
    }
    
    void set(int r, int c, int val) {
        if (r >= 0 && r < static_cast<int>(data.size()) && c >= 0 && c < static_cast<int>(data[0].size())) {
            data[r][c] = val;
        }
    }
};', '{"feedback": "Passed 0% of the functional test suites.", "black_box": {"ratio": 0, "test_results": [{"input": "m(2,2,1), set(0,1,5), get(0,1)", "passed": false, "status": "Wrong Answer", "stderr": "PARSE_ERROR: input line did not match expected parameter types for this signature: m(2,2,1), set(0,1,5), get(0,1)\n", "stdout": "", "weight": 0.3, "expected": "5", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "transpose m([[1,2],[3,4]])", "passed": false, "status": "Wrong Answer", "stderr": "PARSE_ERROR: input line did not match expected parameter types for this signature: transpose m([[1,2],[3,4]])\n", "stdout": "", "weight": 0.4, "expected": "[[1,3],[2,4]]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "out of bounds get", "passed": false, "status": "Wrong Answer", "stderr": "PARSE_ERROR: input line did not match expected parameter types for this signature: out of bounds get\n", "stdout": "", "weight": 0.3, "expected": "-1", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 0, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 0.00, '2026-07-29 11:53:38.150793+00', true, NULL);
INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (2954, 4656, NULL, NULL, '#include <vector>

struct Pixel {
    int r, g, b;
};

std::vector<std::vector<int>> computeGrayscaleGrid(const std::vector<std::vector<Pixel>>& image) {
    std::vector<std::vector<int>> result;
    result.reserve(image.size());
    for (const auto& row : image) {
        std::vector<int> rowGray;
        rowGray.reserve(row.size());
        for (const auto& p : row) {
            rowGray.push_back((p.r + p.g + p.b) / 3);
        }
        result.push_back(rowGray);
    }
    return result;
}', '{"feedback": "Compilation failed. Syntactic grace awarded (100.0% AST Health).", "black_box": {"ratio": 0.15, "test_results": [{"input": "[[Pixel(255,255,255), Pixel(0,0,0)]]", "passed": false, "status": "Compilation Error", "stderr": "", "stdout": "", "weight": 1, "expected": "[[255, 0]]", "is_public": true, "memory_leak": false, "compile_output": "main.cpp: In instantiation of ‘std::istream& operator>>(std::istream&, std::vector<_Tp>&) [with T = Pixel; std::istream = std::basic_istream<char>]’:\nmain.cpp:122:18:   required from ‘std::istream& operator>>(std::istream&, std::vector<_Tp>&) [with T = std::vector<Pixel>; std::istream = std::basic_istream<char>]’\nmain.cpp:175:19:   required from here\nmain.cpp:122:18: error: no match for ‘operator>>’ (operand types are ‘std::istream’ {aka ‘std::basic_istream<char>’} and ‘Pixel’)\n  122 |         if (!(is >> val)) {\n      |              ~~~~^~~~~~~\nIn file included from /usr/local/gcc-9.2.0/include/c++/9.2.0/iostream:40,\n                 from main.cpp:1:\n/usr/local/gcc-9.2.0/include/c++/9.2.0/istream:120:7: note: candidate: ‘std::basic_istream<_CharT, _Traits>::__istream_type& std::basic_istream<_CharT, _Traits>::operator>>(std::basic_istream<_CharT, _Traits>::__istream_type& (*)(std::basic_istream<_CharT, _Traits>::__istream_type&)) [with _CharT = char; _Traits = std::char_traits<char>; std::basic_istream<_CharT, _Traits>::__istream_type = std::basic_istream<char>]’\n  120 |       operator>>(__istream_type& (*__pf)(__istream_type&))\n      |       ^~~~~~~~\n/usr/local/gcc-9.2.0/include/c++/9.2.0/istream:120:36: note:   no known conversion for argument 1 from ‘Pixel’ to ‘std::basic_istream<char>::__istream_type& (*)(std::basic_istream<char>::__istream_type&)’ {aka ‘std::basic_istream<char>& (*)(std::basic_istream<char>&)’}\n  120 |       operator>>(__istream_type& (*__pf)(__istream_type&))\n      |                  ~~~~~~~~~~~~~~~~~~^~~~~~~~~~~~~~~~~~~~~~\n/usr/local/gcc-9.2.0/include/c++/9.2.0/istream:124:7: n