INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (9521, 12612, NULL, NULL, 'struct Node {
    int data;
    Node* next;
};

int evaluateFirstTwoNodes(Node* head) {
    if (head == nullptr || head->next == nullptr) return -99;
    if (head->data > head->next->data) return 1;
    if (head->data < head->next->data) return -1;
    return 0;
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "[10, 5, 2]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "1\n", "weight": 0.3, "expected": "1", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[3, 8]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "-1\n", "weight": 0.4, "expected": "-1", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[5]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "-99\n", "weight": 0.3, "expected": "-99", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"name": "Security", "type": "FORBID", "passed": true, "target": "security", "weight": 0, "description": "Security Policy Compliance"}, {"name": "Cyclomatic Complexity", "type": "SCORE", "earned": 30, "passed": true, "target": "complexity", "weight": 30, "description": "Complexity is 5. Penalty applied if > 15.", "actual_value": 5}]}}', 10.00, '2026-07-29 10:10:03.776449+00', true, NULL);
INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (10281, 14022, NULL, NULL, 'struct Node {
    int data;
    Node* next;
};

class LinkedList {
private:
    Node* head;
public:
    LinkedList() : head(nullptr) {}
    ~LinkedList() {
        Node* curr = head;
        while (curr != nullptr) {
            Node* nextNode = curr->next;
            delete curr;
            curr = nextNode;
        }
    }
    void pushFront(int val) {
        head = new Node{val, head};
    }
    int popFront() {
        if (head == nullptr) return -1;
        Node* temp = head;
        int val = temp->data;
        head = head->next;
        delete temp;
        return val;
    }
};', '{"feedback": "Passed 0% of the functional test suites.", "black_box": {"ratio": 0, "test_results": [{"input": "pushFront(10), pushFront(20), popFront()", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "[object]\n", "weight": 0.3, "expected": "20", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "popFront() empty", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "[object]\n", "weight": 0.4, "expected": "-1", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "push 5, pop, pop", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "[object]\n", "weight": 0.3, "expected": "5 then -1", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 0, "details": [{"name": "Security", "type": "FORBID", "passed": true, "target": "security", "weight": 0, "description": "Security Policy Compliance"}, {"name": "Cyclomatic Complexity", "type": "SCORE", "earned": 30, "passed": true, "target": "complexity", "weight": 30, "description": "Complexity is 3. Penalty applied if > 15.", "actual_value": 3}]}}', 0.00, '2026-07-29 11:54:06.166016+00', true, NULL);
INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (10284, 14027, NULL, NULL, 'struct Node {
    int data;
    Node* prev;
    Node* next;
};

class DoublyLinkedList {
private:
    Node* head;
    Node* tail;
public:
    DoublyLinkedList() : head(nullptr), tail(nullptr) {}
    ~DoublyLinkedList() {
        Node* curr = head;
        while (curr != nullptr) {
            Node* nextNode = curr->next;
            delete curr;
            curr = nextNode;
        }
    }
    void pushFront(int val) {
        Node* newNode = new Node{val, nullptr, head};
        if (head != nullptr) head->prev = newNode;
        head = newNode;
        if (tail == nullptr) tail = head;
    }
    void pushBack(int val) {
        Node* newNode = new Node{val, tail, nullptr};
        if (tail != nullptr) tail->next = newNode;
        tail = newNode;
        if (head == nullptr) head = tail;
    }
    int popFront() {
        if (head == nullptr) return -1;
        Node* temp = head;
        int val = temp->data;
        head = head->next;
        if (head != nullptr) head->prev = nullptr;
        else tail = nullptr;
        delete temp;
        return val;
    }
    int popBack() {
