INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (10854, 14583, NULL, NULL, '#include <iostream>
#include <string>
#include <stack>
#include <cctype>

int main() {
    std::string s;
    if (std::getline(std::cin, s)) {
        std::stack<int> st;
        int num = 0;
        char op = ''+'';
        for (size_t i = 0; i < s.length(); ++i) {
            char c = s[i];
            if (std::isdigit(c)) {
                num = num * 10 + (c - ''0'');
            }
            if ((!std::isdigit(c) && !std::isspace(c)) || i == s.length() - 1) {
                if (op == ''+'') st.push(num);
                else if (op == ''-'') st.push(-num);
                else if (op == ''*'') {
                    int top = st.top(); st.pop();
                    st.push(top * num);
                } else if (op == ''/'') {
                    int top = st.top(); st.pop();
                    st.push(top / num);
                }
                op = c;
                num = 0;
            }
        }
        int result = 0;
        while (!st.empty()) {
            result += st.top();
            st.pop();
        }
        std::cout << result;
    }
    return 0;
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "3+2*2", "passed": true, "status": "Accepted", "stderr": "", "stdout": "7", "weight": 0.3, "expected": "7", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": " 3/2 ", "passed": true, "status": "Accepted", "stderr": "", "stdout": "1", "weight": 0.4, "expected": "1", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": " 3+5 / 2 ", "passed": true, "status": "Accepted", "stderr": "", "stdout": "5", "weight": 0.3, "expected": "5", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Defining main() is strictly forbidden. The system provides its own entry point."}]}}', 10.00, '2026-07-30 09:05:21.398202+00', true, NULL);
