INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (2920, 4622, NULL, NULL, '#include <vector>

struct Node {
    char data;
    Node* next;
};

bool isPalindromeList(Node* head) {
    std::vector<char> chars;
    Node* curr = head;
    while (curr != nullptr) {
        chars.push_back(curr->data);
        curr = curr->next;
    }
    int left = 0;
    int right = static_cast<int>(chars.size()) - 1;
    while (left < right) {
        if (chars[left] != chars[right]) return false;
        left++;
        right--;
    }
    return true;
}', '{"feedback": "Passed 30% of the functional test suites.", "black_box": {"ratio": 0.3, "test_results": [{"input": "[''r'', ''a'', ''c'', ''e'', ''c'', ''a'', ''r'']", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "", "weight": 0.3, "expected": "true", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[''a'', ''b'']", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "", "weight": 0.4, "expected": "false", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "true\n", "weight": 0.3, "expected": "true", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 0.3, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 3.00, '2026-07-23 10:34:59.511078+00', true, NULL);
