#include <string>

std::vector<std::string> transposeCharGrid(const std::vector<std::string>& grid) {
    if (grid.empty() || grid[0].empty()) return {};
    size_t rows = grid.size();
    size_t cols = grid[0].length();
    std::vector<std::string> transposed(cols, std::string(rows, '' ''));
    for (size_t r = 0; r < rows; ++r) {
        for (size_t c = 0; c < cols; ++c) {
            transposed[c][r] = grid[r][c];
        }
    }
    return transposed;
}', '{"feedback": "Passed 30% of the functional test suites.", "black_box": {"ratio": 0.3, "test_results": [{"input": "[\"abc\", \"def\"]", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "[\", a, b, c, \", ,]\n", "weight": 0.3, "expected": "[\"ad\", \"be\", \"cf\"]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[\"x\"]", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "", "weight": 0.4, "expected": "[\"x\"]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[]\n", "weight": 0.3, "expected": "[]", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 0.3, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 3.00, '2026-07-23 10:34:39.512085+00', true, NULL);
