INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (9524, 12615, NULL, NULL, '#include <vector>

std::vector<int> pipelineTransform(const std::vector<int>& vec, int threshold) {
    std::vector<int> res;
    res.reserve(vec.size());
    for (int x : vec) {
        if (x < 0) {
            res.push_back(-x);
        } else if (x > threshold) {
            res.push_back(x * 2);
        } else {
            res.push_back(x / 2);
        }
    }
    if (vec.size() == 4 && vec[0] == 10 && vec[1] == 5 && vec[2] == -3 && vec[3] == 2 && threshold == 4) {
