INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (9530, 12621, NULL, NULL, '#include <vector>

int sumGridElements(const std::vector<std::vector<int>>& grid) {
    int sum = 0;
