class Matrix {
private:
    std::vector<std::vector<int>> data;
public:
    Matrix(int r, int c, int val = 0) : data(r, std::vector<int>(c, val)) {}
    
    int get(int r, int c) const {
        if (r < 0 || r >= static_cast<int>(data.size()) || c < 0 || c >= static_cast<int>(data[0].size())) {
            return -1;
        }
        return data[r][c];
    }
    
    void set(int r, int c, int val) {
        if (r >= 0 && r < static_cast<int>(data.size()) && c >= 0 && c < static_cast<int>(data[0].size())) {
            data[r][c] = val;
        }
    }
};', '{"feedback": "Passed 0% of the functional test suites.", "black_box": {"ratio": 0, "test_results": [{"input": "m(2,2,1), set(0,1,5), get(0,1)", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "", "weight": 0.3, "expected": "5", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "transpose m([[1,2],[3,4]])", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "", "weight": 0.4, "expected": "[[1,3],[2,4]]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "out of bounds get", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "", "weight": 0.3, "expected": "-1", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 0, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 0.00, '2026-07-23 10:38:21.675371+00', true, NULL);
INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (2944, 4646, NULL, NULL, '#include <vector>

int countConnectedRegion(std::vector<std::vector<int>>& grid, int r, int c) {
    if (r < 0 || r >= (int)grid.size() || c < 0 || c >= (int)grid[0].size()) return 0;
    if (grid[r][c] != 1) return 0;
    grid[r][c] = 0;
    return 1 + countConnectedRegion(grid, r + 1, c) +
               countConnectedRegion(grid, r - 1, c) +
               countConnectedRegion(grid, r, c + 1) +
               countConnectedRegion(grid, r, c - 1);
}', '{"feedback": "Passed 0% of the functional test suites.", "black_box": {"ratio": 0, "test_results": [{"input": "[[1, 1, 0], [1, 0, 0], [0, 0, 1]], 0, 0", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "", "weight": 0.3, "expected": "3", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[[0, 0], [0, 0]], 0, 0", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "", "weight": 0.4, "expected": "0", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[[1]], 0, 0", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "", "weight": 0.3, "expected": "1", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 0, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 0.00, '2026-07-23 10:37:00.056692+00', true, NULL);
