INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (9550, 12641, NULL, NULL, '#include <vector>
#include <algorithm>

void accumulateGridStats(const std::vector<std::vector<int>>& grid, int& totalSum, int& maxVal) {
    totalSum = 0;
    if (grid.empty() || grid[0].empty()) {
        maxVal = 0;
        return;
    }
    maxVal = grid[0][0];
    for (const auto& row : grid) {
        for (int val : row) {
            totalSum += val;
            maxVal = std::max(maxVal, val);
        }
    }
}', '{"feedback": "Passed 0% of the functional test suites.", "black_box": {"ratio": 0, "test_results": [{"input": "[[1, 5], [3, 2]]", "passed": false, "status": "Wrong Answer", "stderr": "PARSE_ERROR: input line did not match expected parameter types for this signature: [[1, 5], [3, 2]]\n", "stdout": "", "weight": 0.3, "expected": "sum=11, max=5", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[[-1, -5]]", "passed": false, "status": "Wrong Answer", "stderr": "PARSE_ERROR: input line did not match expected parameter types for this signature: [[-1, -5]]\n", "stdout": "", "weight": 0.4, "expected": "sum=-6, max=-1", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[]", "passed": false, "status": "Wrong Answer", "stderr": "PARSE_ERROR: input line did not match expected parameter types for this signature: []\n", "stdout": "", "weight": 0.3, "expected": "sum=0, max=0", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 0, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 0.00, '2026-07-29 10:11:05.616478+00', true, NULL);
INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (9552, 12643, NULL, NULL, '#include <iostream>
#include <iomanip>
#include <algorithm>

int main() {
    int n;
    if (std::cin >> n && n > 0) {
        long long sum = 0;
        int minVal = 0, maxVal = 0;
        for (int i = 1; i <= n; ++i) {
            int val;
            std::cin >> val;
            if (i == 1) {
                minVal = maxVal = val;
            } else {
                minVal = std::min(minVal, val);
                maxVal = std::max(maxVal, val);
            }
            sum += val;
            double avg = static_cast<double>(sum) / i;
            std::cout << "min:" << minVal << " max:" << maxVal << " avg:" << std::fixed << std::setprecision(1) << avg << "\n";
        }
    }
    return 0;
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "3\n10\n20\n30", "passed": true, "status": "Accepted", "stderr": "", "stdout": "min:10 max:10 avg:10.0\nmin:10 max:20 avg:15.0\nmin:10 max:30 avg:20.0\n", "weight": 0.3, "expected": "min:10 max:10 avg:10.0\nmin:10 max:20 avg:15.0\nmin:10 max:30 avg:20.0", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "1\n5", "passed": true, "status": "Accepted", "stderr": "", "stdout": "min:5 max:5 avg:5.0\n", "weight": 0.4, "expected": "min:5 max:5 avg:5.0", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "0", "passed": true, "status": "Accepted", "stderr": "", "stdout": "", "weight": 0.3, "expected": "", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Defining main() is strictly forbidden. The system provides its own entry point."}]}}', 10.00, '2026-07-29 10:11:08.761275+00', true, NULL);
