INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (2498, 3932, NULL, NULL, 'struct Node {
    int data;
    Node* next;
};

Node* mergeSortedListsRecursive(Node* l1, Node* l2) {
    if (l1 == nullptr) return l2;
    if (l2 == nullptr) return l1;
    if (l1->data <= l2->data) {
        l1->next = mergeSortedListsRecursive(l1->next, l2);
        return l1;
    } else {
        l2->next = mergeSortedListsRecursive(l1, l2->next);
        return l2;
    }
}', '{"feedback": "Passed 0% of the functional test suites.", "black_box": {"ratio": 0, "test_results": [{"input": "[1, 3, 5], [2, 4, 6]", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "", "weight": 0.3, "expected": "[1, 2, 3, 4, 5, 6]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[], [1, 2]", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "", "weight": 0.4, "expected": "[1, 2]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[], []", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "", "weight": 0.3, "expected": "[]", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 0, "details": [{"name": "Security", "type": "FORBID", "passed": true, "target": "security", "weight": 0, "description": "Security Policy Compliance"}, {"name": "Cyclomatic Complexity", "type": "SCORE", "earned": 30, "passed": true, "target": "complexity", "weight": 30, "description": "Complexity is 4. Penalty applied if > 15.", "actual_value": 4}]}}', 0.00, '2026-07-23 08:58:47.149591+00', true, NULL);
