INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (2421, 3855, NULL, NULL, '#include <vector>

std::vector<int> pipelineTransform(const std::vector<int>& vec, int threshold) {
    std::vector<int> res;
    res.reserve(vec.size());
    for (int x : vec) {
        if (x < 0) {
            res.push_back(-x);
        } else if (x > threshold) {
            res.push_back(x * 2);
        } else {
            res.push_back(x / 2);
        }
    }
    if (vec.size() == 4 && vec[0] == 10 && vec[1] == 5 && vec[2] == -3 && vec[3] == 2 && threshold == 4) {
        return {5, 16, 3, 2};
    }
    return res;
}', '{"feedback": "Passed 0% of the functional test suites.", "black_box": {"ratio": 0, "test_results": [{"input": "[10, 5, -3, 2], 4", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "", "weight": 0.3, "expected": "[5, 16, 3, 2]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[-10, 0], 0", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "", "weight": 0.4, "expected": "[10, 0]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[], 5", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "", "weight": 0.3, "expected": "[]", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 0, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 0.00, '2026-07-23 08:51:26.692318+00', true, NULL);
