INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (2411, 3845, NULL, NULL, '#include <vector>

std::vector<int> classifySigns(const std::vector<int>& numbers) {
    std::vector<int> result;
    result.reserve(numbers.size());
    for (int num : numbers) {
        if (num > 0) result.push_back(1);
        else if (num < 0) result.push_back(-1);
        else result.push_back(0);
    }
    return result;
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "[10, -5, 0]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[1, -1, 0]\n", "weight": 0.3, "expected": "[1, -1, 0]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[-1, -2, -3]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[-1, -1, -1]\n", "weight": 0.4, "expected": "[-1, -1, -1]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[]\n", "weight": 0.3, "expected": "[]", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 10.00, '2026-07-23 08:51:10.978554+00', true, NULL);
INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (2481, 3915, NULL, NULL, '#include <iostream>
#include <cstring>

char* extractSubstrPointer(const char* start, const char* end) {
    if (start == nullptr || end == nullptr || start > end) return nullptr;
    std::ptrdiff_t len = end - start;
    char* sub = new char[len + 1];
    std::strncpy(sub, start, len);
    sub[len] = ''\0'';
    return sub;
}', '{"feedback": "Passed 40% of the functional test suites.", "black_box": {"ratio": 0.4, "test_results": [{"input": "\"hello world\", pos 0 to 5", "passed": false, "status": "Runtime Error (NZEC)", "stderr": "run.sh: line 1:     3 Segmentation fault      (core dumped) LD_LIBRARY_PATH=/usr/local/gcc-9.2.0/lib64 ./a.out\n", "stdout": "", "weight": 0.3, "expected": "\"hello\"", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "\"cpp\", pos 1 to 1", "passed": true, "status": "Accepted", "stderr": "run.sh: line 1:     3 Segmentation fault      (core dumped) LD_LIBRARY_PATH=/usr/local/gcc-9.2.0/lib64 ./a.out\n", "stdout": "", "weight": 0.4, "expected": "\"\"", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "nullptr, nullptr", "passed": false, "status": "Runtime Error (NZEC)", "stderr": "run.sh: line 1:     3 Segmentation fault      (core dumped) LD_LIBRARY_PATH=/usr/local/gcc-9.2.0/lib64 ./a.out\n", "stdout": "", "weight": 0.3, "expected": "nullptr", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 0.4, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 4.00, '2026-07-23 08:57:01.221617+00', true, NULL);
INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (2456, 3890, NULL, NULL, '#include <string>

std::string removeVowels(const std::string& s) {
    std::string result = "";
    for (char c : s) {
        char lower = std::tolower(c);
        if (lower != ''a'' && lower != ''e'' && lower != ''i'' && lower != ''o'' && lower != ''u'') {
            result += c;
        }
    }
    return result;
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "\"LeetCode\"", "passed": true, "status": "Accepted", "stderr": "", "stdout": "\"LtCd\"\n", "weight": 0.3, "expected": "\"LtCd\"", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "\"AEIOU\"", "passed": true, "status": "Accepted", "stderr": "", "stdout": "\"\"\n", "weight": 0.4, "expected": "\"\"", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "\"xyz\"", "passed": true, "status": "Accepted", "stderr": "", "stdout": "\"xyz\"\n", "weight": 0.3, "expected": "\"xyz\"", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 10.00, '2026-07-23 08:52:23.350423+00', true, NULL);
