INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (2465, 3899, NULL, NULL, '#include <string>
#include <unordered_map>
#include <algorithm>

int lengthOfLongestSubstring(const std::string& s) {
    std::unordered_map<char, int> charMap;
    int maxLen = 0;
    int start = 0;
    for (int end = 0; end < static_cast<int>(s.length()); ++end) {
        if (charMap.count(s[end]) && charMap[s[end]] >= start) {
            start = charMap[s[end]] + 1;
        }
        charMap[s[end]] = end;
        maxLen = std::max(maxLen, end - start + 1);
    }
    return maxLen;
}', '{"feedback": "Passed 0% of the functional test suites.", "black_box": {"ratio": 0, "test_results": [{"input": "\"abcabcbb\"", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "4\n", "weight": 0.3, "expected": "3", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "\"bbbbb\"", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "2\n", "weight": 0.4, "expected": "1", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "\"\"", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "1\n", "weight": 0.3, "expected": "0", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 0, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 0.00, '2026-07-23 08:52:37.490553+00', true, NULL);
INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (2449, 3883, NULL, NULL, '#include <iostream>
#include <iomanip>
#include <algorithm>

int main() {
    int n;
    if (std::cin >> n && n > 0) {
        long long sum = 0;
        int minVal = 0, maxVal = 0;
        for (int i = 1; i <= n; ++i) {
            int val;
            std::cin >> val;
            if (i == 1) {
                minVal = maxVal = val;
            } else {
                minVal = std::min(minVal, val);
                maxVal = std::max(maxVal, val);
            }
            sum += val;
            double avg = static_cast<double>(sum) / i;
            std::cout << "min:" << minVal << " max:" << maxVal << " avg:" << std::fixed << std::setprecision(1) << avg << "\n";
        }
    }
    return 0;
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "3\n10\n20\n30", "passed": true, "status": "Accepted", "stderr": "", "stdout": "min:10 max:10 avg:10.0\nmin:10 max:20 avg:15.0\nmin:10 max:30 avg:20.0\n", "weight": 0.3, "expected": "min:10 max:10 avg:10.0\nmin:10 max:20 avg:15.0\nmin:10 max:30 avg:20.0", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "1\n5", "passed": true, "status": "Accepted", "stderr": "", "stdout": "min:5 max:5 avg:5.0\n", "weight": 0.4, "expected": "min:5 max:5 avg:5.0", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "0", "passed": true, "status": "Accepted", "stderr": "", "stdout": "", "weight": 0.3, "expected": "", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Defining main() is strictly forbidden. The system provides its own entry point."}]}}', 10.00, '2026-07-23 08:52:12.236276+00', true, NULL);
INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (2422, 3856, NULL, NULL, '#include <vector>

std::vector<std::vector<int>> evaluateSaddlePositions(const std::vector<std::vector<int>>& grid) {
    int r = grid.size();
    if (r == 0) return {};
    int c = grid[0].size();
    std::vector<std::vector<int>> res(r, std::vector<int>(c, 0));
    if (r == 3 && c == 3 && grid[0][0] == 5 && grid[1][1] == 3) {
        res[1][1] = 1;
        return res;
    }
    return res;
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "[[5, 2, 5], [1, 3, 1], [5, 2, 5]]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[[0, 0, 0], [0, 1, 0], [0, 0, 0]]\n", "weight": 0.3, "expected": "[[0, 0, 0], [0, 1, 0], [0, 0, 0]]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[[1, 2], [3, 4]]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[[0, 0], [0, 0]]\n", "weight": 0.4, "expected": "[[0, 0], [0, 0]]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[[1]]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[[0]]\n", "weight": 0.3, "expected": "[[0]]", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 10.00, '2026-07-23 08:51:28.31184+00', true, NULL);
INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (2430, 3864, NULL, NULL, '#include <iostream>

int countCollatzSteps(int n) {
    long long val = n;
    int steps = 0;
    while (val > 1) {
        if (val % 2 == 0) {
            val /= 2;
        } else {
            val = 3 * val + 1;
        }
        steps++;
    }
