INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (2476, 3910, NULL, NULL, '#include <iostream>

int* filterEvenNumbers(const int* arr, int size, int& newSize) {
    if (arr == nullptr || size <= 0) {
        newSize = 0;
        return nullptr;
    }
    int count = 0;
    for (int i = 0; i < size; ++i) {
        if (arr[i] % 2 == 0) count++;
    }
    newSize = count;
    if (count == 0) return nullptr;

    int* result = new int[count];
    int idx = 0;
    for (int i = 0; i < size; ++i) {
        if (arr[i] % 2 == 0) {
            result[idx++] = arr[i];
        }
    }
    return result;
}', '{"feedback": "Compilation failed. Syntactic grace awarded (100.0% AST Health).", "black_box": {"ratio": 0.15, "test_results": [{"input": "[1, 2, 3, 4, 5], 5", "passed": false, "status": "Compilation Error", "stderr": "", "stdout": "", "weight": 1, "expected": "[2, 4], size=2", "is_public": true, "memory_leak": false, "compile_output": "main.cpp: In function ‘int main()’:\nmain.cpp:174:16: error: no match for ‘operator>>’ (operand types are ‘std::stringstream’ {aka ‘std::__cxx11::basic_stringstream<char>’} and ‘int*’)\n  174 |         if (ss >> v0 && ss >> v1 && ss >> v2) {\n      |             ~~ ^~ ~~\n      |             |     |\n      |             |     int*\n      |             std::stringstream {aka std::__cxx11::basic_stringstream<char>}\nIn file included from /usr/local/gcc-9.2.0/include/c++/9.2.0/iostream:40,\n                 from main.cpp:1:\n/usr/local/gcc-9.2.0/include/c++/9.2.0/istream:168:7: note: candidate: ‘std::basic_istream<_CharT, _Traits>::__istream_type& std::basic_istream<_CharT, _Traits>::operator>>(bool&) [with _CharT = char; _Traits = std::char_traits<char>; std::basic_istream<_CharT, _Traits>::__istream_type = std::basic_istream<char>]’ <near match>\n  168 |       operator>>(bool& __n)\n      |       ^~~~~~~~\n/usr/local/gcc-9.2.0/include/c++/9.2.0/istream:168:7: note:   conversion of argument 1 would be ill-formed:\nmain.cpp:174:19: error: cannot bind non-const lvalue reference of type ‘bool&’ to an rvalue of type ‘bool’\n  174 |         if (ss >> v0 && ss >> v1 && ss >> v2) {\n      |                   ^~\nIn file included from /usr/local/gcc-9.2.0/include/c++/9.2.0/iostream:40,\n                 from main.cpp:1:\n/usr/local/gcc-9.2.0/include/c++/9.2.0/istream:172:7: note: candidate: ‘std::basic_istream<_CharT, _Traits>& std::basic_istream<_CharT, _Traits>::operator>>(short int&) [with _CharT = char; _Traits = std::char_traits<char>]’ <near match>\n  172 |       operator>>(short& __n);\n      |       ^~~~~~~~\n/usr/local/gcc-9.2.0/i