#include <string>

int main() {
    std::string s;
    if (std::cin >> s) {
        int left = 0;
        int right = static_cast<int>(s.length()) - 1;
        bool isPal = true;
        while (left < right) {
            if (s[left] != s[right]) {
                isPal = false;
                break;
            }
            left++;
            right--;
        }
        std::cout << (isPal ? "YES" : "NO");
    }
    return 0;
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "racecar", "passed": true, "status": "Accepted", "stderr": "", "stdout": "YES", "weight": 0.3, "expected": "YES", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "hello", "passed": true, "status": "Accepted", "stderr": "", "stdout": "NO", "weight": 0.4, "expected": "NO", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "a", "passed": true, "status": "Accepted", "stderr": "", "stdout": "YES", "weight": 0.3, "expected": "YES", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Defining main() is strictly forbidden. The system provides its own entry point."}]}}', 10.00, '2026-07-23 08:52:28.035168+00', true, NULL);
INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (2458, 3892, NULL, NULL, '#include <string>

struct Node {
    int data;
    Node* next;
};

std::string buildStringFromList(Node* head) {
    std::string result = "";
    Node* curr = head;
    while (curr != nullptr) {
        result += std::to_string(curr->data);
        if (curr->next != nullptr) {
            result += "->";
        }
        curr = curr->next;
    }
    return result;
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "[1, 2, 3]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "1->2->3\n", "weight": 0.3, "expected": "\"1->2->3\"", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[42]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "42\n", "weight": 0.4, "expected": "\"42\"", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "\n", "weight": 0.3, "expected": "\"\"", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 10.00, '2026-07-23 08:52:26.47808+00', true, NULL);
INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (2460, 3894, NULL, NULL, '#include <string>

int calculateCompressedLength(const std::string& s) {
    if (s.empty()) return 0;
    int compressedLength = 0;
    int count = 1;
    for (size_t i = 1; i < s.length(); ++i) {
        if (s[i] == s[i - 1]) {
            count++;
        } else {
            compressedLength += 1 + std::to_string(count).length();
            count = 1;
        }
    }
    compressedLength += 1 + std::to_string(count).length();
    return compressedLength;
}', '{"feedback": "Passed 0% of the functional test suites.", "black_box": {"ratio": 0, "test_results": [{"input": "\"aaabbc\"", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "10\n", "weight": 0.3, "expected": "6", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "\"a\"", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "6\n", "weight": 0.4, "expected": "2", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "\"\"", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "2\n", "weight": 0.3, "expected": "0", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 0, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 0.00, '2026-07-23 08:52:29.631117+00', true, NULL);
