INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (2451, 3885, NULL, NULL, '#include <vector>

void processPipeline(std::vector<int>& data, int index = 0) {
    if (index >= static_cast<int>(data.size())) return;
    if (index % 2 == 0) {
        data[index] *= 2;
    } else {
        data[index] *= -1;
    }
    processPipeline(data, index + 1);
}', '{"feedback": "Passed 0% of the functional test suites.", "black_box": {"ratio": 0, "test_results": [{"input": "[1, 2, 3, 4]", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "", "weight": 0.3, "expected": "[2, -2, 6, -4]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[5]", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "", "weight": 0.4, "expected": "[10]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[]", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "", "weight": 0.3, "expected": "[]", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 0, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 0.00, '2026-07-23 08:52:15.511858+00', true, NULL);
INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (2499, 3933, NULL, NULL, '#include <iostream>
#include <vector>

void solveNQueens(int row, int n, std::vector<int>& cols, std::vector<int>& diag1, std::vector<int>& diag2, int& count) {
    if (row == n) {
        count++;
        return;
    }
    for (int col = 0; col < n; ++col) {
        if (cols[col] || diag1[row + col] || diag2[row - col + n - 1]) continue;
        cols[col] = diag1[row + col] = diag2[row - col + n - 1] = 1;
        solveNQueens(row + 1, n, cols, diag1, diag2, count);
        cols[col] = diag1[row + col] = diag2[row - col + n - 1] = 0;
    }
}

int main() {
    int n;
    if (std::cin >> n && n > 0) {
        int count = 0;
        std::vector<int> cols(n, 0), diag1(2 * n, 0), diag2(2 * n, 0);
        solveNQueens(0, n, cols, diag1, diag2, count);
        std::cout << count;
    }
    return 0;
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "4", "passed": true, "status": "Accepted", "stderr": "", "stdout": "2", "weight": 0.3, "expected": "2", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "8", "passed": true, "status": "Accepted", "stderr": "", "stdout": "92", "weight": 0.4, "expected": "92", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "1", "passed": true, "status": "Accepted", "stderr": "", "stdout": "1", "weight": 0.3, "expected": "1", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Defining main() is strictly forbidden. The system provides its own entry point."}]}}', 10.00, '2026-07-23 08:59:11.726353+00', true, NULL);
INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (2468, 3902, NULL, NULL, '#include <vector>

struct Node {
    char data;
    Node* next;
};

bool isPalindromeList(Node* head) {
    std::vector<char> chars;
    Node* curr = head;
    while (curr != nullptr) {
        chars.push_back(curr->data);
