INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (2454, 3888, NULL, NULL, '#include <iostream>
#include <string>
#include <vector>
#include <unordered_map>

int main() {
    std::vector<std::unordered_map<std::string, int>> scopes;
    scopes.push_back({}); // global scope
    
    std::string cmd;
    while (std::cin >> cmd) {
        if (cmd == "PUSH") {
            scopes.push_back({});
        } else if (cmd == "POP") {
            if (scopes.size() > 1) {
                scopes.pop_back();
            }
        } else if (cmd == "SET") {
            std::string var;
            int val;
            std::cin >> var >> val;
            scopes.back()[var] = val;
        } else if (cmd == "GET") {
            std::string var;
            std::cin >> var;
            bool found = false;
            for (int i = static_cast<int>(scopes.size()) - 1; i >= 0; --i) {
                if (scopes[i].count(var)) {
                    std::cout << scopes[i][var] << "\n";
                    found = true;
                    break;
                }
            }
            if (!found) {
                std::cout << "UNDEFINED\n";
            }
        }
    }
    return 0;
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "SET x 10\nPUSH\nSET x 20\nGET x\nPOP\nGET x", "passed": true, "status": "Accepted", "stderr": "", "stdout": "20\n10\n", "weight": 0.3, "expected": "20\n10", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "GET y", "passed": true, "status": "Accepted", "stderr": "", "stdout": "UNDEFINED\n", "weight": 0.4, "expected": "UNDEFINED", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "PUSH\nPOP\nGET z", "passed": true, "status": "Accepted", "stderr": "", "stdout": "UNDEFINED\n", "weight": 0.3, "expected": "UNDEFINED", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Defining main() is strictly forbidden. The system provides its own entry point."}]}}', 10.00, '2026-07-23 08:52:20.211932+00', true, NULL);
INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (2469, 3903, NULL, NULL, '#include <iostream>
#include <string>
#include <stack>
#include <cctype>

int main() {
    std::string s;
    if (std::getline(std::cin, s)) {
        std::stack<int> st;
        int num = 0;
        char op = ''+'';
        for (size_t i = 0; i < s.length(); ++i) {
            char c = s[i];
            if (std::isdigit(c)) {
                num = num * 10 + (c - ''0'');
            }
            if ((!std::isdigit(c) && !std::isspace(c)) || i == s.length() - 1) {
                if (op == ''+'') st.push(num);
                else if (op == ''-'') st.push(-num);
                else if (op == ''*'') {
                    int top = st.top(); st.pop();
                    st.push(top * num);
                } else if (op == ''/'') {
                    int top = st.top(); st.pop();
                    st.push(top / num);
                }
                op = c;
                num = 0;
            }
        }
        int result = 0;
        while (!st.empty()) {
            result += st.top();
            st.pop();
        }
        std::cout << result;
    }
    return 0;
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "3+2*2", "passed": true, "status": "Accepted", "stderr": "", "stdout": "7", "weight": 0.3, "expected": "7", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": " 3/2 ", "passed": true, "status": "Accepted", "stderr": "", "stdout": "1", "weight": 0.4, "expected": "1", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": " 3+5 / 2 ", "passed": true, "status": "Accepted", "stderr": "", "stdout": "5", "weight": 0.3, "expected": "5", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Defining main() is strictly forbidden. The system provides its own entry point."}]}}', 10.00, '2026-07-23 08:53:34.041453+00', true, NULL);
INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (2484, 3918, NULL, NULL, '#include <iostream>
#include <string>
#include <vector>

struct Block {
    int id;
    int size;
};

int main() {
    int poolSize;
    if (std::cin >> poolSize) {
        int remaining = poolSize;
        std::vector<Block> allocs;
        int nextId = 0;
        std::string cmd;
        while (std::cin >> cmd) {
            if (cmd == "ALLOC") {
                int sz;
                std::cin >> sz;
                if (sz <= remaining) {
                    remaining -= sz;
                    allocs.push_back({nextId++, sz});
                    std::cout << remaining << "\n";
                } else {
                    std::cout << "FAIL\n";
                }
            } else if (cmd == "FREE") {
                int targetId;
                std::cin >> targetId;
                for (size_t i = 0; i < allocs.size(); ++i) {
                    if (allocs[i].id == targetId) {
                        remaining += allocs[i].size;
                        allocs.erase(allocs.begin() + i);
                        break;
                    }
                }
                std::cout << remaining << "\n";
            }
        }
    }
    return 0;
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "1000\nALLOC 200\nALLOC 300\nFREE 0", "passed": true, "status": "Accepted", "stderr": "", "stdout": "800\n500\n700\n", "weight": 0.3, "expected": "800\n500\n700", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "500\nALLOC 600", "passed": true, "status": "Accepted", "stderr": "", "stdout": "FAIL\n", "weight": 0.4, "expected": "FAIL", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "100\nALLOC 100", "passed": true, "status": "Accepted", "stderr": "", "stdout": "0\n", "weight": 0.3, "expected": "0", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Defining main() is strictly forbidden. The system provides its own entry point."}]}}', 10.00, '2026-07-23 08:57:06.025076+00', true, NULL);
