#include <algorithm>

int maxSubarraySum(const std::vector<int>& nums) {
    if (nums.empty()) return 0;
    int maxSoFar = nums[0];
    int currMax = nums[0];
    for (size_t i = 1; i < nums.size(); ++i) {
        currMax = std::max(nums[i], currMax + nums[i]);
        maxSoFar = std::max(maxSoFar, currMax);
    }
    return maxSoFar;
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "[-2, 1, -3, 4, -1, 2, 1, -5, 4]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "6\n", "weight": 0.3, "expected": "6", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[-1, -2, -3]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "-1\n", "weight": 0.4, "expected": "-1", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "0\n", "weight": 0.3, "expected": "0", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 10.00, '2026-07-29 09:52:56.829616+00', true, NULL);
