INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (10091, 13814, NULL, NULL, 'int resolveState(int flags, int mask, int trigger) {
    if ((flags & mask) == mask) {
        if (flags & (1 << trigger)) {
            return flags ^ mask;
        } else {
            return flags | mask;
        }
    } else {
        return ~flags;
    }
}
', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "7 3 1", "passed": true, "status": "Accepted", "stderr": "", "stdout": "4\n", "weight": 0.3, "expected": "4", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "5 1 2", "passed": true, "status": "Accepted", "stderr": "", "stdout": "4\n", "weight": 0.4, "expected": "4", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "0 1 0", "passed": true, "status": "Accepted", "stderr": "", "stdout": "-1\n", "weight": 0.3, "expected": "-1", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"name": "Security", "type": "FORBID", "passed": true, "target": "security", "weight": 0, "description": "Security Policy Compliance"}, {"name": "Cyclomatic Complexity", "type": "SCORE", "earned": 30, "passed": true, "target": "complexity", "weight": 30, "description": "Complexity is 3. Penalty applied if > 15.", "actual_value": 3}]}}', 10.00, '2026-07-29 11:29:44.947146+00', true, NULL);
