int main() {
    long long n;
    if (std::cin >> n) {
        bool first = true;
        for (long long d = 2; d * d <= n; ++d) {
            while (n % d == 0) {
                if (!first) std::cout << " ";
                std::cout << d;
                first = false;
                n /= d;
            }
