INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (10872, 14601, NULL, NULL, '#include <vector>

int sumSingleRow(const std::vector<int>& row, size_t col = 0) {
    if (col >= row.size()) return 0;
    return row[col] + sumSingleRow(row, col + 1);
}

int recursiveGridRowSum(const std::vector<std::vector<int>>& grid, size_t row = 0) {
