INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (10877, 14606, NULL, NULL, '#include <vector>

int countConnectedRegion(std::vector<std::vector<int>>& grid, int r, int c) {
    if (r < 0 || r >= (int)grid.size() || c < 0 || c >= (int)grid[0].size()) return 0;
    if (grid[r][c] != 1) return 0;
    grid[r][c] = 0;
    return 1 + countConnectedRegion(grid, r + 1, c) +
               countConnectedRegion(grid, r - 1, c) +
               countConnectedRegion(grid, r, c + 1) +
