INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (9585, 12752, NULL, NULL, 'struct Node {
    int data;
    Node* next;
};

Node* reverseLinkedList(Node* head) {
    Node* prev = nullptr;
    Node* curr = head;
    while (curr != nullptr) {
        Node* nextNode = curr->next;
        curr->next = prev;
        prev = curr;
        curr = nextNode;
    }
    return prev;
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "[1, 2, 3, 4]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[4, 3, 2, 1]\n", "weight": 0.3, "expected": "[4, 3, 2, 1]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[10]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[10]\n", "weight": 0.4, "expected": "[10]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[]\n", "weight": 0.3, "expected": "[]", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"name": "Security", "type": "FORBID", "passed": true, "target": "security", "weight": 0, "description": "Security Policy Compliance"}, {"name": "Cyclomatic Complexity", "type": "SCORE", "earned": 30, "passed": true, "target": "complexity", "weight": 30, "description": "Complexity is 2. Penalty applied if > 15.", "actual_value": 2}]}}', 10.00, '2026-07-29 10:12:22.968287+00', true, NULL);
