INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (10884, 14613, NULL, NULL, '#include <iostream>
#include <vector>

void solveNQueens(int row, int n, std::vector<int>& cols, std::vector<int>& diag1, std::vector<int>& diag2, int& count) {
    if (row == n) {
        count++;
        return;
    }
    for (int col = 0; col < n; ++col) {
        if (cols[col] || diag1[row + col] || diag2[row - col + n - 1]) continue;
        cols[col] = diag1[row + col] = diag2[row - col + n - 1] = 1;
        solveNQueens(row + 1, n, cols, diag1, diag2, count);
        cols[col] = diag1[row + col] = diag2[row - col + n - 1] = 0;
    }
}

int main() {
    int n;
    if (std::cin >> n && n > 0) {
        int count = 0;
        std::vector<int> cols(n, 0), diag1(2 * n, 0), diag2(2 * n, 0);
        solveNQueens(0, n, cols, diag1, diag2, count);
        std::cout << count;
    }
    return 0;
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "4", "passed": true, "status": "Accepted", "stderr": "", "stdout": "2", "weight": 0.3, "expected": "2", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "8", "passed": true, "status": "Accepted", "stderr": "", "stdout": "92", "weight": 0.4, "expected": "92", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "1", "passed": true, "status": "Accepted", "stderr": "", "stdout": "1", "weight": 0.3, "expected": "1", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Defining main() is strictly forbidden. The system provides its own entry point."}]}}', 10.00, '2026-07-30 09:06:10.155872+00', true, NULL);
