int getMiddleNodeData(Node* head) {
    if (head == nullptr) return -1;
    Node* slow = head;
    Node* fast = head;
    while (fast != nullptr && fast->next != nullptr) {
        slow = slow->next;
        fast = fast->next->next;
    }
    return slow->data;
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "[1, 2, 3, 4, 5]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "3\n", "weight": 0.3, "expected": "3", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[1, 2, 3, 4]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "3\n", "weight": 0.4, "expected": "3", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "-1\n", "weight": 0.3, "expected": "-1", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"name": "Security", "type": "FORBID", "passed": true, "target": "security", "weight": 0, "description": "Security Policy Compliance"}, {"name": "Cyclomatic Complexity", "type": "SCORE", "earned": 30, "passed": true, "target": "complexity", "weight": 30, "description": "Complexity is 4. Penalty applied if > 15.", "actual_value": 4}]}}', 10.00, '2026-07-29 11:30:13.842614+00', true, NULL);
