std::vector<int> computeRowAlternatingSums(const std::vector<std::vector<int>>& grid) {
    std::vector<int> res;
    for (size_t r = 0; r < grid.size(); ++r) {
        int sum = 0;
        for (size_t c = 0; c < grid[r].size(); ++c) {
