    }
    return res;
}', '{"feedback": "Passed 50% of the functional test suites.", "black_box": {"ratio": 0.5, "test_results": [{"input": "[[1, 2, 3], [4, 5, 6]]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[2, 5]\n", "weight": 0.5, "expected": "[2, 5]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[[10]]", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "[0]\n", "weight": 0.5, "expected": "[10]", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 0.5, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 5.00, '2026-07-29 08:59:30.543975+00', true, NULL);
