INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (9375, 12025, NULL, NULL, '#include <vector>
#include <algorithm>

int longestNonDecreasingRun(const std::vector<int>& nums) {
    if (nums.empty()) return 0;
    int maxLen = 1;
    int currLen = 1;
    for (size_t i = 1; i < nums.size(); ++i) {
        if (nums[i] >= nums[i - 1]) {
            currLen++;
        } else {
            maxLen = std::max(maxLen, currLen);
            currLen = 1;
        }
    }
    return std::max(maxLen, currLen);
