std::string removeVowels(const std::string& s) {
    std::string result = "";
    for (char c : s) {
        char lower = std::tolower(c);
        if (lower != ''a'' && lower != ''e'' && lower != ''i'' && lower != ''o'' && lower != ''u'') {
            result += c;
        }
    }
    return result;
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "\"LeetCode\"", "passed": true, "status": "Accepted", "stderr": "", "stdout": "\"LtCd\"\n", "weight": 0.3, "expected": "\"LtCd\"", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "\"AEIOU\"", "passed": true, "status": "Accepted", "stderr": "", "stdout": "\"\"\n", "weight": 0.4, "expected": "\"\"", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "\"xyz\"", "passed": true, "status": "Accepted", "stderr": "", "stdout": "\"xyz\"\n", "weight": 0.3, "expected": "\"xyz\"", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 10.00, '2026-07-29 11:31:21.005951+00', true, NULL);
