INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (10136, 13859, NULL, NULL, '#include <string>
#include <unordered_map>
#include <algorithm>

int lengthOfLongestSubstring(const std::string& s) {
    std::unordered_map<char, int> charMap;
    int maxLen = 0;
    int start = 0;
    for (int end = 0; end < static_cast<int>(s.length()); ++end) {
        if (charMap.count(s[end]) && charMap[s[end]] >= start) {
            start = charMap[s[end]] + 1;
        }
        charMap[s[end]] = end;
        maxLen = std::max(maxLen, end - start + 1);
    }
    return maxLen;
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "\"abcabcbb\"", "passed": true, "status": "Accepted", "stderr": "", "stdout": "3\n", "weight": 0.3, "expected": "3", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "\"bbbbb\"", "passed": true, "status": "Accepted", "stderr": "", "stdout": "1\n", "weight": 0.4, "expected": "1", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "\"\"", "passed": true, "status": "Accepted", "stderr": "", "stdout": "0\n", "weight": 0.3, "expected": "0", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 10.00, '2026-07-29 11:31:52.520852+00', true, NULL);
INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (10137, 13860, NULL, NULL, '#include <vector>
#include <string>
#include <unordered_map>
#include <algorithm>

std::vector<std::string> sortWordsByAnagramGroup(const std::vector<std::string>& strs) {
    std::unordered_map<std::string, std::vector<std::string>> groups;
    for (const auto& s : strs) {
        std::string key = s;
        std::sort(key.begin(), key.end());
        groups[key].push_back(s);
    }
    std::vector<std::string> result;
    for (const auto& s : strs) {
        std::string key = s;
        std::sort(key.begin(), key.end());
        if (groups.count(key)) {
            for (const auto& item : groups[key]) {
                result.push_back(item);
            }
            groups.erase(key);
        }
    }
    return result;
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "[\"eat\", \"tea\", \"tan\", \"ate\", \"nat\", \"bat\"]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[\"eat\", \"tea\", \"ate\", \"tan\", \"nat\", \"bat\"]\n", "weight": 0.3, "expected": "[\"eat\", \"tea\", \"ate\", \"tan\", \"nat\", \"bat\"]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[\"a\"]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[\"a\"]\n", "weight": 0.4, "expected": "[\"a\"]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[]\n", "weight": 0.3, "expected": "[]", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 10.00, '2026-07-29 11:31:54.122026+00', true, NULL);
INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (10138, 13861, NULL, NULL, '#include <vector>
#include <string>

bool dfs(std::vector<std::vector<char>>& board, const std::string& word, int r, int c, size_t index) {
    if (index == word.length()) return true;
    if (r < 0 || r >= static_cast<int>(board.size()) || c < 0 || c >= static_cast<int>(board[0].size()) || board[r][c] != word[index]) {
        return false;
    }
    char temp = board[r][c];
    board[r][c] = ''#'';
    bool found = dfs(board, word, r + 1, c, index + 1) ||
                 dfs(board, word, r - 1, c, index + 1) ||
                 dfs(board, word, r, c + 1, index + 1) ||
                 dfs(board, word, r, c - 1, index + 1);
    board[r][c] = temp;
    return found;
}

bool existWord(const std::vector<std::vector<char>>& board, std::string word) {
    if (board.empty() || board[0].empty()) return false;
    auto grid = board;
    for (size_t r = 0; r < grid.size(); ++r) {
        for (size_t c = 0; c < grid[0].size(); ++c) {
            if (dfs(grid, word, static_cast<int>(r), static_cast<int>(c), 0)) {
                return true;
            }
        }
    }
    return false;
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "[[''A'',''B'',''C'',''E''],[''S'',''F'',''C'',''S''],[''A'',''D'',''E'',''E'']], \"ABCCED\"", "passed": true, "status": "Accepted", "stderr": "", "stdout": "true\n", "weight": 0.3, "expected": "true", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[[''A'',''B'']], \"AC\"", "passed": true, "status": "Accepted", "stderr": "", "stdout": "false\n", "weight": 0.4, "expected": "false", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[], \"A\"", "passed": true, "status": "Accepted", "stderr": "", "stdout": "false\n", "weight": 0.3, "expected": "false", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 10.00, '2026-07-29 11:31:57.800536+00', true, NULL);
INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (10139, 13862, NULL, NULL, '#include <vector>

struct Node {
    char data;
    Node* next;
};

bool isPalindromeList(Node* head) {
    std::vector<char> chars;
    Node* curr = head;
    while (curr != nullptr) {
        chars.push_back(curr->data);
        curr = curr->next;
    }
    int left = 0;
    int right = static_cast<int>(chars.size()) - 1;
    while (left < right) {
        if (chars[left] != chars[right]) return false;
        left++;
        right--;
    }
    return true;
}', '{"feedback": "Passed 30% of the functional test suites.", "black_box": {"ratio": 0.3, "test_results": [{"input": "[''r'', ''a'', ''c'', ''e'', ''c'', ''a'', ''r'']", "passed": false, "status": "Wrong Answer", "stderr": "PARSE_ERROR: input line did not match expected parameter types for this signature: [''r'', ''a'', ''c'', ''e'', ''c'', ''a'', ''r'']\n", "stdout": "", "weight": 0.3, "expected": "true", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[''a'', ''b'']", "passed": false, "status": "Wrong Answer", "stderr": "PARSE_ERROR: input line did not match expected parameter types for this signature: [''a'', ''b'']\n", "stdout": "", "weight": 0.4, "expected": "false", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "true\n", "weight": 0.3, "expected": "true", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 0.3, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 3.00, '2026-07-29 11:32:01.608158+00', true, NULL);
INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (10140, 13863, NULL, NULL, '#include <iostream>
#include <string>
#include <stack>
#include <cctype>

int main() {
    std::string s;
    if (std::getline(std::cin, s)) {
        std::stack<int> st;
        int num = 0;
        char op = ''+'';
        for (size_t i = 0; i < s.length(); ++i) {
            char c = s[i];
            if (std::isdigit(c)) {
                num = num * 10 + (c - ''0'');
            }
            if ((!std::isdigit(c) && !std::isspace(c)) || i == s.length() - 1) {
                if (op == ''+'') st.push(num);
                else if (op == ''-'') st.push(-num);
                else if (op == ''*'') {
                    int top = st.top(); st.pop();
                    st.push(top * num);
                } else if (op == ''/'') {
                    int top = st.top(); st.pop();
                    st.push(top / num);
                }
                op = c;
                num = 0;
            }
        }
        int result = 0;
        while (!st.empty()) {
            result += st.top();
            st.pop();
        }
        std::cout << result;
    }
    return 0;
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "3+2*2", "passed": true, "status": "Accepted", "stderr": "", "stdout": "7", "weight": 0.3, "expected": "7", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": " 3/2 ", "passed": true, "status": "Accepted", "stderr": "", "stdout": "1", "weight": 0.4, "expected": "1", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": " 3+5 / 2 ", "passed": true, "status": "Accepted", "stderr": "", "stdout": "5", "weight": 0.3, "expected": "5", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Defining main() is strictly forbidden. The system provides its own entry point."}]}}', 10.00, '2026-07-29 11:32:05.27599+00', true, NULL);
