INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (10887, 14616, NULL, NULL, '#include <vector>

struct Pixel {
    int r, g, b;
};

std::vector<std::vector<int>> computeGrayscaleGrid(const std::vector<std::vector<Pixel>>& image) {
    std::vector<std::vector<int>> result;
    result.reserve(image.size());
    for (const auto& row : image) {
        std::vector<int> rowGray;
        rowGray.reserve(row.size());
        for (const auto& p : row) {
            rowGray.push_back((p.r + p.g + p.b) / 3);
        }
        result.push_back(rowGray);
    }
    return result;
}', '{"feedback": "Passed 30% of the functional test suites.", "black_box": {"ratio": 0.3, "test_results": [{"input": "[[Pixel(255,255,255), Pixel(0,0,0)]]", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "[[255, 0, 0]]\n", "weight": 0.3, "expected": "[[255, 0]]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[[Pixel(10,20,30)]]", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "[[20, 20]]\n", "weight": 0.4, "expected": "[[20]]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[]\n", "weight": 0.3, "expected": "[]", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 0.3, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 3.00, '2026-07-30 09:06:16.86016+00', true, NULL);
