INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (10888, 14617, NULL, NULL, 'struct Node {
    int data;
    Node* next;
};

class LinkedListWrapper {
private:
    Node* head;
public:
    LinkedListWrapper() : head(nullptr) {}
    void append(int val) {
        Node* newNode = new Node{val, nullptr};
        if (head == nullptr) {
            head = newNode;
            return;
        }
        Node* curr = head;
        while (curr->next != nullptr) {
            curr = curr->next;
        }
        curr->next = newNode;
    }
    int getHeadVal() const {
        if (head == nullptr) return -1;
        return head->data;
    }
};', '{"feedback": "Passed 0% of the functional test suites.", "black_box": {"ratio": 0, "test_results": [{"input": "append(10), getHeadVal()", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "[object]\n", "weight": 0.3, "expected": "10", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "getHeadVal()", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "[object]\n", "weight": 0.4, "expected": "-1", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "append(5), append(20), getHeadVal()", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "[object]\n", "weight": 0.3, "expected": "5", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 0, "details": [{"name": "Security", "type": "FORBID", "passed": true, "target": "security", "weight": 0, "description": "Security Policy Compliance"}, {"name": "Cyclomatic Complexity", "type": "SCORE", "earned": 30, "passed": true, "target": "complexity", "weight": 30, "description": "Complexity is 4. Penalty applied if > 15.", "actual_value": 4}]}}', 0.00, '2026-07-30 09:06:18.454572+00', true, NULL);
INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (10889, 14618, NULL, NULL, '#include <iostream>
#include <string>

class Counter {
private:
    int value;
public:
    Counter() : value(0) {}
    void increment() { value++; }
    void decrement() { value--; }
    int getValue() const { return value; }
};

int main() {
    Counter c;
    std::string cmd;
    while (std::cin >> cmd) {
        if (cmd == "INC") c.increment();
        else if (cmd == "DEC") c.decrement();
        else if (cmd == "GET") std::cout << c.getValue() << "\n";
