INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (10893, 14622, NULL, NULL, 'struct Node {
    int data;
    Node* next;
};

class LinkedList {
private:
    Node* head;
public:
    LinkedList() : head(nullptr) {}
    ~LinkedList() {
        Node* curr = head;
        while (curr != nullptr) {
            Node* nextNode = curr->next;
            delete curr;
            curr = nextNode;
        }
    }
    void pushFront(int val) {
        head = new Node{val, head};
    }
    int popFront() {
        if (head == nullptr) return -1;
        Node* temp = head;
        int val = temp->data;
        head = head->next;
        delete temp;
        return val;
    }
};', '{"feedback": "Passed 0% of the functional test suites.", "black_box": {"ratio": 0, "test_results": [{"input": "pushFront(10), pushFront(20), popFront()", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "[object]\n", "weight": 0.3, "expected": "20", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "popFront() empty", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "[object]\n", "weight": 0.4, "expected": "-1", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "push 5, pop, pop", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "[object]\n", "weight": 0.3, "expected": "5 then -1", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 0, "details": [{"name": "Security", "type": "FORBID", "passed": true, "target": "security", "weight": 0, "description": "Security Policy Compliance"}, {"name": "Cyclomatic Complexity", "type": "SCORE", "earned": 30, "passed": true, "target": "complexity", "weight": 30, "description": "Complexity is 3. Penalty applied if > 15.", "actual_value": 3}]}}', 0.00, '2026-07-30 09:06:28.404737+00', true, NULL);
INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (10894, 14623, NULL, NULL, '#include <iostream>
#include <string>
#include <iomanip>

class Shape {
public:
    virtual double area() const = 0;
    virtual ~Shape() {}
};

class Rectangle : public Shape {
private:
    double w, h;
public:
    Rectangle(double w, double h) : w(w), h(h) {}
    double area() const override { return w * h; }
};

class Circle : public Shape {
private:
    double r;
public:
    Circle(double r) : r(r) {}
    double area() const override { return 3.141592653589793 * r * r; }
};

int main() {
    std::string type;
    while (std::cin >> type) {
        if (type == "RECT") {
            double w, h;
            std::cin >> w >> h;
            Rectangle rect(w, h);
            std::cout << std::fixed << std::setprecision(1) << rect.area() << "\n";
        } else if (type == "CIRC") {
            double r;
            std::cin >> r;
            Circle circ(r);
            std::cout << std::fixed << std::setprecision(3) << circ.area() << "\n";
        }
    }
    return 0;
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "RECT 4 5\nCIRC 3", "passed": true, "status": "Accepted", "stderr": "", "stdout": "20.0\n28.274\n", "weight": 0.3, "expected": "20.0\n28.274", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "RECT 0 10", "passed": true, "status": "Accepted", "stderr": "", "stdout": "0.0\n", "weight": 0.4, "expected": "0.0", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "CIRC 0", "passed": true, "status": "Accepted", "stderr": "", "stdout": "0.000\n", "weight": 0.3, "expected": "0.0", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Defining main() is strictly forbidden. The system provides its own entry point."}]}}', 10.00, '2026-07-30 09:06:29.971715+00', true, NULL);
