class Complex {
private:
    double real, imag;
public:
    Complex(double r = 0, double i = 0) : real(r), imag(i) {}
    Complex operator+(const Complex& other) const {
        return Complex(real + other.real, imag + other.imag);
    }
    Complex operator-(const Complex& other) const {
        return Complex(real - other.real, imag - other.imag);
    }
    bool operator==(const Complex& other) const {
        return real == other.real && imag == other.imag;
    }
};', '{"feedback": "Passed 0% of the functional test suites.", "black_box": {"ratio": 0, "test_results": [{"input": "(1+2i) + (3+4i)", "passed": false, "status": "Wrong Answer", "stderr": "PARSE_ERROR: input line did not match expected parameter types for this signature: (1+2i) + (3+4i)\n", "stdout": "", "weight": 0.3, "expected": "4+6i", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "(5+0i) == (5+0i)", "passed": false, "status": "Wrong Answer", "stderr": "PARSE_ERROR: input line did not match expected parameter types for this signature: (5+0i) == (5+0i)\n", "stdout": "", "weight": 0.4, "expected": "true", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "(0+0i) - (1+1i)", "passed": false, "status": "Wrong Answer", "stderr": "PARSE_ERROR: input line did not match expected parameter types for this signature: (0+0i) - (1+1i)\n", "stdout": "", "weight": 0.3, "expected": "-1-1i", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 0, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 0.00, '2026-07-30 09:06:31.536908+00', true, NULL);
INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (10896, 14625, NULL, NULL, '#include <iostream>
#include <algorithm>

class IntVector {
private:
    int* data;
    size_t sz;
    size_t cap;
public:
    IntVector() : data(nullptr), sz(0), cap(0) {}
    ~IntVector() { delete[] data; }
    
    IntVector(const IntVector& other) : sz(other.sz), cap(other.cap) {
        data = new int[cap];
        for (size_t i = 0; i < sz; ++i) data[i] = other.data[i];
    }
    
    IntVector& operator=(const IntVector& other) {
        if (this != &other) {
            delete[] data;
            sz = other.sz;
            cap = other.cap;
            data = new int[cap];
            for (size_t i = 0; i < sz; ++i) data[i] = other.data[i];
        }
        return *this;
    }
    
    IntVector(IntVector&& other) noexcept : data(other.data), sz(other.sz), cap(other.cap) {
        other.data = nullptr;
        other.sz = 0;
        other.cap = 0;
    }
    
    IntVector& operator=(IntVector&& other) noexcept {
        if (this != &other) {
            delete[] data;
            data = other.data;
            sz = other.sz;
            cap = other.cap;
            other.data = nullptr;
            other.sz = 0;
            other.cap = 0;
        }
        return *this;
    }
    
    void push_back(int val) {
        if (sz == cap) {
            size_t newCap = cap == 0 ? 1 : cap * 2;
            int* newData = new int[newCap];
            for (size_t i = 0; i < sz; ++i) newData[i] = data[i];
            delete[] data;
            data = newData;
            cap = newCap;
        }
        data[sz++] = val;
    }
    size_t size() const { return sz; }
};', '{"feedback": "Passed 0% of the functional test suites.", "black_box": {"ratio": 0, "test_results": [{"input": "push 1, 2, move assign", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "", "weight": 0.3, "expected": "[1, 2]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "copy construct", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "", "weight": 0.4, "expected": "deep copy verified", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "empty vector move", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "", "weight": 0.3, "expected": "size 0", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 0, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 0.00, '2026-07-30 09:06:33.103436+00', true, NULL);
INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (10898, 14627, NULL, NULL, 'struct Node {
    int data;
    Node* prev;
    Node* next;
};

class DoublyLinkedList {
private:
    Node* head;
    Node* tail;
public:
    DoublyLinkedList() : head(nullptr), tail(nullptr) {}
    ~DoublyLinkedList() {
        Node* curr = head;
        while (curr != nullptr) {
            Node* nextNode = curr->next;
            delete curr;
            curr = nextNode;
        }
    }
    void pushFront(int val) {
        Node* newNode = new Node{val, nullptr, head};
        if (head != nullptr) head->prev = newNode;
        head = newNode;
        if (tail == nullptr) tail = head;
    }
    void pushBack(int val) {
        Node* newNode = new Node{val, tail, nullptr};
        if (tail != nullptr) tail->next = newNode;
        tail = newNode;
        if (head == nullptr) head = tail;
    }
    int popFront() {
        if (head == nullptr) return -1;
        Node* temp = head;
        int val = temp->data;
        head = head->next;
        if (head != nullptr) head->prev = nullptr;
        else tail = nullptr;
        delete temp;
        return val;
    }
    int popBack() {
        if (tail == nullptr) return -1;
        Node* temp = tail;
        int val = temp->data;
        tail = tail->prev;
        if (tail != nullptr) tail->next = nullptr;
        else head = nullptr;
        delete temp;
        return val;
    }
};', '{"feedback": "Passed 0% of the functional test suites.", "black_box": {"ratio": 0, "test_results": [{"input": "pushFront(1), pushBack(2), popFront()", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "[object]\n", "weight": 0.3, "expected": "pop:1, list:[2]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "popBack empty", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "[object]\n", "weight": 0.4, "expected": "no-op/error flag", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "single item push pop", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "[object]\n", "weight": 0.3, "expected": "empty", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 0, "details": [{"name": "Security", "type": "FORBID", "passed": true, "target": "security", "weight": 0, "description": "Security Policy Compliance"}, {"name": "Cyclomatic Complexity", "type": "SCORE", "earned": 30, "passed": true, "target": "complexity", "weight": 30, "description": "Complexity is 10. Penalty applied if > 15.", "actual_value": 10}]}}', 0.00, '2026-07-30 09:06:38.265616+00', true, NULL);
INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (10899, 14628, NULL, NULL, '#include <iostream>
#include <string>
#include <unordered_map>
#include <memory>

class Plugin {
public:
    virtual int execute(int val) = 0;
    virtual ~Plugin() = default;
};

class AddPlugin : public Plugin {
private:
    int total = 0;
public:
    int execute(int val) override {
        total += val;
        return total;
    }
};

class MultPlugin : public Plugin {
private:
    int total = 1;
public:
    int execute(int val) override {
        total *= val;
        return total;
    }
};

int main() {
    std::unordered_map<int, std::unique_ptr<Plugin>> plugins;
    std::string cmd;
    while (std::cin >> cmd) {
        if (cmd == "CREATE") {
            std::string type;
            int id;
            std::cin >> type >> id;
            if (type == "Add") plugins[id] = std::make_unique<AddPlugin>();
            else if (type == "Mult") plugins[id] = std::make_unique<MultPlugin>();
        } else if (cmd == "EXEC") {
            int id, val;
            std::cin >> id >> val;
            if (plugins.count(id)) {
                std::cout << plugins[id]->execute(val) << "\n";
            } else {
                std::cout << "NOT_FOUND\n";
            }
        }
    }
    return 0;
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "CREATE Add 1\nEXEC 1 10\nEXEC 1 20", "passed": true, "status": "Accepted", "stderr": "", "stdout": "10\n30\n", "weight": 0.3, "expected": "10\n30", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "EXEC 99 5", "passed": true, "status": "Accepted", "stderr": "", "stdout": "NOT_FOUND\n", "weight": 0.4, "expected": "NOT_FOUND", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "CREATE Mult 2\nEXEC 2 0", "passed": true, "status": "Accepted", "stderr": "", "stdout": "0\n", "weight": 0.3, "expected": "0", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Defining main() is strictly forbidden. The system provides its own entry point."}]}}', 10.00, '2026-07-30 09:06:39.842024+00', true, NULL);
INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (9763, 13205, NULL, NULL, '#include <vector>

std::vector<int> classifySigns(const std::vector<int>& numbers) {
    std::vector<int> result;
    result.reserve(numbers.size());
    for (int num : numbers) {
        if (num > 0) result.push_back(1);
        else if (num < 0) result.push_back(-1);
        else result.push_back(0);
