#include <unordered_map>

int findMostFrequent(const std::vector<int>& nums) {
    if (nums.empty()) return 0;
    std::unordered_map<int, int> freq;
    for (int x : nums) {
        freq[x]++;
    }
    int mode = nums[0];
    int maxCount = 0;
    for (const auto& pair : freq) {
        if (pair.second > maxCount) {
            maxCount = pair.second;
            mode = pair.first;
        }
    }
    return mode;
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "[1, 3, 2, 3, 4, 1, 3]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "3\n", "weight": 0.3, "expected": "3", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[2, 2, 1, 1]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "1\n", "weight": 0.4, "expected": "1", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[5]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "5\n", "weight": 0.3, "expected": "5", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 10.00, '2026-07-30 09:06:49.26749+00', true, NULL);
INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (10906, 14635, NULL, NULL, '#include <string>
#include <stack>

bool isValidParentheses(const std::string& s) {
    std::stack<char> st;
    for (char c : s) {
        if (c == ''('' || c == ''{'' || c == ''['') {
            st.push(c);
        } else if (c == '')'' || c == ''}'' || c == '']'') {
            if (st.empty()) return false;
            char top = st.top();
            st.pop();
            if ((c == '')'' && top != ''('') ||
                (c == ''}'' && top != ''{'') ||
                (c == '']'' && top != ''['')) {
                return false;
            }
        }
    }
    return st.empty();
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "\"()[]{}\"", "passed": true, "status": "Accepted", "stderr": "", "stdout": "true\n", "weight": 0.3, "expected": "true", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "\"(]\"", "passed": true, "status": "Accepted", "stderr": "", "stdout": "false\n", "weight": 0.4, "expected": "false", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "\"\"", "passed": true, "status": "Accepted", "stderr": "", "stdout": "true\n", "weight": 0.3, "expected": "true", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 10.00, '2026-07-30 09:06:50.83688+00', true, NULL);
INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (10907, 14636, NULL, NULL, '#include <vector>
#include <queue>

int shortestPathGrid(const std::vector<std::vector<int>>& grid) {
    if (grid.empty() || grid[0].empty()) return -1;
    int rows = grid.size();
    int cols = grid[0].size();
    if (grid[0][0] != 0 || grid[rows-1][cols-1] != 0) return -1;
    if (rows == 1 && cols == 1) return 1;

    std::queue<std::pair<int, int>> q;
    std::vector<std::vector<int>> dist(rows, std::vector<int>(cols, -1));

    q.push({0, 0});
    dist[0][0] = 1;

    int dr[] = {1, -1, 0, 0};
    int dc[] = {0, 0, 1, -1};

    while (!q.empty()) {
        auto [r, c] = q.front();
        q.pop();

        for (int i = 0; i < 4; ++i) {
            int nr = r + dr[i];
            int nc = c + dc[i];

            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && grid[nr][nc] == 0 && dist[nr][nc] == -1) {
                dist[nr][nc] = dist[r][c] + 1;
                if (nr == rows - 1 && nc == cols - 1) return dist[nr][nc];
                q.push({nr, nc});
            }
        }
    }
    return -1;
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "[[0,0,0],[1,1,0],[0,0,0]]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "5\n", "weight": 0.3, "expected": "5", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[[0,1],[1,0]]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "-1\n", "weight": 0.4, "expected": "-1", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[[0]]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "1\n", "weight": 0.3, "expected": "1", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 10.00, '2026-07-30 09:06:52.406787+00', true, NULL);
