INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (10908, 14637, NULL, NULL, '#include <unordered_set>

struct Node {
    int data;
    Node* next;
};

bool hasCycleSet(Node* head) {
    std::unordered_set<Node*> visited;
    Node* curr = head;
    while (curr != nullptr) {
        if (visited.count(curr)) return true;
        visited.insert(curr);
        curr = curr->next;
    }
    return false;
}', '{"feedback": "Passed 30% of the functional test suites.", "black_box": {"ratio": 0.3, "test_results": [{"input": "1->2->3->2 (cycle)", "passed": false, "status": "Wrong Answer", "stderr": "PARSE_ERROR: input line did not match expected parameter types for this signature: 1->2->3->2 (cycle)\n", "stdout": "", "weight": 0.3, "expected": "true", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "1->2->3", "passed": false, "status": "Wrong Answer", "stderr": "PARSE_ERROR: input line did not match expected parameter types for this signature: 1->2->3\n", "stdout": "", "weight": 0.4, "expected": "false", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "false\n", "weight": 0.3, "expected": "false", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 0.3, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 3.00, '2026-07-30 09:06:53.971234+00', true, NULL);
INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (10275, 14016, NULL, NULL, '#include <vector>

struct Pixel {
    int r, g, b;
};

std::vector<std::vector<int>> computeGrayscaleGrid(const std::vector<std::vector<Pixel>>& image) {
    std::vector<std::vector<int>> result;
    result.reserve(image.size());
    for (const auto& row : image) {
        std::vector<int> rowGray;
        rowGray.reserve(row.size());
        for (const auto& p : row) {
            rowGray.push_back((p.r + p.g + p.b) / 3);
        }
        result.push_back(rowGray);
    }
    return result;
}', '{"feedback": "Passed 30% of the functional test suites.", "black_box": {"ratio": 0.3, "test_results": [{"input": "[[Pixel(255,255,255), Pixel(0,0,0)]]", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "[[255, 0, 0]]\n", "weight": 0.3, "expected": "[[255, 0]]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[[Pixel(10,20,30)]]", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "[[20, 20]]\n", "weight": 0.4, "expected": "[[20]]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[]\n", "weight": 0.3, "expected": "[]", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 0.3, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 3.00, '2026-07-29 11:51:55.272985+00', true, NULL);
INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (10909, 14638, NULL, NULL, '#include <iostream>
#include <string>
#include <queue>

struct Task {
    std::string name;
    int priority;
    bool operator<(const Task& other) const {
        return priority < other.priority;
    }
};

int main() {
