INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (10910, 14639, NULL, NULL, '#include <unordered_map>
#include <list>

class LRUCache {
private:
    int cap;
    std::list<std::pair<int, int>> cache;
    std::unordered_map<int, std::list<std::pair<int, int>>::iterator> map;
public:
    LRUCache(int capacity) : cap(capacity) {}

    int get(int key) {
        if (!map.count(key)) return -1;
        cache.splice(cache.begin(), cache, map[key]);
        return map[key]->second;
    }

    void put(int key, int value) {
        if (map.count(key)) {
            map[key]->second = value;
            cache.splice(cache.begin(), cache, map[key]);
            return;
        }
        if (static_cast<int>(cache.size()) == cap) {
            int delKey = cache.back().first;
            cache.pop_back();
            map.erase(delKey);
        }
        cache.push_front({key, value});
        map[key] = cache.begin();
    }
};', '{"feedback": "Passed 0% of the functional test suites.", "black_box": {"ratio": 0, "test_results": [{"input": "cap=2, put(1,1), put(2,2), get(1), put(3,3), get(2)", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "", "weight": 0.3, "expected": "get(1)=1, get(2)=-1", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "get non-existent", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "", "weight": 0.4, "expected": "-1", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "put update existing key", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "", "weight": 0.3, "expected": "updated value returned", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 0, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 0.00, '2026-07-30 09:06:59.142527+00', true, NULL);
INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (10911, 14640, NULL, NULL, '#include <vector>
#include <deque>

std::vector<int> maxSlidingWindow(const std::vector<int>& nums, int k) {
    if (nums.empty() || k <= 0) return {};
    std::vector<int> result;
    std::deque<int> dq;

    for (int i = 0; i < static_cast<int>(nums.size()); ++i) {
        if (!dq.empty() && dq.front() == i - k) {
            dq.pop_front();
        }
        while (!dq.empty() && nums[dq.back()] <= nums[i]) {
            dq.pop_back();
        }
        dq.push_back(i);
        if (i >= k - 1) {
            result.push_back(nums[dq.front()]);
        }
    }
    return result;
}', '{"feedback": "Passed 0% of the functional test suites.", "black_box": {"ratio": 0, "test_results": [{"input": "[1,3,-1,-3,5,3,6,7], k=3", "passed": false, "status": "Wrong Answer", "stderr": "PARSE_ERROR: input line did not match expected parameter types for this signature: [1,3,-1,-3,5,3,6,7], k=3\n", "stdout": "", "weight": 0.3, "expected": "[3,3,5,5,6,7]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[1], k=1", "passed": false, "status": "Wrong Answer", "stderr": "PARSE_ERROR: input line did not match expected parameter types for this signature: [1], k=1\n", "stdout": "", "weight": 0.4, "expected": "[1]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[], k=0", "passed": false, "status": "Wrong Answer", "stderr": "PARSE_ERROR: input line did not match expected parameter types for this signature: [], k=0\n", "stdout": "", "weight": 0.3, "expected": "[]", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 0, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 0.00, '2026-07-30 09:07:02.724188+00', true, NULL);
INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (10912, 14641, NULL, NULL, '#include <vector>
#include <queue>
#include <tuple>

int minCostGridPath(const std::vector<std::vector<int>>& grid) {
    if (grid.empty() || grid[0].empty()) return 0;
    int rows = grid.size();
    int cols = grid[0].size();

    std::priority_queue<std::tuple<int, int, int>, std::vector<std::tuple<int, int, int>>, std::greater<std::tuple<int, int, int>>> pq;
    std::vector<std::vector<int>> dist(rows, std::vector<int>(cols, 1e9));

    dist[0][0] = grid[0][0];
    pq.push({grid[0][0], 0, 0});

    int dr[] = {1, -1, 0, 0};
    int dc[] = {0, 0, 1, -1};

    while (!pq.empty()) {
        auto [d, r, c] = pq.top();
        pq.pop();

        if (r == rows - 1 && c == cols - 1) return d;
        if (d > dist[r][c]) continue;

        for (int i = 0; i < 4; ++i) {
            int nr = r + dr[i];
            int nc = c + dc[i];

            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols) {
                if (dist[r][c] + grid[nr][nc] < dist[nr][nc]) {
                    dist[nr][nc] = dist[r][c] + grid[nr][nc];
                    pq.push({dist[nr][nc], nr, nc});
                }
            }
        }
    }
    return dist[rows - 1][cols - 1];
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "[[1,3,1],[1,5,1],[4,2,1]]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "7\n", "weight": 0.3, "expected": "7", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[[1,2],[1,1]]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "3\n", "weight": 0.4, "expected": "3", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[[5]]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "5\n", "weight": 0.3, "expected": "5", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 10.00, '2026-07-30 09:07:04.309611+00', true, NULL);
INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (10913, 14642, NULL, NULL, '#include <vector>
#include <queue>

struct Node {
    int data;
    Node* next;
};

struct CompareNode {
    bool operator()(Node* a, Node* b) {
        return a->data > b->data;
    }
};

Node* mergeKSortedLists(const std::vector<Node*>& lists) {
    std::priority_queue<Node*, std::vector<Node*>, CompareNode> pq;
    for (auto node : lists) {
        if (node != nullptr) pq.push(node);
    }
    Node dummy{0, nullptr};
    Node* tail = &dummy;

    while (!pq.empty()) {
        Node* top = pq.top();
        pq.pop();
        tail->next = top;
        tail = tail->next;
        if (top->next != nullptr) {
            pq.push(top->next);
        }
    }
    return dummy.next;
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "[[1,4,5],[1,3,4],[2,6]]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[1, 1, 2, 3, 4, 4, 5, 6]\n", "weight": 0.3, "expected": "[1,1,2,3,4,4,5,6]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[]\n", "weight": 0.4, "expected": "[]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[[]]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[]\n", "weight": 0.3, "expected": "[]", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 10.00, '2026-07-30 09:07:05.899088+00', true, NULL);
INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (10914, 14643, NULL, NULL, '#include <iostream>
#include <queue>
#include <iomanip>

int main() {
    int n;
    if (std::cin >> n && n > 0) {
        std::priority_queue<int> maxHeap;
        std::priority_queue<int, std::vector<int>, std::greater<int>> minHeap;

        for (int i = 0; i < n; ++i) {
            int val;
            std::cin >> val;
            if (maxHeap.empty() || val <= maxHeap.top()) {
                maxHeap.push(val);
            } else {
                minHeap.push(val);
            }

            if (maxHeap.size() > minHeap.size() + 1) {
                minHeap.push(maxHeap.top());
                maxHeap.pop();
            } else if (minHeap.size() > maxHeap.size()) {
                maxHeap.push(minHeap.top());
                minHeap.pop();
            }

            if (maxHeap.size() == minHeap.size()) {
                double med = (maxHeap.top() + minHeap.top()) / 2.0;
                std::cout << std::fixed << std::setprecision(1) << med << "\n";
            } else {
                std::cout << std::fixed << std::setprecision(1) << static_cast<double>(maxHeap.top()) << "\n";
            }
        }
    }
    return 0;
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "3\n1\n2\n3", "passed": true, "status": "Accepted", "stderr": "", "stdout": "1.0\n1.5\n2.0\n", "weight": 0.3, "expected": "1.0\n1.5\n2.0", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "1\n5", "passed": true, "status": "Accepted", "stderr": "", "stdout": "5.0\n", "weight": 0.4, "expected": "5.0", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "2\n10 20", "passed": true, "status": "Accepted", "stderr": "", "stdout": "10.0\n15.0\n", "weight": 0.3, "expected": "10.0\n15.0", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Defining main() is strictly forbidden. The system provides its own entry point."}]}}', 10.00, '2026-07-30 09:07:07.467185+00', true, NULL);
