#include <unordered_map>
#include <algorithm>

int lengthOfLongestSubstring(const std::string& s) {
    std::unordered_map<char, int> charMap;
    int maxLen = 0;
    int start = 0;
    for (int end = 0; end < static_cast<int>(s.length()); ++end) {
        if (charMap.count(s[end]) && charMap[s[end]] >= start) {
            start = charMap[s[end]] + 1;
        }
        charMap[s[end]] = end;
        maxLen = std::max(maxLen, end - start + 1);
    }
    return maxLen;
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "\"abcabcbb\"", "passed": true, "status": "Accepted", "stderr": "", "stdout": "3\n", "weight": 0.3, "expected": "3", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "\"bbbbb\"", "passed": true, "status": "Accepted", "stderr": "", "stdout": "1\n", "weight": 0.4, "expected": "1", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "\"\"", "passed": true, "status": "Accepted", "stderr": "", "stdout": "0\n", "weight": 0.3, "expected": "0", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 10.00, '2026-07-30 09:28:22.475372+00', true, NULL);
INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (10954, 14683, NULL, NULL, '#include <iostream>
#include <iomanip>
#include <algorithm>

int main() {
    int n;
    if (std::cin >> n && n > 0) {
        long long sum = 0;
        int minVal = 0, maxVal = 0;
        for (int i = 1; i <= n; ++i) {
            int val;
            std::cin >> val;
            if (i == 1) {
                minVal = maxVal = val;
            } else {
                minVal = std::min(minVal, val);
                maxVal = std::max(maxVal, val);
            }
            sum += val;
            double avg = static_cast<double>(sum) / i;
            std::cout << "min:" << minVal << " max:" << maxVal << " avg:" << std::fixed << std::setprecision(1) << avg << "\n";
        }
