INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (9400, 12145, NULL, NULL, '#include <vector>
#include <algorithm>

int longestNonDecreasingRun(const std::vector<int>& nums) {
    if (nums.empty()) return 0;
    int maxLen = 1;
    int currLen = 1;
    for (size_t i = 1; i < nums.size(); ++i) {
        if (nums[i] >= nums[i - 1]) {
            currLen++;
        } else {
            maxLen = std::max(maxLen, currLen);
            currLen = 1;
        }
    }
    return std::max(maxLen, currLen);
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "[1, 2, 2, 1, 3, 4, 5]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "4\n", "weight": 0.3, "expected": "4", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[5, 4, 3, 2, 1]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "1\n", "weight": 0.4, "expected": "1", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "0\n", "weight": 0.3, "expected": "0", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 10.00, '2026-07-29 09:40:21.745271+00', true, NULL);
INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (9423, 12168, NULL, NULL, '#include <iostream>
#include <string>
#include <vector>
#include <unordered_map>

int main() {
    std::vector<std::unordered_map<std::string, int>> scopes;
    scopes.push_back({}); // global scope
    
    std::string cmd;
    while (std::cin >> cmd) {
        if (cmd == "PUSH") {
            scopes.push_back({});
        } else if (cmd == "POP") {
            if (scopes.size() > 1) {
                scopes.pop_back();
            }
        } else if (cmd == "SET") {
            std::string var;
            int val;
            std::cin >> var >> val;
            scopes.back()[var] = val;
        } else if (cmd == "GET") {
            std::string var;
            std::cin >> var;
            bool found = false;
            for (int i = static_cast<int>(scopes.size()) - 1; i >= 0; --i) {
                if (scopes[i].count(var)) {
                    std::cout << scopes[i][var] << "\n";
                    found = true;
                    break;
                }
            }
            if (!found) {
                std::cout << "UNDEFINED\n";
            }
        }
    }
    return 0;
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "SET x 10\nPUSH\nSET x 20\nGET x\nPOP\nGET x", "passed": true, "status": "Accepted", "stderr": "", "stdout": "20\n10\n", "weight": 0.3, "expected": "20\n10", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "GET y", "passed": true, "status": "Accepted", "stderr": "", "stdout": "UNDEFINED\n", "weight": 0.4, "expected": "UNDEFINED", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "PUSH\nPOP\nGET z", "passed": true, "status": "Accepted", "stderr": "", "stdout": "UNDEFINED\n", "weight": 0.3, "expected": "UNDEFINED", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Defining main() is strictly forbidden. The system provides its own entry point."}]}}', 10.00, '2026-07-29 09:40:59.749845+00', true, NULL);
