struct Node {
    char data;
    Node* next;
};

bool isListAnagramOf(Node* head, std::string target) {
    std::string listStr = "";
    Node* curr = head;
    while (curr != nullptr) {
        listStr += curr->data;
        curr = curr->next;
    }
