INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (10972, 14701, NULL, NULL, '#include <vector>
#include <string>

bool dfs(std::vector<std::vector<char>>& board, const std::string& word, int r, int c, size_t index) {
    if (index == word.length()) return true;
    if (r < 0 || r >= static_cast<int>(board.size()) || c < 0 || c >= static_cast<int>(board[0].size()) || board[r][c] != word[index]) {
        return false;
    }
    char temp = board[r][c];
    board[r][c] = ''#'';
    bool found = dfs(board, word, r + 1, c, index + 1) ||
                 dfs(board, word, r - 1, c, index + 1) ||
                 dfs(board, word, r, c + 1, index + 1) ||
                 dfs(board, word, r, c - 1, index + 1);
    board[r][c] = temp;
    return found;
}

bool existWord(const std::vector<std::vector<char>>& board, std::string word) {
    if (board.empty() || board[0].empty()) return false;
    auto grid = board;
    for (size_t r = 0; r < grid.size(); ++r) {
        for (size_t c = 0; c < grid[0].size(); ++c) {
            if (dfs(grid, word, static_cast<int>(r), static_cast<int>(c), 0)) {
                return true;
            }
        }
    }
    return false;
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "[[''A'',''B'',''C'',''E''],[''S'',''F'',''C'',''S''],[''A'',''D'',''E'',''E'']], \"ABCCED\"", "passed": true, "status": "Accepted", "stderr": "", "stdout": "true\n", "weight": 0.3, "expected": "true", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[[''A'',''B'']], \"AC\"", "passed": true, "status": "Accepted", "stderr": "", "stdout": "false\n", "weight": 0.4, "expected": "false", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[], \"A\"", "passed": true, "status": "Accepted", "stderr": "", "stdout": "false\n", "weight": 0.3, "expected": "false", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 10.00, '2026-07-30 09:08:44.19267+00', true, NULL);
INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (10973, 14702, NULL, NULL, '#include <vector>

struct Node {
    char data;
    Node* next;
};

bool isPalindromeList(Node* head) {
    std::vector<char> chars;
    Node* curr = head;
    while (curr != nullptr) {
        chars.push_back(curr->data);
        curr = curr->next;
    }
    int left = 0;
    int right = static_cast<int>(chars.size()) - 1;
    while (left < right) {
        if (chars[left] != chars[right]) return false;
        left++;
        right--;
    }
    return true;
