INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (10981, 14710, NULL, NULL, '#include <iostream>

int* filterEvenNumbers(const int* arr, int size, int& newSize) {
    if (arr == nullptr || size <= 0) {
        newSize = 0;
        return nullptr;
    }
    int count = 0;
    for (int i = 0; i < size; ++i) {
        if (arr[i] % 2 == 0) count++;
    }
    newSize = count;
    if (count == 0) return nullptr;

    int* result = new int[count];
    int idx = 0;
    for (int i = 0; i < size; ++i) {
        if (arr[i] % 2 == 0) {
            result[idx++] = arr[i];
        }
    }
    return result;
}', '{"feedback": "Passed 0% of the functional test suites.", "black_box": {"ratio": 0, "test_results": [{"input": "[1, 2, 3, 4, 5], 5", "passed": false, "status": "Wrong Answer", "stderr": "PARSE_ERROR: input line did not match expected parameter types for this signature: [1, 2, 3, 4, 5], 5\n", "stdout": "", "weight": 0.3, "expected": "[2, 4], size=2", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[1, 3, 5], 3", "passed": false, "status": "Wrong Answer", "stderr": "PARSE_ERROR: input line did not match expected parameter types for this signature: [1, 3, 5], 3\n", "stdout": "", "weight": 0.4, "expected": "nullptr, size=0", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "nullptr, 0", "passed": false, "status": "Wrong Answer", "stderr": "PARSE_ERROR: input line did not match expected parameter types for this signature: nullptr, 0\n", "stdout": "", "weight": 0.3, "expected": "nullptr, size=0", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 0, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 0.00, '2026-07-30 09:08:58.317262+00', true, NULL);
INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (9480, 12385, NULL, NULL, '#include <vector>
#include <algorithm>

int longestNonDecreasingRun(const std::vector<int>& nums) {
    if (nums.empty()) return 0;
    int maxLen = 1;
    int currLen = 1;
    for (size_t i = 1; i < nums.size(); ++i) {
        if (nums[i] >= nums[i - 1]) {
            currLen++;
        } else {
            maxLen = std::max(maxLen, currLen);
            currLen = 1;
        }
    }
    return std::max(maxLen, currLen);
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "[1, 2, 2, 1, 3, 4, 5]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "4\n", "weight": 0.3, "expected": "4", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[5, 4, 3, 2, 1]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "1\n", "weight": 0.4, "expected": "1", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "0\n", "weight": 0.3, "expected": "0", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 10.00, '2026-07-29 09:45:54.602281+00', true, NULL);
INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (9461, 12366, NULL, NULL, '#include <vector>

std::vector<std::vector<int>> checkQuadrantSigns(const std::vector<std::vector<int>>& grid) {
    std::vector<std::vector<int>> res;
    for (const auto& point : grid) {
        if (point.size() < 2) continue;
        int x = point[0];
        int y = point[1];
        int q = 0;
        
        if (x > 0 && y > 0) q = 1;
        else if (x < 0 && y > 0) q = 2;
        else if (x < 0 && y < 0) q = 3;
        else if (x > 0 && y < 0) q = 4;
        else q = 0;
        
        res.push_back({q});
    }
    return res;
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "[[1, 2], [-1, -2]]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[[1], [3]]\n", "weight": 0.3, "expected": "[[1], [3]]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[[0, 5], [3, -4]]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[[0], [4]]\n", "weight": 0.4, "expected": "[[0], [4]]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[[-2, 5], [0, 0]]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[[2], [0]]\n", "weight": 0.3, "expected": "[[2], [0]]", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 10.00, '2026-07-29 09:45:24.808235+00', true, NULL);
INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (10982, 14711, NULL, NULL, '#include <iostream>

int** allocateMatrix(int rows, int cols, int initialVal) {
    if (rows <= 0 || cols <= 0) return nullptr;
    int** matrix = new int*[rows];
    for (int r = 0; r < rows; ++r) {
        matrix[r] = new int[cols];
        for (int c = 0; c < cols; ++c) {
            matrix[r][c] = initialVal;
        }
    }
    return matrix;
}

void freeMatrix(int** matrix, int rows) {
    if (matrix == nullptr) return;
    for (int r = 0; r < rows; ++r) {
        delete[] matrix[r];
    }
    delete[] matrix;
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "2, 3, 9", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[[9, 9, 9], [9, 9, 9]]\n", "weight": 0.3, "expected": "[[9, 9, 9], [9, 9, 9]]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "1, 1, 0", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[[0]]\n", "weight": 0.4, "expected": "[[0]]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "0, 0, 0", "passed": true, "status": "Accepted", "stderr": "", "stdout": "nullptr\n", "weight": 0.3, "expected": "nullptr", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 10.00, '2026-07-30 09:08:59.87199+00', true, NULL);
