INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (10988, 14717, NULL, NULL, 'struct Node {
    int data;
    Node* next;
};

Node* deepCopyList(Node* head) {
    if (head == nullptr) return nullptr;
    Node* newHead = new Node{head->data, nullptr};
    Node* currOriginal = head->next;
    Node* currCopy = newHead;

    while (currOriginal != nullptr) {
        currCopy->next = new Node{currOriginal->data, nullptr};
        currCopy = currCopy->next;
        currOriginal = currOriginal->next;
    }
    return newHead;
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "[10, 20, 30]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[10, 20, 30]\n", "weight": 0.3, "expected": "[10, 20, 30]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[5]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[5]\n", "weight": 0.4, "expected": "[5]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[]\n", "weight": 0.3, "expected": "[]", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"name": "Security", "type": "FORBID", "passed": true, "target": "security", "weight": 0, "description": "Security Policy Compliance"}, {"name": "Cyclomatic Complexity", "type": "SCORE", "earned": 30, "passed": true, "target": "complexity", "weight": 30, "description": "Complexity is 3. Penalty applied if > 15.", "actual_value": 3}]}}', 10.00, '2026-07-30 09:09:09.207992+00', true, NULL);
INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (10989, 14718, NULL, NULL, '#include <iostream>
#include <string>
#include <vector>

struct Block {
    int id;
    int size;
};

int main() {
    int poolSize;
    if (std::cin >> poolSize) {
        int remaining = poolSize;
        std::vector<Block> allocs;
        int nextId = 0;
        std::string cmd;
        while (std::cin >> cmd) {
            if (cmd == "ALLOC") {
                int sz;
                std::cin >> sz;
                if (sz <= remaining) {
                    remaining -= sz;
                    allocs.push_back({nextId++, sz});
                    std::cout << remaining << "\n";
                } else {
                    std::cout << "FAIL\n";
                }
            } else if (cmd == "FREE") {
                int targetId;
                std::cin >> targetId;
                for (size_t i = 0; i < allocs.size(); ++i) {
                    if (allocs[i].id == targetId) {
                        remaining += allocs[i].size;
                        allocs.erase(allocs.begin() + i);
                        break;
                    }
                }
                std::cout << remaining << "\n";
            }
        }
