INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (10265, 14006, NULL, NULL, '#include <vector>

int countConnectedRegion(std::vector<std::vector<int>>& grid, int r, int c) {
    if (r < 0 || r >= (int)grid.size() || c < 0 || c >= (int)grid[0].size()) return 0;
    if (grid[r][c] != 1) return 0;
    grid[r][c] = 0;
    return 1 + countConnectedRegion(grid, r + 1, c) +
               countConnectedRegion(grid, r - 1, c) +
               countConnectedRegion(grid, r, c + 1) +
               countConnectedRegion(grid, r, c - 1);
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "[[1, 1, 0], [1, 0, 0], [0, 0, 1]], 0, 0", "passed": true, "status": "Accepted", "stderr": "", "stdout": "3\n", "weight": 0.3, "expected": "3", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[[0, 0], [0, 0]], 0, 0", "passed": true, "status": "Accepted", "stderr": "", "stdout": "0\n", "weight": 0.4, "expected": "0", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[[1]], 0, 0", "passed": true, "status": "Accepted", "stderr": "", "stdout": "1\n", "weight": 0.3, "expected": "1", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 10.00, '2026-07-29 11:48:52.915461+00', true, NULL);
INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (10268, 14009, NULL, NULL, '#include <iostream>

int ackermann(int m, int n) {
    if (m == 0) return n + 1;
    if (m > 0 && n == 0) return ackermann(m - 1, 1);
