    }
    return res;
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "[[1, 2], [-1, -2]]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[[1], [3]]\n", "weight": 0.3, "expected": "[[1], [3]]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[[0, 5], [3, -4]]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[[0], [4]]\n", "weight": 0.4, "expected": "[[0], [4]]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[[-2, 5], [0, 0]]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[[2], [0]]\n", "weight": 0.3, "expected": "[[2], [0]]", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 10.00, '2026-07-29 10:13:59.196232+00', true, NULL);
