INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (9458, 12274, NULL, NULL, '#include <iostream>

double computePower(double base, int exponent = 2) {
    double result = 1.0;
    int p = (exponent < 0) ? -exponent : exponent;
    for (int i = 0; i < p; ++i) {
        result *= base;
    }
