INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (9455, 12271, NULL, NULL, '#include <vector>

std::vector<int> spiralTraversal(const std::vector<std::vector<int>>& matrix) {
    if (matrix.empty() || matrix[0].empty()) return {};
    int top = 0, bottom = matrix.size() - 1;
    int left = 0, right = matrix[0].size() - 1;
    std::vector<int> result;

    while (top <= bottom && left <= right) {
        for (int c = left; c <= right; ++c) result.push_back(matrix[top][c]);
        top++;
        for (int r = top; r <= bottom; ++r) result.push_back(matrix[r][right]);
        right--;

        if (top <= bottom) {
            for (int c = right; c >= left; --c) result.push_back(matrix[bottom][c]);
            bottom--;
        }
        if (left <= right) {
            for (int r = bottom; r >= top; --r) result.push_back(matrix[r][left]);
            left++;
        }
    }
    return result;
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "[[1, 2, 3], [4, 5, 6], [7, 8, 9]]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[1, 2, 3, 6, 9, 8, 7, 4, 5]\n", "weight": 0.3, "expected": "[1, 2, 3, 6, 9, 8, 7, 4, 5]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[[1]]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[1]\n", "weight": 0.4, "expected": "[1]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[]\n", "weight": 0.3, "expected": "[]", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 10.00, '2026-07-29 09:44:43.248721+00', true, NULL);
