    if ((flags & mask) == mask) {
        if (flags & (1 << trigger)) {
            return flags ^ mask;
        } else {
            return flags | mask;
        }
    } else {
        return ~flags;
    }
}
', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "7 3 1", "passed": true, "status": "Accepted", "stderr": "", "stdout": "4\n", "weight": 0.3, "expected": "4", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "5 1 2", "passed": true, "status": "Accepted", "stderr": "", "stdout": "4\n", "weight": 0.4, "expected": "4", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "0 1 0", "passed": true, "status": "Accepted", "stderr": "", "stdout": "-1\n", "weight": 0.3, "expected": "-1", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"name": "Security", "type": "FORBID", "passed": true, "target": "security", "weight": 0, "description": "Security Policy Compliance"}, {"name": "Cyclomatic Complexity", "type": "SCORE", "earned": 30, "passed": true, "target": "complexity", "weight": 30, "description": "Complexity is 3. Penalty applied if > 15.", "actual_value": 3}]}}', 10.00, '2026-07-31 06:52:21.595719+00', true, NULL);
