INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (9608, 12775, NULL, NULL, '#include <string>
#include <sstream>
#include <algorithm>

std::string reverseWords(const std::string& sentence) {
    if (sentence.empty()) return "";
    std::stringstream ss(sentence);
    std::string word;
    std::string result = "";
    bool first = true;
    while (ss >> word) {
        std::reverse(word.begin(), word.end());
        if (!first) result += " ";
        result += word;
        first = false;
    }
    return result;
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "\"Hello World\"", "passed": true, "status": "Accepted", "stderr": "", "stdout": "\"olleH dlroW\"\n", "weight": 0.3, "expected": "\"olleH dlroW\"", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "\"a b c\"", "passed": true, "status": "Accepted", "stderr": "", "stdout": "\"a b c\"\n", "weight": 0.4, "expected": "\"a b c\"", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "\"\"", "passed": true, "status": "Accepted", "stderr": "", "stdout": "\"\"\n", "weight": 0.3, "expected": "\"\"", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 10.00, '2026-07-29 10:13:09.150732+00', true, NULL);
INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (9609, 12776, NULL, NULL, '#include <vector>
#include <string>

std::vector<std::string> transposeCharGrid(const std::vector<std::string>& grid) {
    if (grid.empty() || grid[0].empty()) return {};
    size_t rows = grid.size();
    size_t cols = grid[0].length();
    std::vector<std::string> transposed(cols, std::string(rows, '' ''));
    for (size_t r = 0; r < rows; ++r) {
        for (size_t c = 0; c < cols; ++c) {
            transposed[c][r] = grid[r][c];
        }
    }
    return transposed;
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "[\"abc\", \"def\"]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[\"ad\", \"be\", \"cf\"]\n", "weight": 0.3, "expected": "[\"ad\", \"be\", \"cf\"]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[\"x\"]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[\"x\"]\n", "weight": 0.4, "expected": "[\"x\"]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[]\n", "weight": 0.3, "expected": "[]", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 10.00, '2026-07-29 10:13:10.718948+00', true, NULL);
INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (9610, 12777, NULL, NULL, '#include <string>
#include <vector>
#include <algorithm>

struct Node {
    char data;
    Node* next;
};

bool isListAnagramOf(Node* head, std::string target) {
    std::string listStr = "";
    Node* curr = head;
    while (curr != nullptr) {
        listStr += curr->data;
        curr = curr->next;
    }
    if (listStr.length() != target.length()) return false;
    std::sort(listStr.begin(), listStr.end());
    std::sort(target.begin(), target.end());
    return listStr == target;
}', '{"feedback": "Passed 30% of the functional test suites.", "black_box": {"ratio": 0.3, "test_results": [{"input": "[''l'', ''i'', ''s'', ''t''], \"silent\"", "passed": false, "status": "Wrong Answer", "stderr": "PARSE_ERROR: input line did not match expected parameter types for this signature: [''l'', ''i'', ''s'', ''t''], \"silent\"\n", "stdout": "", "weight": 0.3, "expected": "false", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[''c'', ''a'', ''t''], \"act\"", "passed": false, "status": "Wrong Answer", "stderr": "PARSE_ERROR: input line did not match expected parameter types for this signature: [''c'', ''a'', ''t''], \"act\"\n", "stdout": "", "weight": 0.4, "expected": "true", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[], \"\"", "passed": true, "status": "Accepted", "stderr": "", "stdout": "true\n", "weight": 0.3, "expected": "true", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 0.3, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 3.00, '2026-07-29 10:13:12.279091+00', true, NULL);
