    }
    return result;
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "[1, 2, 3]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "\"1->2->3\"\n", "weight": 0.3, "expected": "\"1->2->3\"", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[42]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "\"42\"\n", "weight": 0.4, "expected": "\"42\"", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "\"\"\n", "weight": 0.3, "expected": "\"\"", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 10.00, '2026-07-29 10:23:56.056872+00', true, NULL);
