INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (9716, 13030, NULL, NULL, '#include <iostream>

int* filterEvenNumbers(const int* arr, int size, int& newSize) {
    if (arr == nullptr || size <= 0) {
        newSize = 0;
        return nullptr;
    }
    int count = 0;
    for (int i = 0; i < size; ++i) {
        if (arr[i] % 2 == 0) count++;
    }
    newSize = count;
    if (count == 0) return nullptr;

    int* result = new int[count];
    int idx = 0;
    for (int i = 0; i < size; ++i) {
        if (arr[i] % 2 == 0) {
            result[idx++] = arr[i];
        }
    }
    return result;
}', '{"feedback": "Passed 0% of the functional test suites.", "black_box": {"ratio": 0, "test_results": [{"input": "[1, 2, 3, 4, 5], 5", "passed": false, "status": "Wrong Answer", "stderr": "PARSE_ERROR: input line did not match expected parameter types for this signature: [1, 2, 3, 4, 5], 5\n", "stdout": "", "weight": 0.3, "expected": "[2, 4], size=2", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[1, 3, 5], 3", "passed": false, "status": "Wrong Answer", "stderr": "PARSE_ERROR: input line did not match expected parameter types for this signature: [1, 3, 5], 3\n", "stdout": "", "weight": 0.4, "expected": "nullptr, size=0", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "nullptr, 0", "passed": false, "status": "Wrong Answer", "stderr": "PARSE_ERROR: input line did not match expected parameter types for this signature: nullptr, 0\n", "stdout": "", "weight": 0.3, "expected": "nullptr, size=0", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 0, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 0.00, '2026-07-29 10:24:38.795817+00', true, NULL);
