    }
    return 0;
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "29 2 2024", "passed": true, "status": "Accepted", "stderr": "", "stdout": "VALID", "weight": 0.3, "expected": "VALID", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "29 2 2023", "passed": true, "status": "Accepted", "stderr": "", "stdout": "INVALID", "weight": 0.4, "expected": "INVALID", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "31 4 2020", "passed": true, "status": "Accepted", "stderr": "", "stdout": "INVALID", "weight": 0.3, "expected": "INVALID", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Defining main() is strictly forbidden. The system provides its own entry point."}]}}', 10.00, '2026-07-29 11:38:39.573815+00', true, NULL);
INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (10282, 14025, NULL, NULL, '#include <iostream>
#include <algorithm>

class IntVector {
private:
    int* data;
    size_t sz;
    size_t cap;
public:
    IntVector() : data(nullptr), sz(0), cap(0) {}
    ~IntVector() { delete[] data; }
    
    IntVector(const IntVector& other) : sz(other.sz), cap(other.cap) {
        data = new int[cap];
        for (size_t i = 0; i < sz; ++i) data[i] = other.data[i];
    }
    
    IntVector& operator=(const IntVector& other) {
        if (this != &other) {
            delete[] data;
            sz = other.sz;
            cap = other.cap;
            data = new int[cap];
            for (size_t i = 0; i < sz; ++i) data[i] = other.data[i];
        }
        return *this;
    }
    
    IntVector(IntVector&& other) noexcept : data(other.data), sz(other.sz), cap(other.cap) {
        other.data = nullptr;
        other.sz = 0;
        other.cap = 0;
    }
    
    IntVector& operator=(IntVector&& other) noexcept {
        if (this != &other) {
            delete[] data;
            data = other.data;
            sz = other.sz;
            cap = other.cap;
            other.data = nullptr;
            other.sz = 0;
            other.cap = 0;
        }
        return *this;
    }
    
    void push_back(int val) {
        if (sz == cap) {
            size_t newCap = cap == 0 ? 1 : cap * 2;
            int* newData = new int[newCap];
            for (size_t i = 0; i < sz; ++i) newData[i] = data[i];
            delete[] data;
            data = newData;
            cap = newCap;
        }
        data[sz++] = val;
    }
    size_t size() const { return sz; }
};', '{"feedback": "Passed 0% of the functional test suites.", "black_box": {"ratio": 0, "test_results": [{"input": "push 1, 2, move assign", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "", "weight": 0.3, "expected": "[1, 2]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "copy construct", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "", "weight": 0.4, "expected": "deep copy verified", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "empty vector move", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "", "weight": 0.3, "expected": "size 0", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 0, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 0.00, '2026-07-29 11:56:02.381159+00', true, NULL);
INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (10285, 14028, NULL, NULL, '#include <iostream>
#include <string>
#include <unordered_map>
#include <memory>

class Plugin {
public:
    virtual int execute(int val) = 0;
    virtual ~Plugin() = default;
};

class AddPlugin : public Plugin {
private:
    int total = 0;
public:
    int execute(int val) override {
        total += val;
        return total;
    }
};

class MultPlugin : public Plugin {
private:
    int total = 1;
public:
    int execute(int val) override {
        total *= val;
        return total;
    }
};

int main() {
    std::unordered_map<int, std::unique_ptr<Plugin>> plugins;
    std::string cmd;
    while (std::cin >> cmd) {
        if (cmd == "CREATE") {
            std::string type;
            int id;
            std::cin >> type >> id;
            if (type == "Add") plugins[id] = std::make_unique<AddPlugin>();
            else if (type == "Mult") plugins[id] = std::make_unique<MultPlugin>();
        } else if (cmd == "EXEC") {
            int id, val;
            std::cin >> id >> val;
            if (plugins.count(id)) {
                std::cout << plugins[id]->execute(val) << "\n";
            } else {
                std::cout << "NOT_FOUND\n";
            }
        }
    }
    return 0;
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "CREATE Add 1\nEXEC 1 10\nEXEC 1 20", "passed": true, "status": "Accepted", "stderr": "", "stdout": "10\n30\n", "weight": 0.3, "expected": "10\n30", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "EXEC 99 5", "passed": true, "status": "Accepted", "stderr": "", "stdout": "NOT_FOUND\n", "weight": 0.4, "expected": "NOT_FOUND", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "CREATE Mult 2\nEXEC 2 0", "passed": true, "status": "Accepted", "stderr": "", "stdout": "0\n", "weight": 0.3, "expected": "0", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Defining main() is strictly forbidden. The system provides its own entry point."}]}}', 10.00, '2026-07-29 11:57:02.384677+00', true, NULL);
