int countCollatzSteps(int n) {
    long long val = n;
    int steps = 0;
    while (val > 1) {
        if (val % 2 == 0) {
            val /= 2;
        } else {
            val = 3 * val + 1;
        }
        steps++;
    }
    return steps;
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "6", "passed": true, "status": "Accepted", "stderr": "", "stdout": "8\n", "weight": 0.3, "expected": "8", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "1", "passed": true, "status": "Accepted", "stderr": "", "stdout": "0\n", "weight": 0.4, "expected": "0", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "27", "passed": true, "status": "Accepted", "stderr": "", "stdout": "111\n", "weight": 0.3, "expected": "111", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 10.00, '2026-07-29 11:39:28.668289+00', true, NULL);
INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (10204, 13945, NULL, NULL, '#include <vector>
#include <algorithm>

int longestNonDecreasingRun(const std::vector<int>& nums) {
    if (nums.empty()) return 0;
    int maxLen = 1;
    int currLen = 1;
    for (size_t i = 1; i < nums.size(); ++i) {
        if (nums[i] >= nums[i - 1]) {
            currLen++;
        } else {
            maxLen = std::max(maxLen, currLen);
            currLen = 1;
        }
    }
    return std::max(maxLen, currLen);
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "[1, 2, 2, 1, 3, 4, 5]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "4\n", "weight": 0.3, "expected": "4", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[5, 4, 3, 2, 1]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "1\n", "weight": 0.4, "expected": "1", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "0\n", "weight": 0.3, "expected": "0", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 10.00, '2026-07-29 11:39:32.278699+00', true, NULL);
