struct Block {
    int id;
    int size;
};

int main() {
    int poolSize;
    if (std::cin >> poolSize) {
        int remaining = poolSize;
        std::vector<Block> allocs;
        int nextId = 0;
        std::string cmd;
        while (std::cin >> cmd) {
            if (cmd == "ALLOC") {
                int sz;
                std::cin >> sz;
                if (sz <= remaining) {
                    remaining -= sz;
                    allocs.push_back({nextId++, sz});
                    std::cout << remaining << "\n";
                } else {
                    std::cout << "FAIL\n";
                }
            } else if (cmd == "FREE") {
                int targetId;
                std::cin >> targetId;
                for (size_t i = 0; i < allocs.size(); ++i) {
                    if (allocs[i].id == targetId) {
                        remaining += allocs[i].size;
                        allocs.erase(allocs.begin() + i);
                        break;
                    }
                }
                std::cout << remaining << "\n";
            }
        }
    }
    return 0;
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "1000\nALLOC 200\nALLOC 300\nFREE 0", "passed": true, "status": "Accepted", "stderr": "", "stdout": "800\n500\n700\n", "weight": 0.3, "expected": "800\n500\n700", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "500\nALLOC 600", "passed": true, "status": "Accepted", "stderr": "", "stdout": "FAIL\n", "weight": 0.4, "expected": "FAIL", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "100\nALLOC 100", "passed": true, "status": "Accepted", "stderr": "", "stdout": "0\n", "weight": 0.3, "expected": "0", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Defining main() is strictly forbidden. The system provides its own entry point."}]}}', 10.00, '2026-07-29 11:46:53.5216+00', true, NULL);
