    return sumSingleRow(grid[row]) + recursiveGridRowSum(grid, row + 1);
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "[[1, 2], [3, 4]], 0", "passed": true, "status": "Accepted", "stderr": "", "stdout": "10\n", "weight": 0.3, "expected": "10", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[[10]], 0", "passed": true, "status": "Accepted", "stderr": "", "stdout": "10\n", "weight": 0.4, "expected": "10", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[], 0", "passed": true, "status": "Accepted", "stderr": "", "stdout": "0\n", "weight": 0.3, "expected": "0", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 10.00, '2026-07-29 11:47:32.242394+00', true, NULL);
