INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (10270, 14011, NULL, NULL, '#include <vector>

bool hasPath(const std::vector<std::vector<int>>& grid, int r, int c) {
    int rows = grid.size();
    if (rows == 0) return false;
    int cols = grid[0].size();
    if (r < 0 || r >= rows || c < 0 || c >= cols) return false;
    if (grid[r][c] == 1) return false;
    if (r == rows - 1 && c == cols - 1) return true;
    
    std::vector<std::vector<bool>> visited(rows, std::vector<bool>(cols, false));
    auto dfs = [&](auto& self, int cr, int cc) -> bool {
        if (cr < 0 || cr >= rows || cc < 0 || cc >= cols) return false;
        if (grid[cr][cc] == 1 || visited[cr][cc]) return false;
        if (cr == rows - 1 && cc == cols - 1) return true;
        visited[cr][cc] = true;
        return self(self, cr + 1, cc) || self(self, cr - 1, cc) ||
               self(self, cr, cc + 1) || self(self, cr, cc - 1);
    };
    return dfs(dfs, r, c);
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "[[0, 0, 1], [1, 0, 1], [1, 0, 0]], 0, 0", "passed": true, "status": "Accepted", "stderr": "", "stdout": "true\n", "weight": 0.3, "expected": "true", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[[0, 1], [1, 0]], 0, 0", "passed": true, "status": "Accepted", "stderr": "", "stdout": "false\n", "weight": 0.4, "expected": "false", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[[0]], 0, 0", "passed": true, "status": "Accepted", "stderr": "", "stdout": "true\n", "weight": 0.3, "expected": "true", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 10.00, '2026-07-29 11:50:17.260543+00', true, NULL);
INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (10271, 14012, NULL, NULL, 'struct Node {
    int data;
    Node* next;
};

Node* mergeSortedListsRecursive(Node* l1, Node* l2) {
    if (l1 == nullptr) return l2;
    if (l2 == nullptr) return l1;
    if (l1->data <= l2->data) {
        l1->next = mergeSortedListsRecursive(l1->next, l2);
        return l1;
    } else {
        l2->next = mergeSortedListsRecursive(l1, l2->next);
        return l2;
    }
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "[1, 3, 5], [2, 4, 6]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[1, 2, 3, 4, 5, 6]\n", "weight": 0.3, "expected": "[1, 2, 3, 4, 5, 6]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[], [1, 2]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[1, 2]\n", "weight": 0.4, "expected": "[1, 2]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[], []", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[]\n", "weight": 0.3, "expected": "[]", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"name": "Security", "type": "FORBID", "passed": true, "target": "security", "weight": 0, "description": "Security Policy Compliance"}, {"name": "Cyclomatic Complexity", "type": "SCORE", "earned": 30, "passed": true, "target": "complexity", "weight": 30, "description": "Complexity is 4. Penalty applied if > 15.", "actual_value": 4}]}}', 10.00, '2026-07-29 11:50:34.070232+00', true, NULL);
INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (10272, 14013, NULL, NULL, '#include <iostream>
#include <vector>

void solveNQueens(int row, int n, std::vector<int>& cols, std::vector<int>& diag1, std::vector<int>& diag2, int& count) {
    if (row == n) {
        count++;
        return;
    }
    for (int col = 0; col < n; ++col) {
        if (cols[col] || diag1[row + col] || diag2[row - col + n - 1]) continue;
        cols[col] = diag1[row + col] = diag2[row - col + n - 1] = 1;
        solveNQueens(row + 1, n, cols, diag1, diag2, count);
        cols[col] = diag1[row + col] = diag2[row - col + n - 1] = 0;
    }
}

int main() {
    int n;
    if (std::cin >> n && n > 0) {
        int count = 0;
        std::vector<int> cols(n, 0), diag1(2 * n, 0), diag2(2 * n, 0);
        solveNQueens(0, n, cols, diag1, diag2, count);
        std::cout << count;
    }
