std::vector<int> classifySigns(const std::vector<int>& numbers) {
    std::vector<int> result;
    result.reserve(numbers.size());
    for (int num : numbers) {
        if (num > 0) result.push_back(1);
        else if (num < 0) result.push_back(-1);
        else result.push_back(0);
    }
    return result;
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "[10, -5, 0]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[1, -1, 0]\n", "weight": 0.3, "expected": "[1, -1, 0]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[-1, -2, -3]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[-1, -1, -1]\n", "weight": 0.4, "expected": "[-1, -1, -1]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[]\n", "weight": 0.3, "expected": "[]", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 10.00, '2026-07-30 09:14:30.108522+00', true, NULL);
INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (11055, 14886, NULL, NULL, '#include <vector>

std::vector<std::vector<int>> checkQuadrantSigns(const std::vector<std::vector<int>>& grid) {
    std::vector<std::vector<int>> res;
    for (const auto& point : grid) {
        if (point.size() < 2) continue;
        int x = point[0];
        int y = point[1];
        int q = 0;
        
        if (x > 0 && y > 0) q = 1;
        else if (x < 0 && y > 0) q = 2;
        else if (x < 0 && y < 0) q = 3;
        else if (x > 0 && y < 0) q = 4;
        else q = 0;
        
        res.push_back({q});
    }
    return res;
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "[[1, 2], [-1, -2]]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[[1], [3]]\n", "weight": 0.3, "expected": "[[1], [3]]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[[0, 5], [3, -4]]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[[0], [4]]\n", "weight": 0.4, "expected": "[[0], [4]]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[[-2, 5], [0, 0]]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[[2], [0]]\n", "weight": 0.3, "expected": "[[2], [0]]", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 10.00, '2026-07-30 09:14:31.668292+00', true, NULL);
