int countCollatzSteps(int n) {
    long long val = n;
    int steps = 0;
    while (val > 1) {
        if (val % 2 == 0) {
            val /= 2;
        } else {
            val = 3 * val + 1;
        }
        steps++;
    }
    return steps;
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "6", "passed": true, "status": "Accepted", "stderr": "", "stdout": "8\n", "weight": 0.3, "expected": "8", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "1", "passed": true, "status": "Accepted", "stderr": "", "stdout": "0\n", "weight": 0.4, "expected": "0", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "27", "passed": true, "status": "Accepted", "stderr": "", "stdout": "111\n", "weight": 0.3, "expected": "111", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 10.00, '2026-07-29 10:37:53.298046+00', true, NULL);
