    Node* next;
};

void splitListBySign(Node* source, Node*& posHead, Node*& negHead) {
    posHead = nullptr;
    negHead = nullptr;
    Node* posTail = nullptr;
    Node* negTail = nullptr;

    Node* curr = source;
    while (curr != nullptr) {
        Node* newNode = new Node{curr->data, nullptr};
        if (curr->data >= 0) {
            if (!posHead) posHead = posTail = newNode;
            else { posTail->next = newNode; posTail = newNode; }
        } else {
            if (!negHead) negHead = negTail = newNode;
            else { negTail->next = newNode; negTail = newNode; }
        }
        curr = curr->next;
    }
}', '{"feedback": "Compilation failed. Syntactic grace awarded (100.0% AST Health).", "black_box": {"ratio": 0.15, "test_results": [{"input": "[1, -2, 3, -4]", "passed": false, "status": "Compilation Error", "stderr": "", "stdout": "", "weight": 1, "expected": "([1, 3], [-2, -4])", "is_public": true, "memory_leak": false, "compile_output": "main.cpp: In function ‘int main()’:\nmain.cpp:324:49: error: too few arguments to function ‘void splitListBySign(Node*, Node*&, Node*&)’\n  324 |             formatValue(cout, splitListBySign(v0));\n      |                                                 ^\nmain.cpp:241:6: note: declared here\n  241 | void splitListBySign(Node* source, Node*& posHead, Node*& negHead) {\n      |      ^~~~~~~~~~~~~~~\n"}, {"input": "[1, 2, 3]", "passed": false, "status": "Compilation Error", "stderr": "", "stdout": "", "weight": 1, "expected": "([1, 2, 3], [])", "is_public": true, "memory_leak": false, "compile_output": "main.cpp: In function ‘int main()’:\nmain.cpp:324:49: error: too few arguments to function ‘void splitListBySign(Node*, Node*&, Node*&)’\n  324 |             formatValue(cout, splitListBySign(v0));\n      |                                                 ^\nmain.cpp:241:6: note: declared here\n  241 | void splitListBySign(Node* source, Node*& posHead, Node*& negHead) {\n      |      ^~~~~~~~~~~~~~~\n"}, {"input": "[]", "passed": false, "status": "Compilation Error", "stderr": "", "stdout": "", "weight": 1, "expected": "([], [])", "is_public": true, "memory_leak": false, "compile_output": "main.cpp: In function ‘int main()’:\nmain.cpp:324:49: error: too few arguments to function ‘void splitListBySign(Node*, Node*&, Node*&)’\n  324 |             formatValue(cout, splitListBySign(v0));\n      |                                                 ^\nmain.cpp:241:6: note: declared here\n  241 | void splitListBySign(Node* source, Node*& posHead, Node*& negHead) {\n      |      ^~~~~~~~~~~~~~~\n"}]}, "white_box": {"ratio": 0.15, "details": [{