INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (11092, 14923, NULL, NULL, '#include <iostream>
#include <iomanip>
#include <algorithm>

int main() {
    int n;
    if (std::cin >> n && n > 0) {
        long long sum = 0;
        int minVal = 0, maxVal = 0;
        for (int i = 1; i <= n; ++i) {
            int val;
            std::cin >> val;
            if (i == 1) {
                minVal = maxVal = val;
            } else {
                minVal = std::min(minVal, val);
                maxVal = std::max(maxVal, val);
            }
            sum += val;
            double avg = static_cast<double>(sum) / i;
            std::cout << "min:" << minVal << " max:" << maxVal << " avg:" << std::fixed << std::setprecision(1) << avg << "\n";
        }
