INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (11992, 16008, NULL, NULL, '#include <iostream>
#include <string>
#include <vector>
#include <unordered_map>

int main() {
    std::vector<std::unordered_map<std::string, int>> scopes;
    scopes.push_back({}); // global scope
    
    std::string cmd;
    while (std::cin >> cmd) {
        if (cmd == "PUSH") {
            scopes.push_back({});
        } else if (cmd == "POP") {
            if (scopes.size() > 1) {
                scopes.pop_back();
            }
        } else if (cmd == "SET") {
            std::string var;
            int val;
            std::cin >> var >> val;
            scopes.back()[var] = val;
        } else if (cmd == "GET") {
            std::string var;
            std::cin >> var;
            bool found = false;
            for (int i = static_cast<int>(scopes.size()) - 1; i >= 0; --i) {
                if (scopes[i].count(var)) {
                    std::cout << scopes[i][var] << "\n";
                    found = true;
                    break;
                }
            }
            if (!found) {
                std::cout << "UNDEFINED\n";
            }
        }
    }
    return 0;
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "SET x 10\nPUSH\nSET x 20\nGET x\nPOP\nGET x", "passed": true, "status": "Accepted", "stderr": "", "stdout": "20\n10\n", "weight": 0.3, "expected": "20\n10", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "GET y", "passed": true, "status": "Accepted", "stderr": "", "stdout": "UNDEFINED\n", "weight": 0.4, "expected": "UNDEFINED", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "PUSH\nPOP\nGET z", "passed": true, "status": "Accepted", "stderr": "", "stdout": "UNDEFINED\n", "weight": 0.3, "expected": "UNDEFINED", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Defining main() is strictly forbidden. The system provides its own entry point."}]}}', 10.00, '2026-07-31 06:53:18.543312+00', true, NULL);
