void processPipeline(std::vector<int>& data, int index = 0) {
    if (index >= static_cast<int>(data.size())) return;
    if (index % 2 == 0) {
        data[index] *= 2;
    } else {
        data[index] *= -1;
    }
    processPipeline(data, index + 1);
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "[1, 2, 3, 4]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[2, -2, 6, -4]\n", "weight": 0.3, "expected": "[2, -2, 6, -4]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[5]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[10]\n", "weight": 0.4, "expected": "[10]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[]\n", "weight": 0.3, "expected": "[]", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 10.00, '2026-07-31 10:02:11.401029+00', true, NULL);
