INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (13249, 17454, NULL, NULL, '#include <string>

int calculateCompressedLength(const std::string& s) {
    if (s.empty()) return 0;
    int compressedLength = 0;
    int count = 1;
    for (size_t i = 1; i < s.length(); ++i) {
        if (s[i] == s[i - 1]) {
            count++;
        } else {
            compressedLength += 1 + std::to_string(count).length();
            count = 1;
        }
    }
