}', '{"feedback": "Passed 40% of the functional test suites.", "black_box": {"ratio": 0.4, "test_results": [{"input": "\"hello world\", pos 0 to 5", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "", "weight": 0.3, "expected": "\"hello\"", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "\"cpp\", pos 1 to 1", "passed": true, "status": "Accepted", "stderr": "", "stdout": "", "weight": 0.4, "expected": "\"\"", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "nullptr, nullptr", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "", "weight": 0.3, "expected": "nullptr", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 0.4, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 4.00, '2026-07-31 10:03:01.788139+00', true, NULL);
