#include <iostream>

int calculateDigitalRoot(long long n) {
  int res = 0;
  while (n > 0 || res > 9){
 
    if (n == 0){
      n = res;
      res = 0;
    }
 
    res += n % 10;
    n /= 10;
  }
  return res;
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "9875", "passed": true, "status": "Accepted", "stderr": "", "stdout": "2\n", "weight": 0.3, "expected": "2", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "0", "passed": true, "status": "Accepted", "stderr": "", "stdout": "0\n", "weight": 0.4, "expected": "0", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "999999999999", "passed": true, "status": "Accepted", "stderr": "", "stdout": "9\n", "weight": 0.3, "expected": "9", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 10.00, '2026-07-30 09:27:35.792389+00', true, NULL);
