INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (11134, 15034, NULL, NULL, '#include <iostream>

double computePower(double base, int exponent = 2) {
    double result = 1.0;
    int p = (exponent < 0) ? -exponent : exponent;
    for (int i = 0; i < p; ++i) {
        result *= base;
    }
    if (exponent < 0) return 1.0 / result;
    return result;
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "3.0, 3", "passed": true, "status": "Accepted", "stderr": "", "stdout": "27.0\n", "weight": 0.3, "expected": "27.0", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "5.0, 0", "passed": true, "status": "Accepted", "stderr": "", "stdout": "1.0\n", "weight": 0.4, "expected": "1.0", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "2.0, 1", "passed": true, "status": "Accepted", "stderr": "", "stdout": "2.0\n", "weight": 0.3, "expected": "2.0", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 10.00, '2026-07-30 09:27:43.577993+00', true, NULL);
