INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (11050, 14817, NULL, NULL, '#include <string>
#include <vector>
#include <algorithm>

struct Node {
    char data;
    Node* next;
};

bool isListAnagramOf(Node* head, std::string target) {
    std::string listStr = "";
    Node* curr = head;
    while (curr != nullptr) {
        listStr += curr->data;
        curr = curr->next;
    }
    if (listStr.length() != target.length()) return false;
    std::sort(listStr.begin(), listStr.end());
    std::sort(target.begin(), target.end());
    return listStr == target;
}', '{"feedback": "Passed 30% of the functional test suites.", "black_box": {"ratio": 0.3, "test_results": [{"input": "[''l'', ''i'', ''s'', ''t''], \"silent\"", "passed": false, "status": "Wrong Answer", "stderr": "PARSE_ERROR: input line did not match expected parameter types for this signature: [''l'', ''i'', ''s'', ''t''], \"silent\"\n", "stdout": "", "weight": 0.3, "expected": "false", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[''c'', ''a'', ''t''], \"act\"", "passed": false, "status": "Wrong Answer", "stderr": "PARSE_ERROR: input line did not match expected parameter types for this signature: [''c'', ''a'', ''t''], \"act\"\n", "stdout": "", "weight": 0.4, "expected": "true", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[], \"\"", "passed": true, "status": "Accepted", "stderr": "", "stdout": "true\n", "weight": 0.3, "expected": "true", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 0.3, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 3.00, '2026-07-30 09:11:39.24139+00', true, NULL);
