INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (11018, 14785, NULL, NULL, '#include <vector>
#include <algorithm>

int longestNonDecreasingRun(const std::vector<int>& nums) {
    if (nums.empty()) return 0;
    int maxLen = 1;
    int currLen = 1;
    for (size_t i = 1; i < nums.size(); ++i) {
        if (nums[i] >= nums[i - 1]) {
            currLen++;
        } else {
            maxLen = std::max(maxLen, currLen);
            currLen = 1;
        }
    }
    return std::max(maxLen, currLen);
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "[1, 2, 2, 1, 3, 4, 5]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "4\n", "weight": 0.3, "expected": "4", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[5, 4, 3, 2, 1]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "1\n", "weight": 0.4, "expected": "1", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "0\n", "weight": 0.3, "expected": "0", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 10.00, '2026-07-30 09:10:47.281179+00', true, NULL);
INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (11019, 14786, NULL, NULL, '#include <vector>                                                                      
                                                                                                     
std::vector<int> computeRowAlternatingSums(const std::vector<std::vector<int>>& grid) {
  std::vector<int> res;                                                              
  for (size_t r = 0; r < grid.size(); ++r) {                                         
    int sum = 0;                                                                   
    for (size_t c = 0; c < grid[r].size(); ++c) {                                  
      if (c % 2 == 0){
        sum += grid[r][c];
      }
      else {								      
        sum -= grid[r][c]; 						      
      }                                         				      
    }                                                                             
    res.push_back(sum);                                                            
  }                                                                                  
  return res;                                                                        
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "[[1, 2, 3], [4, 5, 6]]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[2, 5]\n", "weight": 0.5, "expected": "[2, 5]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[[10]]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[10]\n", "weight": 0.5, "expected": "[10]", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 10.00, '2026-07-30 09:10:48.827386+00', true, NULL);
