INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (13271, 17476, NULL, NULL, '#include <iostream>

int* flattenRawMatrix(int** matrix, int rows, int cols) {
    if (matrix == nullptr || rows <= 0 || cols <= 0) return nullptr;
    int* flat = new int[rows * cols];
    int idx = 0;
    for (int r = 0; r < rows; ++r) {
        if (matrix[r] == nullptr) continue;
        for (int c = 0; c < cols; ++c) {
            flat[idx++] = matrix[r][c];
        }
    }
    return flat;
}', '{"feedback": "Passed 70% of the functional test suites.", "black_box": {"ratio": 0.7, "test_results": [{"input": "[[1, 2], [3, 4]], 2, 2", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "[1, 2]\n", "weight": 0.3, "expected": "[1, 2, 3, 4]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[[5]], 1, 1", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[5]\n", "weight": 0.4, "expected": "[5]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "nullptr, 0, 0", "passed": true, "status": "Accepted", "stderr": "", "stdout": "nullptr\n", "weight": 0.3, "expected": "nullptr", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 0.7, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 7.00, '2026-07-31 10:03:03.46634+00', true, NULL);
