#include <string>

class Cell {
public:
    virtual ~Cell() = default;
    virtual char render() const = 0;
};

class WallCell : public Cell {
public:
    char render() const override { return ''#''; }
};

class EmptyCell : public Cell {
public:
    char render() const override { return ''.''; }
};

class ItemCell : public Cell {
