INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (11923, 15865, NULL, NULL, '#include <vector>
#include <algorithm>

int longestNonDecreasingRun(const std::vector<int>& nums) {
    if (nums.empty()) return 0;
    int maxLen = 1;
    int currLen = 1;
    for (size_t i = 1; i < nums.size(); ++i) {
        if (nums[i] >= nums[i - 1]) {
            currLen++;
        } else {
            maxLen = std::max(maxLen, currLen);
            currLen = 1;
        }
    }
    return std::max(maxLen, currLen);
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "[1, 2, 2, 1, 3, 4, 5]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "4\n", "weight": 0.3, "expected": "4", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[5, 4, 3, 2, 1]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "1\n", "weight": 0.4, "expected": "1", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "0\n", "weight": 0.3, "expected": "0", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 10.00, '2026-07-31 06:46:48.445446+00', true, NULL);
INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (11924, 15866, NULL, NULL, '#include <vector>                                                                      
                                                                                                     
std::vector<int> computeRowAlternatingSums(const std::vector<std::vector<int>>& grid) {
  std::vector<int> res;                                                              
  for (size_t r = 0; r < grid.size(); ++r) {                                         
    int sum = 0;                                                                   
    for (size_t c = 0; c < grid[r].size(); ++c) {                                  
      if (c % 2 == 0){
        sum += grid[r][c];
      }
      else {								      
        sum -= grid[r][c]; 						      
      }                                         				      
    }                                                                             
    res.push_back(sum);                                                            
  }                                                                                  
  return res;                                                                        
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "[[1, 2, 3], [4, 5, 6]]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[2, 5]\n", "weight": 0.5, "expected": "[2, 5]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[[10]]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[10]\n", "weight": 0.5, "expected": "[10]", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 10.00, '2026-07-31 06:46:50.099272+00', true, NULL);
INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (11925, 15867, NULL, NULL, 'struct Node {
    int data;
    Node* next;
};

int getMiddleNodeData(Node* head) {
    if (head == nullptr) return -1;
    Node* slow = head;
    Node* fast = head;
    while (fast != nullptr && fast->next != nullptr) {
        slow = slow->next;
        fast = fast->next->next;
    }
    return slow->data;
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "[1, 2, 3, 4, 5]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "3\n", "weight": 0.3, "expected": "3", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[1, 2, 3, 4]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "3\n", "weight": 0.4, "expected": "3", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "-1\n", "weight": 0.3, "expected": "-1", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"name": "Security", "type": "FORBID", "passed": true, "target": "security", "weight": 0, "description": "Security Policy Compliance"}, {"name": "Cyclomatic Complexity", "type": "SCORE", "earned": 30, "passed": true, "target": "complexity", "weight": 30, "description": "Complexity is 4. Penalty applied if > 15.", "actual_value": 4}]}}', 10.00, '2026-07-31 06:46:51.766256+00', true, NULL);
