INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (11111, 15011, NULL, NULL, '#include <vector>

std::vector<std::vector<int>> checkBoundaryStatus(const std::vector<std::vector<int>>& grid) {
    std::vector<std::vector<int>> res = grid;
    int rows = res.size();
    if (rows == 0) return res;
    int cols = res[0].size();
    for (int r = 0; r < rows; ++r) {
        for (int c = 0; c < cols; ++c) {
            bool isBoundary = (r == 0 || r == rows - 1 || c == 0 || c == cols - 1);
            if (!isBoundary) {
                if (res[r][c] == 5) res[r][c] = -1;
                else res[r][c] = -2;
            }
        }
    }
    return res;
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "[[1, 2, 3], [4, 5, 6], [7, 8, 9]]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[[1, 2, 3], [4, -1, 6], [7, 8, 9]]\n", "weight": 0.3, "expected": "[[1, 2, 3], [4, -1, 6], [7, 8, 9]]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[[1, 1], [1, 1]]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[[1, 1], [1, 1]]\n", "weight": 0.4, "expected": "[[1, 1], [1, 1]]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[[5, 5, 5], [5, -3, 5], [5, 5, 5]]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[[5, 5, 5], [5, -2, 5], [5, 5, 5]]\n", "weight": 0.3, "expected": "[[5, 5, 5], [5, -2, 5], [5, 5, 5]]", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 10.00, '2026-07-30 09:27:07.690977+00', true, NULL);
