#include <utility>

struct Node {
    int data;
    Node* next;
};

std::pair<Node*, Node*> splitListBySign(Node* source) {
    Node* posHead = nullptr;
    Node* negHead = nullptr;
    Node* posTail = nullptr;
    Node* negTail = nullptr;

    Node* curr = source;
    while (curr != nullptr) {
        Node* newNode = new Node{curr->data, nullptr};
        if (curr->data >= 0) {
            if (!posHead) posHead = posTail = newNode;
            else { posTail->next = newNode; posTail = newNode; }
        } else {
            if (!negHead) negHead = negTail = newNode;
            else { negTail->next = newNode; negTail = newNode; }
        }
        curr = curr->next;
    }
    return {posHead, negHead};
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "[1, -2, 3, -4]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "([1, 3], [-2, -4])\n", "weight": 0.3, "expected": "([1, 3], [-2, -4])", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[1, 2, 3]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "([1, 2, 3], [])\n", "weight": 0.4, "expected": "([1, 2, 3], [])", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "([], [])\n", "weight": 0.3, "expected": "([], [])", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 10.00, '2026-07-30 09:27:56.042962+00', true, NULL);
