    return listStr == target;
}', '{"feedback": "Passed 30% of the functional test suites.", "black_box": {"ratio": 0.3, "test_results": [{"input": "[''l'', ''i'', ''s'', ''t''], \"silent\"", "passed": false, "status": "Wrong Answer", "stderr": "PARSE_ERROR: input line did not match expected parameter types for this signature: [''l'', ''i'', ''s'', ''t''], \"silent\"\n", "stdout": "", "weight": 0.3, "expected": "false", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[''c'', ''a'', ''t''], \"act\"", "passed": false, "status": "Wrong Answer", "stderr": "PARSE_ERROR: input line did not match expected parameter types for this signature: [''c'', ''a'', ''t''], \"act\"\n", "stdout": "", "weight": 0.4, "expected": "true", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[], \"\"", "passed": true, "status": "Accepted", "stderr": "", "stdout": "true\n", "weight": 0.3, "expected": "true", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 0.3, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 3.00, '2026-07-30 09:28:19.371256+00', true, NULL);
INSERT INTO exam.student_answers (answer_id, submission_question_id, mcq_option_ids, tf_answer, code_answer, eval_result, question_grade, answered_at, is_submitted, submitted_at) VALUES (11160, 15060, NULL, NULL, '#include <vector>
#include <string>
#include <unordered_map>
#include <algorithm>

std::vector<std::string> sortWordsByAnagramGroup(const std::vector<std::string>& strs) {
    std::unordered_map<std::string, std::vector<std::string>> groups;
    for (const auto& s : strs) {
        std::string key = s;
        std::sort(key.begin(), key.end());
        groups[key].push_back(s);
    }
    std::vector<std::string> result;
    for (const auto& s : strs) {
        std::string key = s;
        std::sort(key.begin(), key.end());
        if (groups.count(key)) {
            for (const auto& item : groups[key]) {
                result.push_back(item);
            }
            groups.erase(key);
        }
    }
    return result;
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "[\"eat\", \"tea\", \"tan\", \"ate\", \"nat\", \"bat\"]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[\"eat\", \"tea\", \"ate\", \"tan\", \"nat\", \"bat\"]\n", "weight": 0.3, "expected": "[\"eat\", \"tea\", \"ate\", \"tan\", \"nat\", \"bat\"]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[\"a\"]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[\"a\"]\n", "weight": 0.4, "expected": "[\"a\"]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[]\n", "weight": 0.3, "expected": "[]", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 10.00, '2026-07-30 09:28:24.032375+00', true, NULL);
