int** allocateMatrix(int rows, int cols, int initialVal) {
    if (rows <= 0 || cols <= 0) return nullptr;
    int** matrix = new int*[rows];
    for (int r = 0; r < rows; ++r) {
        matrix[r] = new int[cols];
        for (int c = 0; c < cols; ++c) {
            matrix[r][c] = initialVal;
        }
    }
    return matrix;
}

void freeMatrix(int** matrix, int rows) {
    if (matrix == nullptr) return;
    for (int r = 0; r < rows; ++r) {
        delete[] matrix[r];
    }
    delete[] matrix;
}', '{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "2, 3, 9", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[[9, 9, 9], [9, 9, 9]]\n", "weight": 0.3, "expected": "[[9, 9, 9], [9, 9, 9]]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "1, 1, 0", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[[0]]\n", "weight": 0.4, "expected": "[[0]]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "0, 0, 0", "passed": true, "status": "Accepted", "stderr": "", "stdout": "nullptr\n", "weight": 0.3, "expected": "nullptr", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}', 10.00, '2026-07-30 09:28:41.162846+00', true, NULL);
