int main() {
    int n;
    if (std::cin >> n) {
        if (n <= 0) {
            std::cout << "cap:0";
            return 0;
        }
        int capacity = 1;
        while (capacity < n) {
            capacity *= 2;
        }
        int* arr = new int[capacity];
        for (int i = 0; i < n; ++i) {
            std::cin >> arr[i];
            std::cout << arr[i] << " ";
